(window.GIM_TS=window.GIM_TS||{})["Menachot.8"]={"from":192,"a":[["דיבר הכתוב בשיעור אמה של קרנות המזבח, \u0003לא שנא הכי\u0004 \u0005[אינו שונה\u0006 דווקא \u0005כך]\u0006 לענין גובהן של הקרנות, \u0003ולא שנא הכי\u0004 \u0005[ואינו שונה\u0006 דווקא \u0005כך]\u0006 לענין רוחב כניסתן של הקרנות, שבשניהם שיעור האמה הוא בחמישה טפחים.","ומעתה נאמר כך בתיאור מידות המזבח: גובהו של \u0003מזבח\u0004 (שהוא עשר אמות) \u0003כמה הוי\u0004 \u0005[הוא]?\u0006 שמונה מאמות גובהו הן בנות ששה טפחים, ואילו שתים מאמות גובהו (של אמת היסוד ושל הקרנות) הריהן בנות חמישה טפחים, נמצא סך גובהו \u0003חמשין ותמניא\u0004 \u0005[חמישים ושמונה]\u0006 טפחים. \u0003פלגיה\u0004 \u0005[חציו]\u0006 של גובה ה\u0003מזבח, כמה הוי\u0004 \u0005[הוא]\u0006 לפי זה? \u0003עשרין ותשעה\u0004 טפחים. \u0003מ\u0004שפת ה\u0003קרנות ועד\u0004 לגובה ה\u0003סובב כמה\u0004 טפחים \u0003הוו\u0004 \u0005[הם]?\u0006 \u0003עשרין ותלתא\u0004 \u0005[עשרים ושלושה],\u0006 חמישה טפחים של גובה הקרנות ועוד שלוש אמות בנות ששה טפחים, ובכללן עשרים ושלושה טפחים, ומעתה נשאל:","\u0003כמה\u0004 טפחים \u0003בציר\u0004 \u0005[חסר]\u0006 מגובה הסובב (עשרים ושלושה טפחים) \u0003לפלגיה\u0004 \u0005[לחציו]\u0006 של ה\u0003מזבח\u0004 (שהוא עשרים ותשעה טפחים)? \u0003שיתא\u0004 \u0005[ששה]\u0006 טפחים. \u0003ו\u0004אכן כך גם \u0003תנן\u0004 \u0005[שנינו]\u0006 בדינה של עולת העוף \u0005(כמובא בעמוד הקודם) ש\u0006\u0003אם\u0004 הכהן \u0003עשאה\u0004 (מיצה את דמה) במקום במזבח שהוא \u0003למטה מרגליו\u0004 של הכהן הניצבות בסובב, \u0003אפילו\u0004 עד כדי \u0003אמה אחת\u0004 — הריהי \u0003כשירה.\u0004 שהרי זה עדיין במחצית העליונה של המזבח, ונמצא שניתנו הדמים כהלכתם.","ומוסיפים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 הוא הסבר זה שניתן עתה לכתוב ביחזקאל, שכוונת הכתוב המתייחס לאמה שביסוד המזבח היא לגובהו, ואילו זה המתייחס לאמה שבסובב המזבח היא לרוחבו, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בכתוב לשונות שונים, שביחס ליסוד המזבח אחז הכתוב לשון \u0003\"חיק האמה\"\u0004 ואילו ביחס לסובב המזבח אמר הכתוב \u0003\"ואמה רחב\"\u0004 — להדגיש שזו אמת רוחב, בעוד הקודמת הריהי אמת גובה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא פירוש הפסוק.","למעלה (צז,א) הובאה מחלוקתם של ר' מאיר ור' יהודה, שלדעת ר' מאיר כל האמות היו בינוניות (חוץ משל מזבח הזהב ושל הקרן והסובב והיסוד של מזבח הנחושת), ולא פירש ר' מאיר בדבריו מהי \"אמה בינונית\". ולכך שואלים: \u0003ו\u0004בת \u0003כמה\u0004 טפחים היא \u0003אמה בינונית? אמר ר' יוחנן:\u0004 אמה בינונית היא בת \u0003ששה טפחים. אמר ר' יוסי בר אבין: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כן במשנתנו, שהרי שנינו בה ש\u0003ר' מאיר אומר\u0004 כי \u0003השלחן\u0004 עליו ערכו את לחם הפנים (שנאמר בכתוב שארכו שתי אמות. שמות כה, כג) \u0003ארכו\u0004 היה \u0003שנים עשר\u0004 טפחים, \u0003ורחבו\u0004 (שנאמר בכתוב שהוא אמה. שם) היה \u0003ששה\u0004 טפחים. והרי שסתם אמה (שלא נתפרש בה אחרת) הריהי בת ששה טפחים.","ושואלים: מתוך שמכונה אמה בת ששה טפחים \"אמה בינונית\", האם \u0003מכלל\u0004 הדברים יש להסיק \u0003דהויא\u0004 \u0005[שיש]\u0006 \u0003אמה דנפישא מינה\u0004 \u0005[שגדולה ממנה],\u0006 ויש בה יותר מששה טפחים? ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 יש אמה שכזו, \u0003והא תנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שתי אמות\u0004 (כלי מידה באורך אמה) \u0003היו בשושן הבירה\u0004 (מקום מיוחד מעל לשער המזרחי של הר הבית), \u0003אחת\u0004 מן האמות היתה מונחת \u0003על קרן מזרחית צפונית, ואחת\u0004 היתה מונחת \u0003על קרן מזרחית דרומית.\u0004 זו \u0003ש\u0004היתה \u0003על קרן מזרחית צפונית,\u0004 היתה \u0003יתירה על\u0004 האמה \u0003של משה\u0004 שהשתמש בה לצורך בניית המשכן, כדי \u0003חצי אצבע.\u0004 ואילו זו \u0003ש\u0004היתה \u0003על קרן מזרחית דרומית היתה יתירה עליה\u0004 על האמה הזו כדי \u0003חצי אצבע\u0004 נוספת. \u0003נמצאת\u0004 האמה היותר גדולה מביניהן \u0003יתירה על\u0004 האמה \u0003של משה\u0004 כדי \u0003אצבע.\u0004","\u0003ולמה אמרו\u0004 חכמים שתהיינה שתי אמות, \u0003אחת גדולה ואחת קטנה? כדי שיהו האומנין\u0004 (בעלי מלאכה) העושים מלאכה במקדש \u0003נוטלין ב\u0004חישוב שכרם, כך וכך דינרים לאמה לפי אמה \u0003קטנה,\u0004 האמה של משה. \u0003ומחזירין בגדולה,\u0004 כלומר, עושים בפועל לפי מידתה של אחת משתי אמות אלה, \u0003כדי שלא יבואו לידי מעילה,\u0004 שמא יטלו מן ההקדש יותר מן הראוי.","ושואלים: ולטעם זה \u0003ותרתי\u0004 \u0005[ושתי]\u0006 מידות שהיו בשושן הבירה היתירות על אמה של משה \u0003למה לי?\u0004 והלא די באחת! ומשיבים: \u0003חדא\u0004 \u0005[אחת]\u0006 הקטנה שביניהן, שהיתה על קרן מזרחית צפונית — \u0003ל\u0004מלאכת \u0003כספא ודהבא\u0004 \u0005[כסף וזהב],\u0006 שכיון שמלאכתם של אלה היא יקרה, והפסדם של האומנים גדול, אפילו בהפרש מועט. ולכך יתירה היא על מידת אמה של משה רק בחצי אצבע. \u0003ו\u0004אילו \u0003חדא\u0004 \u0005[אחת]\u0006 הגדולה שביניהן, יתירה על של משה באצבע שלימה, שהיתה על קרן מזרחית דרומית — \u0003ל\u0004מלאכת \u0003בניינא\u0004 \u0005[בנין]\u0006 אבן ועץ.","ומתוך שהוזכרה למעלה שושן הבירה שבשער המזרח, מוסיפים בענין זה. \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה במסכת מידות\u0005]\u0006 כי אחד מחמשת השערים שהיו בחומת הר הבית, היה \u0003שער המזרח\u0004 ש\u0003עליו שושן הבירה צורה\u0004 (מצויירת). ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 צוירה שושן הבירה על שער חומת הר הבית?","ומביאים שנחלקו בהסבר הדבר \u0003רב חסדא ורב יצחק בר אבדימי,\u0004 \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר\u0004 שהוא \u0003כדי שידעו\u0004 העוברים בשער זה \u0003מהיכן באו,\u0004 שבאו מגלות זו, ויודו למלכות פרס על שחרורם מעול גלות. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר\u0004 שהוא \u0003כדי ש\u0004בכל עת שיעברו בשער זה יזכרו במלכות פרס ו\u0003תהא אימת מלכות\u0004 פרס \u0003עליהן,\u0004 ולא יבואו למרוד בה.","ומביאים כי מעין \u0003זה\u0004 \u0003אמר רבי ינאי\u0004 כהנהגה הראויה: \u0003לעולם תהא אימת מלכות עליך, ש\u0004כך \u0003נ\u0004 \u0003אמר\u0004 לפרעה מלך מצרים על ידי משה, בהתראה על מכת בכורות: \u0003\"וירדו כל עבדיך אלה אלי והשתחוו לי\u0004 \u0003לאמר\u0004 צא אתה וכל העם אשר ברגליך ואחרי כן אצא...\" (שם יא, ח), \u0003שאמר משה כן על עבדיו של פרעה,\u0004 \u0003ואילו לדידיה\u0004 \u0005[לו,\u0006 לפרעה \u0005עצמו]\u0006 שכך הוא עצמו יעשה, \u0003לא קאמר ליה\u0004 \u0005[לא אמר לו],\u0006 מפני אימת המלכות שנהג בה.","\u0003ר' יוחנן אמר:\u0004 כך אכן ראוי לנהוג, ואולם המקור לכך הוא \u0003מהכא\u0004 \u0005[מכאן],\u0006 מהנהגתו של אליהו לפני אחאב מלך ישראל, \u0003ש\u0004כן \u0003נ\u0004 \u0003אמר: \"ויד ה' היתה אל אליהו וישנס מתניו וירץ לפני אחאב עד באכה יזרעאלה\"\u0004 (מלכים א יח, מו), שמפני כבוד המלכות עשה זאת.","ומתוך שהובאה מחלוקת רב חסדא \u0003ורב יצחק בר אבדימי מביאים מחלוקת נוספת שנחלקו בה חכמים אלה. נאמר בתיאור עצי הפרי אשר יגדלו בשני צידי הנחל שעתיד לצאת מבית המקדש\u0004 \"ועל הנחל יעלה על שפתו מזה ומזה כל עץ מאכל לא יבול עלהו ולא יתום פריו לחדשיו יבכר כי מימיו מן המקדש המה יוצאים והיה פריו למאכל \u0003ועלהו לתרופה\"\u0004 (יחזקאל מז, יב). ונחלקו \u0003רב חסדא ורב יצחק בר אבדימי\u0004 בפירוש הביטוי \"תרופה\" האמור בכתוב זה.","\u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר\u0004 שהכוונה \u0003להתיר פה\u0004 (\"תרופה\" — מתיר פה) \u0003ש\u0004מצוי \u0003למעלה,\u0004 בחלקו העליון של גוף האדם, בראש. שעלי עץ זה ישחררו את סוגרי פיהם של האלמים, שאינם יכולים לדבר בפיהם, ויוכלו מעתה לדבר. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר\u0004 שהכוונה \u0003להתיר פה\u0004 \u0003ש\u0004מצוי \u0003למטה,\u0004 בחלקו התחתון של גוף האדם, רחם האשה. שעליו של עץ זה יביאו את הנשים העקרות שתלדנה. ומביאים עוד מה ש\u0003איתמר\u0004 \u0005[נאמר]\u0006 שכיוצא בדבר נחלקו אמוראים אחרים בפירוש פסוק זה, ובלשון מפורשת יותר. ש\u0003חזקיה אמר\u0004 בפירוש הדברים: \u0003להתיר פה אלמים,\u0004 שיתחילו לדבר, ואילו \u0003בר קפרא אמר\u0004 בפירוש הדברים: \u0003להתיר פה עקרות,\u0004 שתלדנה.","ושבים לתיאור סדר עריכת לחם הפנים על השולחן. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הנאמר בלחם הפנים \"ולקחת סולת ואפית אותה \u0005שתים עשרה חלות שני עשרונים יהיה החלה האחת. ושמת אותם שתים מערכות שש המערכת על השולחן הטהור לפני ה' \" (ויקרא כד, ה—ו):\u0006 \u0003אילו\u0004 היה \u0003נאמר\u0004 בכתוב רק \u0003\"ולקחת סלת ואפית אתה שתים עשרה חלות\u0004 שני עשרונים יהיה החלה האחת. \u0003ושמת אותם שתים מערכות\", ולא\u0004 היה \u0003נאמר\u0004 בו המשך הכתוב \u0003\"שש\u0004 המערכת\" — \u0003הייתי אומר\u0004 שאינו חייב לעשות שתי מערכות של שש חלות, אלא יכול הוא לעשות מערכת \u0003אחת של ארבע\u0004 חלות, \u0003ו\u0004מערכת \u0003אחת\u0004 נוספת \u0003של שמונה\u0004 חלות, ואין הקפדה בדבר, שתהיינה שתי המערכות שוות זו לזו. \u0003לכך נאמר \"שש\u0004 המערכת\".","ומוסיפים: \u0003ואילו\u0004 היה \u0003נאמר\u0004 בכתוב רק \"ושמת אותם \u0003שתים מערכות שש המערכת\" ולא\u0004 היה \u0003נאמר\u0004 גם כן \u0003\"שתים עשרה\u0004 חלות\" — \u0003הייתי אומר\u0004 שמספרן הכולל של החלות אינו שתים עשרה אלא אף יותר, ולא בא הכתוב \"שש המערכת\" אלא לומר שמלבד שתי המערכות (שבכל אחת מהן יש שש חלות) יכול להביא עוד שש חלות, ונמצא שהוא מביא שמונה עשרה חלות, \u0003שלש\u0004 מערכות \u0003של שש שש\u0004 חלות בכל אחת. \u0003לכך נאמר \"שתים עשרה\".\u0004","ומוסיפים: \u0003ואילו\u0004 היה \u0003נאמר\u0004 בכתוב רק \"ואפית אותה \u0003שתים עשרה חלות\u0004 שני עשרונים... ושמת אותם \u0003מערכות\u0004 המערכת על השולחן הטהור...\", \u0003ולא\u0004 היה \u0003נאמר\u0004 גם כן \u0003\"שתים\" ו\"שש\"\u0004 — \u0003הייתי אומר\u0004 ששתים עשרה החלות הללו תתחלקנה ל\u0003שלשה\u0004 מערכות, \u0003של\u0004 \u0003ארבע ארבע\u0004 חלות כל אחת. \u0003לכך נאמר\u0004 אף \u0003\"שתים\u0004 מערכות\", \u0003ו\"שש\u0004 המערכת\". \u0003הא\u0004 \u0005[הרי]\u0006 למדנו מכאן כי \u0003עד\u0004 (כל עוד) \u0003שלא יאמרו שלשה מקראות הללו לא למדנו\u0004 איך צריך לעשות.","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 נוהגים בפועל בעריכת לחם הפנים על השולחן? \u0003נותן שתים מערכות של שש שש\u0004 חלות בכל אחת מהמערכות. \u0003ואם\u0004 עבר ו\u0003נתן\u0004 מערכת \u0003אחת של ארבע\u0004 חלות, \u0003ו\u0004מערכת \u0003אחת של שמונה\u0004 חלות — \u0003לא יצא\u0004 ידי חובה. ואם הוסיף שתי חלות ונתן \u0003שתים\u0004 מערכות \u0003של שבע שבע\u0004 חלות בכל אחת מהן. \u0003רבי אומר: רואין את העליונה,\u0004 החלה שניתנה אחרונה נוסף לשש החלות של מצוה, \u0003כאילו\u0004 היא \u0003אינה,\u0004 וכשר. ומקשים על כך: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שתהא הלבונה מונחת על גבי לחם הפנים וכפי שנאמר \u0003\"ונתת על\u0004 המערכת לבונה זכה והיתה ללחם לאזכרה....\" (שם ז), ואילו באופן זה, נמצא שיש חלת חולין המפסיקה בין הלבונה לבין לחמי הפנים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב המנונא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב המנונא לרב חסדא\u0004 בתשובה לשאלה זו: \u0003רבי\u0004 הולך בהלכה זו שלימדנו, \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003אומר\u0004 רבי בפירוש המלה \u0003\"על\"\u0004 האמורה בכתוב \"ונתת על המערכת לבונה זכה\" שאין משמעה על ממש, אלא \u0003בסמוך.\u0004 ומאחר והלבונה נתונה בסמוך ללחמי הפנים אין בחלה זו המונחת למעלה כדי לחצוץ. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003רבי אומר\u0004 כי פירוש האמור בכתוב \u0003\"ונתת על המערכת לבנה זכה\"\u0004 כוונת המלה \u0003\"על\"\u0004 הריהי \u0003בסמוך,\u0004 ולא על ממש. ומוכיח רבי את דבריו: \u0003אתה אומר\u0004 כי משמע הלשון \u0003\"על\"\u0004 הריהו \u0003בסמוך, או\u0004 שמא משמעו \u0003אינו אלא על ממש? כשהוא\u0004 הכתוב \u0003אומר\u0004 \u0003\"וסכת על הארן את הפרכת\"\u0004 (שמות מ, ג), והרי הפרוכת ודאי איננה נתונה על הארון ממש, אלא חוצצת בין הקודש לבין קודש הקדשים, אלא ודאי \u0003הוי אומר\u0004 כי משמע המלה \u0003\"על\"\u0004 הריהו \u0003בסמוך,\u0004 ולא על ממש.","שנינו במשנתנו ש\u0003כל הכלים שבמקדש\u0004 היה אורכן נתון לאורכו של בית המקדש, מן המזרח למערב. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא כי \u0003כל הכלים שבמקדש\u0004 היה \u0003ארכן\u0004 נתון \u0003לארכו של\u0004 ה\u0003בית, חוץ מ\u0004ה\u0003ארון ש\u0004היה \u0003ארכו\u0004 נתון לא לאורכו של בית המקדש אלא \u0003לרחבו של\u0004 ה\u0003בית,\u0004 מצפון לדרום. \u0003וכך היה\u0004 הארון \u0003מונח, וכך היה בדיו מונחין.\u0004","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא,\u0006 התנא שבברייתא זו \u0005אומר],\u0006 מה כוונת הדברים במשפט האחרון? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003כך היה\u0004 הארון \u0003מונח\u0004 דווקא לרוחב בית המקדש, \u0003מ\u0004כיון שעל ידי כך נמצא \u0003ש\u0004\u0003בדיו\u0004 של הארון (הנמצאים ברוחבו) \u0003כך היה מונחין\u0004 לאורכו של הבית.","ושואלים: \u0003ובדיו מנלן\u0004 \u0005[מנין לנו]\u0006 שכך היו מונחים, לאורך הבית, ממזרח למערב? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הנאמר בבית המקדש שבנה שלמה המלך \"ויביאו הכהנים את ארון ברית ה' אל מקומו אל דביר הבית אל קודש הקדשים אל תחת כנפי הכרובים... \u0003ויארכו הבדים\u0004 ויראו ראשי הבדים מן הקודש על פני הדביר ולא יראו החוצה...\" (מלכים א ח, ו—ח) — \u0003יכול לא היו\u0004 הבדים \u0003נוגעין בפרוכת\u0004 כלל? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"ויראו\".\u0004 ומן הצד האחר, יש לשאול: \u0003אי\u0004 \u0005[אם]\u0006 מן הכתוב \u0003\"ויראו\"\u0004 — \u0003יכול\u0004 ש\u0003יהו\u0004 הבדים נוגעים ו\u0003מקרעין בפרוכת ויוצאין\u0004 החוצה? לכך \u0003תלמוד לומר\u0004 \"ו\u0003לא יראו החוצה\". הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 יוסברו שני הלשונות הללו?"],["הבדים היו \u0003דוחקין\u0004 אל תוך הפרוכת, \u0003ובולטין בפרוכת,\u0004 ולא יוצאים מחוצה לה. \u0003ו\u0004היו הבדים שבפרוכת \u0003דומין כמין שני דדי אשה\u0004 שניכרת בליטתם דרך בגדיה, \u0003ש\u0004כן \u0003נ\u0004 \u0003אמר\u0004 בדימוי זה \u0003\"צרור המר דודי לי בין שדי ילין\"\u0004 (שיר השירים א, יג). והרי שהיו הבדים מונחים לארכו של הבית.","ושואלים: \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 שאכן \u0003בדיו\u0004 של הארון \u0003לפותיא\u0004 \u0005[לרוחבו]\u0006 של ה\u0003ארון הוו יתבי\u0004 \u0005[היו ישובים,\u0006 מונחים\u0005],\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לארכו\u0004 של ה\u0003ארון הוו יתבי\u0004 \u0005[היו ישובים],\u0006 ואף הארון היה מונח לאורך המקדש ולא לרוחבו! \u0003אמר ר' יהודה:\u0004 אי אפשר היה לעשות כן, שהרי רוחבו של הארון אמה וחצי, ואם היו הבדים נתונים לאורכו של הארון, נמצא ששני נושאי הארון שבצידו זה של הארון ושני נושאיו שבצידו השני היו עומדים בין הבדים, לרוחבו של הארון — דבר שאינו אפשרי, שכן \u0003תרי גברי\u0004 \u0005[שני אנשים]\u0006 העומדים זה אחרי זה \u0003ב\u0004מקום שכל גודלו הוא \u0003אמתא ופלגא\u0004 \u0005[אמה וחצי]\u0006 \u0003לא מסתגי להו\u0004 \u0005[אינם יכולים ללכת].\u0006 ואולם כאשר הבדים נתונים לרוחבו של הארון, נמצא ששני נושאי הארון שבכל צד היו עומדים בין הבדים לאורכו של הארון ברווח, שהרי אורכו אמתיים וחצי.","ומסבירים: \u0003ומנא לן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003בארבעה\u0004 אנשים \u0003הוו דרו להו\u0004 \u0005[היו נושאים אותו,\u0006 את הארון\u0005]?\u0006 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בסדר נשיאת הארון על ידי בני קהת \"ונסעו הקהתים נושאי המקדש והקימו את המשכן עד בואם\" (במדבר י, כא), ויש בפסוק זה פעמיים לשון רבים: האחד, \u0003\"ונסעו הקהתים\"\u0004 — ללמד כי הם \u0003תרי\u0004 \u0005[שנים]\u0006 הנושאים את הארון, והשני, \u0003\"נשאי המקדש\"\u0004 — ללמד \u0003נמי תרי\u0004 \u0005[גם כן\u0006 כי \u0005שנים]\u0006 נושאים את הארון, שארבעה הם הנושאים את הארון\u0005.\u0006","ועוד בענין מעשה שולחן הפנים שבמקדש. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003עשרה שולחנות\u0004 (מלבד שולחן הפנים שעשה משה במשכן) \u0003עשה שלמה המלך, ש\u0004כן \u0003נאמר\u0004 בתיאור מעשה המקדש שעשה שלמה: \u0003\"ויעש שלחנות עשרה וינח בהיכל חמשה מימין וחמשה משמאול\"\u0004 (דברי הימים ב ד, ח).","\u0003ו\u0004מסבירים: \u0003אם\u0004 \u0003תאמר\u0004 שהכוונה היא שהיו \u0003חמשה\u0004 שולחנות \u0003מימין הפתח\u0004 של ההיכל (ובצידו הצפוני של ההיכל. שהרי פתח ההיכל היה בצידו המזרחי של ההיכל, באמצעו), \u0003וחמשה\u0004 השולחנות האחרים היו \u0003משמאל הפתח\u0004 של ההיכל (ובצידו הדרומי) — אין לומר כך, שהרי אם כך אתה אומר \u0003אם כן מצינו\u0004 (מצאנו) איפוא \u0003ש\u0004ה\u0003שולחן\u0004 (חמשת השולחנות שמשמאל לפתח) היה מונח \u0003בדרום\u0004 ההיכל, \u0003ו\u0004אילו \u0003התורה אמרה\u0004 באשר למקומו של השולחן \u0003\"והשלחן תתן על צלע צפון\"\u0004 (שמות כו, לה)!","\u0003אלא\u0004 הכוונה ב\"ימין\" ו\"שמאל\" להשמיענו כי שולחן הפנים \u0003של משה\u0004 היה מונח \u0003באמצע\u0004 חלקו הצפוני של ההיכל, ומעשרת השולחנות הנוספים שעשה שלמה, היו \u0003חמשה\u0004 שולחנות \u0003מימינו\u0004 של שולחן משה, \u0003וחמשה\u0004 האחרים היו \u0003משמאלו\u0004 של שולחן משה, ואולם כולם היו בצפון ההיכל.","ובדומה לעשרת השולחנות הנוספים שעשה שלמה, עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נוסף למנורת הזהב שעשה משה היו בבית המקדש \u0003עשר מנורות\u0004 זהב ש\u0003עשה שלמה, ש\u0004כן \u0003נ\u0004 \u0003אמר\u0004 בתיאור המקדש שעשה שלמה: \u0003\"ויעש את מנורות הזהב עשר כמשפט ויתן בהיכל\u0004 \u0003חמשה מימין ו\u0004\u0003חמשה משמאול\"\u0004 (דברי הימים שם ז).","\u0003ו\u0004כדרך שהוסבר למעלה לענין השולחנות, כן גם לענין המנורות מסבירים: \u0003אם\u0004 \u0003תאמר\u0004 שהכוונה שהיו \u0003חמשה\u0004 מנורות עומדות \u0003מימין הפתח\u0004 (ובצידו הצפוני של ההיכל), \u0003ו\u0004\u0003חמשה\u0004 מנורות \u0003משמאל הפתח\u0004 (ובצידו הדרומי) של ההיכל — אין לומר כך, שהרי \u0003אם כן\u0004 אתה אומר \u0003מצינו\u0004 איפוא ש\u0003מנורה\u0004 (חמש המנורות שמימין הפתח) עומדת \u0003בצפון\u0004 ההיכל, \u0003ו\u0004אילו \u0003התורה אמרה\u0004 באשר למקומה של \u0003המנורה \"ושמת את השולחן מחוץ לפרוכת\u0004 \u0003ואת המנורה נכח\u0004 \u0003השלחן\u0004 על צלע המשכן תימנה והשולחן תתן על צלע צפון\" (שמות שם), הרי שהמנורה נמצאת בצידו הדרומי של ההיכל (\"צלע תימנה\") מול השולחן הנמצא בצידו הצפוני של ההיכל (\"צלע צפון\")!","\u0003אלא\u0004 הכוונה ב\"ימין\" ו\"שמאל\" להשמיענו כי המנורה שעשה \u0003של משה\u0004 היתה עומדת \u0003באמצע\u0004 חלקו הדרומי של ההיכל, ומעשר המנורות הנוספות שעשה שלמה, היו \u0003חמשה\u0004 עומדות \u0003מימינה\u0004 של מנורת משה, \u0003וחמשה\u0004 האחרות היו עומדות \u0003משמאלה\u0004 של מנורת משה, ואולם כולן בדרום ההיכל.","למעלה הובאו ברייתות בעניינם של עשרת השולחנות ועשר המנורות הנוספים שעשה שלמה. ועוד בעניינם של אלה מובאות שתי ברייתות העוסקות בענין מקומם במקדש. \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 האומרת כי השולחנות והמנורות הללו \u0003מחצי בית ולפנים\u0004 (בחציו הפנימי, מכיוון מזרח למערב, של בית המקדש) \u0003היו מונחין. ותני חדא\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחת]\u0006 האומרת כי \u0003משליש הבית ולפנים\u0004 (בשליש הפנימי של בית המקדש) \u0003היו מונחין,\u0004 והרי זו סתירה!","\u0003ו\u0004מתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שאין \u0005הברייתות חלוקות ביניהן אלא בלשון, שכן\u0006 \u0003מר\u0004 \u0005[חכם זה]\u0006 שבברייתא האומרת שמקומם של השולחנות והמנורות הללו היה משליש הבית ולפנים, \u0003קא חשיב\u0004 \u0005[הריהו מחשיב]\u0006 את \u0003בית קדשי הקדשים\u0004 (שאורכו עשרים אמה, ממזרח למערב) \u0003בהדי\u0004 \u0005[יחד עם]\u0006 ה\u0003היכל\u0004 (שאורכו ארבעים אמה, ממזרח למערב), ששניהם נקראים בלשונו \"בית\". ונמצא איפוא שאורך שניהם ששים אמה, והשליש הפנימי הינו איפוא עשרים אמה הפנימיות של ההיכל. ואילו \u0003מר\u0004 \u0005[חכם זה]\u0006 שבברייתא הראשונה האומרת כי מקומם של השולחנות והמנורות הללו היה בחצי הבית ולפנים, \u0003לא קא חשיב\u0004 \u0005[אינו מחשיב]\u0006 את \u0003בית קדשי הקדשים בהדי\u0004 \u0005[יחד עם]\u0006 ה\u0003היכל,\u0004 שאין נקרא בלשונו \"בית\" אלא ההיכל, ומחציתו של ההיכל \u0003(שאורכו ארבעים אמה) הן עשרים אמה הפנימיות. ונמצא שלדעת שתי הברייתות היו השולחנות והמנורות הללו בעשרים האמה הללו.\u0004","ועוד בעניין עשרת השולחנות שעשה שלמה בבית המקדש. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: כל השולחנות שעשה שלמה מכיוון \u0003מזרח ו\u0004כלפי \u0003מערב היו מונחין,\u0004 שהיה אורכם של השולחנות לאורכו של המקדש, ממזרח למערב, וכפי שהיה מונח השולחן במשכן. אלו \u0003דברי רבי. ר' אלעזר בר' שמעון אומר:\u0004 כל השולחנות היו מונחים מכיוון \u0003צפון ו\u0004כלפי \u0003דרום,\u0004 שהיה אורכם של השולחנות לרוחבו של המקדש, מצפון לדרום. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מקור השיטה\u0005]\u0006 של \u0003רבי\u0004 שהיו השולחנות עומדים בין מזרח למערב? \u0003גמר\u0004 \u0005[למד]\u0006 דבר זה \u0003מ\u0004השוואת השולחנות ל\u0003מנורה: מה\u0004 ה\u0003מנורה\u0004 עומדת בין \u0003מזרח ומערב, אף הני נמי\u0004 \u0005[אלה גם כן,\u0006 השולחנות\u0005]\u0006 עומדים בין \u0003מזרח ומערב.\u0004","ושואלים: \u0003ומנורה גופה מנלן\u0004 \u0005[עצמה מנין לנו]\u0006 שכך היא עומדת? \u0003מדכתיב\u0004 \u0005[מ\u0006מה \u0005שנאמר]\u0006 \u0003בנר\u0004 ה\u0003מערבי\u0004 שבמנורה \"מחוץ לפרוכת העדות באוהל מועד \u0003יערך אתו אהרן\u0004 מערב עד בוקר \u0003לפני ה'\u0004 תמיד חוקת עולם לדורותיכם\" (ויקרא כד, ג), ומן ההדגשה בנר זה כי הוא הנמצא \"לפני ה' \" (הקרוב ביותר לבית קודש הקדשים) —","\u0003מכלל דכולהו\u0004 \u0005[מכאן\u0006 נסיק \u0005שכולם,\u0006 שאר הנרות \u0005שבמנורה\u0006\u0005]\u0006 \u0003לאו\u0004 \u0005[אינם]\u0006 נחשבים \u0003\"לפני ה' \"\u0004ביחס לנר המערבי. והרי זה בודאי משום שהמנורה עומדת בהיכל בין מזרח למערב, והנר היותר מערבי שבה (\"נר מערבי\"), קרוב יותר לבית קודש הקדשים. \u0003ו\u0004בודאי כך הוא, שכן \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שהמנורה היתה עומדת בין \u0003צפון ודרום,\u0004 אם כן נמצא כי \u0003כולהו נמי\u0004 \u0005[כולם,\u0006 כל נרות המנורה, \u0005גם כן]\u0006 בשווה \u0003\"לפני ה' \" נינהו\u0004 \u0005[הם]\u0006 עומדים, ולא נבדל הנר המערבי בכך משאר הנרות.","\u0003ור' אלעזר בר' שמעון מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור לשיטתו\u0005]\u0006 שהיו השולחנות עומדים בין צפון לדרום? \u0003גמר\u0004 \u0005[למד]\u0006 דבר זה \u0003מ\u0004השוואת השולחנות ל\u0003ארון: מה\u0004 ה\u0003ארון\u0004 מונח בין \u0003צפון ודרום, אף הני נמי\u0004 \u0005[אלה גם כן]\u0006 עומדים בין \u0003צפון ודרום.\u0004 ושואלים: \u0003ורבי נמי ליגמר\u0004 \u0005[גם כן שילמד]\u0006 את דין השולחנות \u0003מארון?\u0004 ומשיבים: הוא סבור ש\u0003דנין\u0004 (למדים בהיקש) דינו של כלי מקדש הנמצא בהיכל מ\u0003חוץ\u0004 לקודש הקדשים (כשולחנות), מכלי מקדש הנמצא אף הוא \u0003מחוץ\u0004 לקודש הקדשים (כמנורה), \u0003ואין דנין\u0004 דינו של כלי מקדש הנמצא מ\u0003חוץ\u0004 לקודש הקדשים (כשולחנות) \u0003מ\u0004כלי מקדש הנמצא \u0003בפנים\u0004 קודש הקדשים (כארון).","ומצד שני שואלים: \u0003ור' אלעזר בר' שמעון ליגמר\u0004 \u0005[שילמד]\u0006 את דין השולחנות \u0003ממנורה,\u0004 כדרך שלמד רבי, ומדוע מעדיף הוא ללמוד את דינם מארון? ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר\u0006\u0003]\u0004 \u0003לך\u0004 ר' אלעזר בר' שמעון בתשובה לשאלה זו כי אף ה\u0003מנורה גופה\u0004 \u0005[עצמה]\u0006 בין \u0003צפון ודרום הוה מנחה\u0004 \u0005[היתה מונחת],\u0006 וכדרך שהיה הארון מונח.","ומקשים על כך: \u0003אלא הכתיב\u0004 \u0005[הרי נאמר]\u0006 בנר המערבי שבמנורה \u0003\"יערך אתו אהרן ובניו\u0004 לפני ה' \", והרי זה מלמד שהוא בלבד הקרוב לקודש הקדשים, ואין זה אפשרי אלא כאשר המנורה עומדת ממזרח למערב! ומשיבים: לדעת ר' אלעזר בר' שמעון, אף שהמנורה עומדת מצפון לדרום, עדיין הנר המערבי שבה הוא שהיה מופנה לקודש הקדשים, שכן הכהן המדליק את המנורה היה \u0003מצדד להו אצדודי\u0004 \u0005[מפנה אותם,\u0006 את נרות המנורה \u0005לצדדים\u0006 שונים\u0005].\u0006 ואת הנר המערבי היה מפנה כלפי קודש הקדשים.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור במצות הדלקת המנורה \"בהעלותך את הנרות \u0003אל מול פני המנורה יאירו שבעת הנרות\"\u0004 (במדבר ח, ב) — \u0003מלמד שהיו מצדדין\u0004 שאר הנרות שבמנורה את \u0003פניהם כלפי נר אמצעי,\u0004 שהנרות שמצידיו של \u0003הנר האמצעי היו פונים לעברו.\u0004 \u0003אמר ר' נתן: מכאן\u0004 למדים \u0003ש\u0004הנר ה\u0003אמצעי\u0004 הוא ה\u0003משובח.\u0004 ודנים בשיטות הללו ביחס לדרך העמדת השולחנות.","\u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005זה שאומר,\u0006 רבי\u0005]\u0006 כי השולחנות היו מונחים בין \u0003מזרח ומערב\u0004 — \u0003היינו דהוו יתיבי\u0004 \u0005[זהו,\u0006 מובן הוא איך \u0005שהיו ישובים,\u0006 מונחים\u0005]\u0006 \u0003עשרה\u0004 שולחנות \u0003ב\u0004מקום שאורכו הוא \u0003עשרים\u0004 אמות, שהרי אורכו של כל שולחן הוא שתי אמות. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005זה שאומר,\u0006 ר' אלעזר בר' שמעון\u0005]\u0006 כי השולחנות עומדים בין \u0003צפון ודרום\u0004 — תמוה הוא: \u0003עשרה\u0004 שולחנות, שאורכם הכולל הוא מעט יותר מעשרים אמה \u0003ב\u0004תוך \u0003עשרים\u0004 אמה מדוייקות (שהוא רוחב ההיכל, שמצפון לדרום) \u0003היכי הוו יתבי\u0004 \u0005[איך היו ישובים,\u0006 מונחים\u0005]\u0006?","\u0003ותו\u0004 \u0005[ועוד]\u0006 קשה לשיטה זו: ה\u0003כהנים\u0004 הגדולים, הנכנסים לקודש הקדשים ביום הכיפורים, \u0003היכי הוו עיילי\u0004 \u0005[איך היו נכנסים]\u0006 אל קודש הקדשים דרך ההיכל, אם כל רוחבו של ההיכל היה חסום על ידי עשרת השולחנות הללו? \u0003ותו\u0004 \u0005[ועוד]\u0006 קשה לשיטה זו, שלפיה \u0003מצינו\u0004 (מצאנו) שהיו \u0003חמשה שלחנות\u0004 מבין העשרה עומדים \u0003ב\u0004צד \u0003דרום\u0004 של ההיכל, והרי הורתה התורה (כמובא למעלה) כי מקום השולחנות הוא בצפון ההיכל ולא בדרומו! \u0003ותו\u0004 \u0005[ועוד]\u0006 קשה: לשיטה זו הסבורה שעשרת השולחנות הללו שעשה שלמה מילאו את כל רוחב ההיכל, ה\u0003שלחן\u0004 שעשה \u0003משה היכא מנח ליה\u0004 \u0005[היכן היה מניח אותו]?\u0006","ודוחים את דברי המקשה: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 המקשה על האומר שבין צפון לדרום היו מונחים השולחנות, והרי אף \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005זה שאומר]\u0006 שבין \u0003מזרח ומערב\u0004 היו מונחים השולחנות \u0003נמי\u0004 \u0005[גם כן]\u0006 יש לשאול: ה\u0003שלחן\u0004 שעשה \u0003משה היכא הוה מנח ליה\u0004 \u0005[היכן היה מניח אותו],\u0006 שהרי עשרת השולחנות העומדים לאורך המקדש תפסו עשרים אמה לעצמם, \u0005שהוא כל חציו הפנימי של ההיכל, והיכן היה מקומו של שולחן משה, שעמד באמצעם של עשרת השולחנות?\u0006","\u0003אלא\u0004 על כורחך יש לומר, \u0003מי סברת חד דרא הוה\u0004 \u0005[האם סבור אתה\u0006 כי \u0005שורה אחת\u0006 של שולחנות \u0005היתה],\u0006 שכולם היו עומדים זה אחר זה?! לא כך היה הדבר, אלא \u0003תרי דרי נינהו\u0004 \u0005[שתי שורות\u0006 של שולחנות \u0005הן],\u0006 ובאופן שהיה מקום לכל השולחנות (ובכללם שולחנו של משה) בחציו הפנימי של ההיכל, ורווח לכהנים להיכנס ביניהם מן ההיכל לבית קודש הקדשים. אלא לשיטתי היו עומדים בין צפון לדרום\u0005.\u0006"],["ומוסיפים ודנים בשיטות הללו. \u0003בשלמא למאן דאמר\u0004 \u0005[נניח,\u0006 הדבר מובן, \u0005ל\u0006שיטת \u0005זה שאומר]\u0006 שהשולחנות היו מונחים בין \u0003צפון ודרום\u0004 — \u0003שפיר\u0004 \u0005[יפה,\u0006 ברור\u0005]\u0006 הוא כיצד היה מתבצע בו זמנית סידורו של לחם הפנים החדש וסילוקו של לחם הפנים הישן. שכן שני כהנים המסדרים את הלחם החדש היו עומדים בצידו האחד של השולחן, ושני כהנים אחרים המסלקים באותו זמן את הלחם הישן היו עומדים כנגדם בצידו השני. ומשסיימו יצאו אלו ואלו אל מחוץ להיכל. ולשיטה זו שהיו השולחנות עומדים בין צפון לדרום, היו אם כן הכהנים המסדרים עומדים משני צידיו בחציו הצפוני של ההיכל למזרחו ולמערבו, ודי באותו מקום לצורך הכהנים שמשני צידיו של השולחן.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005זה שאומר,\u0006 רבי\u0005]\u0006 כי השולחנות היו מונחים בין \u0003מזרח ומערב\u0004 והכהנים המסדרים עומדים משני צידיו לצפון ולדרום, \u0003מכדי\u0004 \u0005[הרי]\u0006 ה\u0003שלחן כמה\u0004 אמות היה \u0003משוך\u0004 (מרוחק) \u0003מן הכותל\u0004 הצפוני של ההיכל? \u0003שתי אמות ומחצה\u0004 (שהוא המקום הנדרש להילוכם של שני אנשים), \u0003ו\u0004על כך יש להוסיף עוד \u0003אמה\u0004 שהיא רוחב \u0003דידיה\u0004 \u0005[שלו עצמו,\u0006 של שורת חמשת השולחנות הצפוניים יותר\u0005],\u0006 \u0003ו\u0004עוד יש להוסיף על כך \u0003שתי אמות ומחצה דביני ביני\u0004 \u0005[שבין לבין],\u0006 בין שורת חמשת השולחנות הצפוניים לבין שולחנו של משה, שאף זה נזקק \u0005לשטח זה כדי הילוך שני אנשים.\u0006","\u0003ו\u0004עוד יש להוסיף \u0003אמה\u0004 שהיא רוחבו של שולחן משה, \u0003ו\u0004עוד יש להוסיף \u0003שתי אמות ומחצה דביני ביני\u0004 \u0005[שבין לבין],\u0006 בין שולחנו של משה לשורת חמשת השולחנות הדרומיים, \u0003ו\u0004עוד \u0003אמה\u0004 שהיא רוחבו \u0003דידיה\u0004 \u0005[שלו עצמו,\u0006 של שורת חמשת השולחנות הדרומיים\u0005]\u0006 — נמצא סך הכל עולה עשר וחצי אמות, ומעתה \u0003אישתכח דקאכיל\u0004 \u0005[נמצא שאוכל,\u0006 שנכנס\u0005]\u0006 ה\u0003שולחן\u0004 בשיעור של \u0003פלגא דאמתא\u0004 \u0005[חצי אמה]\u0006 \u0003ב\u0004תוך חלק \u0003דרום\u0004 של ההיכל, והרי מקומו של השולחן הוא בצפון ההיכל, ולא בדרומו!","ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שה\u0003שלחן\u0004 של \u0003משה בהדייהו הוה יתיב\u0004 \u0005[יחד איתם,\u0006 במקביל לעשרת שולחנות של שלמה, \u0005היה ישוב,\u0006 מונח\u0005]?!\u0006 \u0003לא\u0004 כך היה, אלא \u0003דמידלי ליה\u0004 \u0005[מוגבה היה]\u0006 משולחנות שלמה. שהיה השולחן של משה גבוה משאר השולחנות, שנתון היה לצד השולחנות של שלמה לכיוון מערב של המקדש שהוא מקום גבוה יותר (שהרי מקום המקדש היה משתפע ממערב למזרח) \u0003ו\u0004שם \u0003מנח ליה\u0004 \u0005[מניח אותו],\u0006 \u0003ומיתתי להו לדידהו פורתא\u0004 \u0005[ומוריד אותם,\u0006 את שולחנות שלמה מתחתיו, \u0005מעט],\u0006 שהיו נראים השולחנות הללו ביחס לשולחנו של משה, \u0003כתלמיד היושב לפני רבו,\u0004 מתחתיו. ובאופן זה אין רוחב שולחנו של משה מצטרף לרוחבם של שתי שורות השולחנות, והיו כל השולחנות מונחים בחלקו הצפוני של ההיכל.","ועוד מעניינם של השולחנות והמנורות שעשה שלמה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003עשרה שלחנות עשה שלמה\u0004 נוסף על שולחן הפנים שעשה משה במדבר. \u0003ו\u0004אולם \u0003לא היו מסדרין\u0004 במקדש את לחם הפנים \u0003אלא על\u0004 שולחנו \u0003של משה\u0004 בלבד. \u0003ש\u0004כן \u0003נאמר:\u0004 \u0003\"ויעש שלמה את כל הכלים אשר בית ה' את מזבח הזהב\u0004 \u0003ואת השלחן אשר עליו לחם הפנים זהב\"\u0004 (מלכים א ז, מח), ומכאן שלא היה אלא שולחן אחד עליו היה ניתן לחם הפנים.","וכמו כן \u0003עשר מנורות\u0004 זהב \u0003עשה שלמה\u0004 במקדש, \u0003ו\u0004אולם \u0003לא היו מדליקין\u0004 במקדש \u0003אלא ב\u0004מנורה \u0003של משה. ש\u0004כן \u0003נאמר\u0004 \"ומקטירים לה' עולות בבוקר בבוקר ובערב בערב וקטורת סמים ומערכת לחם על השולחן הטהור ו\u0003מנורת הזהב ונרתיה לבער בערב\u0004 בערב...\" (דברי הימים ב יג, יא), ומכאן שלא היתה אלא מנורה אחת בה הודלקו נרות המקדש.","ואילו \u0003ר' אלעזר בן שמוע\u0004 חולק ו\u0003אומר\u0004 כי \u0003על\u0004 כל השולחנות \u0003כולם היו מסדרין\u0004 את לחם הפנים, \u0003ש\u0004כן \u0003נאמר\u0004 \"ויעש שלמה את כל הכלים אשר בית האלקים ואת מזבח הזהב ו\u0003את השלחנות ועליהם לחם הפנים\"\u0004 (דברי הימים ב ד, יט), ומכאן שניתן לחם הפנים על כל השולחנות שבמקדש. \u0003ו\u0004כן \u0003ב\u0004כל המנורות \u0003כולן\u0004 שהיו במקדש \u0003היו מדליקין,\u0004 שכן \u0003נאמר\u0004 בהמשך הפסוק הקודם \u0003\"את המנרות ונרתיהם לבערם כמשפט לפני הדביר זהב סגור\"\u0004 (שם כ).","\u0003ר' יוסי בר' יהודה אומר: לא היו מסדרין\u0004 את הלחם \u0003אלא על\u0004 השולחן \u0003של משה, אלא מה אני מקיים\u0004 (כיצד אני מסביר) את הכתוב \u0003\"ואת השלחנות אשר עליהם לחם הפנים... זהב\"? אלו שלשה\u0004 ה\u0003שלחנות שהיו במקדש: שנים שהיו\u0004 עומדים \u0003באולם\u0004 שלפני ההיכל \u0003מבפנים\u0004 האולם \u0003לפתח הבית\u0004 (ההיכל): שולחן \u0003אחד\u0004 — \u0003של כסף, ו\u0004שולחן \u0003אחד\u0004 — \u0003של זהב.\u0004","\u0003על\u0004 השולחן \u0003של כסף\u0004 היה הכהן \u0003נותן\u0004 את \u0003לחם הפנים\u0004 החדש, המוכנס להיכל, לאחר שנאפה \u0003בכניסתו\u0004 להיכל, שמתקרר עליו הלחם מעט מחום התנור. \u0003ו\u0004היו מניחים את הלחם הישן, שהוסר מעל שולחן הפנים \u0003על\u0004 השולחן \u0003של זהב ביציאתו\u0004 מההיכל, עד שיוקטרו בזיכי הלבונה. ולא היה מונח על של כסף, כשולחן שבכניסתו, \u0003ש\u0004כלל הוא: \u0003מ\u0004\u0003עלין\u0004 בהנהגת חשיבות \u0003ב\u0004דבר שהוא \u0003קודש, ולא מורידין\u0004 בהנהגת חשיבות בו. ולאחר שהיה הלחם נתון (כל השבוע) על שולחן הפנים שהוא מזהב, אין מניחים אותו על שולחן הפחות בערכו. \u0003ו\u0004מלבד שני שולחנות אלה, היה עוד שולחן \u0003אחד של זהב,\u0004 ושולחן זה היה \u0003בפנים\u0004 (בתוך ההיכל), \u0003שעליו\u0004 נתון \u0003לחם הפנים תמיד.\u0004 הוא הנקרא \"שולחן הפנים\".","ושואלים: \u0003ומנא לן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003אין מורידין\u0004 בקודש? \u0003אמר רבי:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויקם משה את המשכן ויתן את אדניו וישם את קרשיו ויתן את בריחיו ויקם את עמודיו\"\u0004 (שמות מ, יח), ומכאן למדים שכיון שמשה (המקודש משאר אחיו) החל לעשות את המשכן וכליו, שוב לא עשו זאת אחרים, שכן יש בדבר משום הורדה בקודש.","\u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003מ\u0004\u0003עלין\u0004 בקודש? \u0003אמר ר' אחא בר יעקב:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 במאתים וחמשים האנשים (בני עדתו של קרח) מקטירי הקטורת במחתות שנאכלו באש: \"אמור אל אלעזר בן אהרן הכהן וירם את המחתות מבין השריפה ואת האש זרה הלאה כי קדשו. \u0003את מחתות החטאים האלה בנפשתם ועשו אתם רקעי פחים צפוי למזבח כי הקריבם לפני ה' ויקדשו ויהיו לאות לבני ישראל\"\u0004 (במדבר יז, ב— ג) — ש\u0003בתחילה\u0004 בזמן שניתנה בהן הקטורת היתה קדושתן של המחתות כקדושת \u0003תשמישי מזבח\u0004 (ששימשו להקטרת הקטורת), \u0003ועכשיו\u0004 שנעשו לציפוי למזבח, העלו אותן בקדושתן, לכלל קדושת \u0003גופו של מזבח.\u0004","ומתוך ששנינו ענין שאין מורידים בקודש, מביאים בענין דומה. נאמר בלוחות הברית הראשונים שנשברו \u0003\"אשר שברת ושמתם בארון\"\u0004 (דברים י, ב) — \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 בפירוש כתוב זה: \u0003מלמד שהלוחות\u0004 השניים \u0003ו\u0004כן \u0003שברי\u0004 ה\u0003לוחות\u0004 הראשונים הריהם \u0003מונחין בארון.\u0004 ו\u0003מכאן\u0004 הוראת דרך הנהגה הנוגעת \u0003ל\u0004עניינו של \u0003תלמיד חכם ששכח תלמודו מחמת אונסו,\u0004 כגון מחמת חולי, \u0003שאין נוהגין בו מנהג בזיון,\u0004 שהרי אף שברי לוחות מונחים בתוך ארון הברית.","כיון שהובאו דבריו אלה של רב יוסף, מביאים מאמרותיו של ריש לקיש בעניינים הדומים לכך, ובתחילה מציינים \u0003סימן\u0004 לזכרון הדברים הבאים: \u0003ביטל\u0004 (המבטל תורה לצורך מצוה), \u0003סרח\u0004 (תלמיד חכם שסרח), \u0003ושכח\u0004 (תלמיד חכם ששכח תלמודו).","ומפרטים: \u0003אמר ריש לקיש: פעמים\u0004"],["יש \u0003ש\u0004נחשב \u0003ביטולה של תורה\u0004 כעושה מעשה ש\u0003זהו יסודה\u0004 (בניין והרחבה) של התורה. וכגון שמפסיק הלומד תורה מלימודו לצורך הלויית המת ולהכנסת כלה. וראיה לדבר, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 למשה, לאחר \u0005שבירת הלוחות הראשונים \"...וכתבתי על הלוחות את הדברים אשר היו על הלוחות הראשונים\u0006 \u0003אשר שברת\"\u0004 (שמות לד, א), שכך \u0003אמר לו הקדוש ברוך הוא למשה: יישר\u0004 (\"אשר\") \u0003כחך ששברת,\u0004 ששבירה זו של התורה היא שהביאה את ייסודן של הלוחות השניים.","\u0003ו\u0004עוד \u0003אמר ריש לקיש: תלמיד חכם שסרח\u0004 (שחטא) — \u0003אין מבזין אותו בפרהסיא, ש\u0004כן \u0003נאמר: \"וכשלת היום וכשל גם נביא עמך לילה\"\u0004 (הושע ד, ה) ואמר הכתוב כי כשלונו של הנביא הוא בלילה, להורות שתלמיד חכם שכשל — \u0003כסהו כלילה,\u0004 שלא יהא הדבר נודע \u0003לרבים משום שיש בזה בזיון לתורה.\u0004","\u0003ו\u0004עוד \u0003אמר ריש לקיש: כל המשכח דבר אחד מתלמודו\u0004 — \u0003עובר ב\u0004כך על איסור \u0003לאו\u0004 (לא תעשה). \u0003ש\u0004כן \u0003נאמר\u0004 לאחר קבלת התורה במעמד הר סיני \"רק \u0003השמר לך ושמר נפשך מאד פן תשכח את\u0004 \u0003הדברים\u0004 אשר ראו עיניך ופן יסורו מלבבך כל ימי חייך...\" (דברים ד, ט). \u0003ו\u0004מנין שלשון הכתוב מורה על איסור לאו — \u0003כ\u0004דברי \u0003ר' אבין\u0004 ש\u0003אמר\u0004 בשם \u0003ר' אילעא.\u0004 שכך \u0003אמר ר' אבין, אמר ר' אילעא: כל מקום שנאמר\u0004 בתורה לשון \u0003\"השמר\"\u0004 או \u0003\"פן\"\u0004 או \u0003\"אל\"\u0004 — \u0003אינו אלא\u0004 מצות \u0003לא תעשה.\u0004","\u0003רבינא אמר:\u0004 כיון שנאמר בפסוק זה הן לשון \u0003\"השמר\" ו\u0004הן לשון \u0003\"פן\"\u0004 — צריך לומר כי השוכח דבר מלימודו \u0003שני לאוין נינהו\u0004 \u0005[הם]\u0006 שעבר עליהם. \u0003רב נחמן בר יצחק אמר: בשלשה לאוין\u0004 הוא עובר, \u0003ש\u0004כן \u0003נאמר\u0004 בפסוק זה \u0003\"השמר לך ושמר נפשך מאד פן תשכח את הדברים\"\u0004 — הרי איפוא ישנם בכתוב זה שתי לשונות שמירה (\"השמר\", \"ושמור\"), וכן לשון \"פן\", והרי אלה שלוש מצוות לא תעשה.","ומבררים: \u0003יכול\u0004 עבר אדם על \u0003איסור זה של שכחת התורה\u0004 \u0003אפילו\u0004 אם שכח \u0003מחמת אונסו?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בכתוב \u0003\"ופן יסורו מלבבך\"\u0004 — רק \u0003ב\u0004זה ש\u0003מסירם מלבו\u0004 מרצונו ומדעתו, \u0003הכתוב מדבר. ר' דוסתאי בר' ינאי אמר: יכול\u0004 שעבר אדם על שכחת התורה \u0003אפילו\u0004 אם \u0003תקפה עליו משנתו,\u0004 שהיה קשה לו לזכור? לכך \u0003תלמוד לומר\u0004 בכתוב \u0003\"רק\"\u0004 — למעט מכלל איסור מי שאינו יכול לזכור.","ועוד בענין שמירת התורה, \u0003ר' יוחנן ור' אלעזר דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 דבר אחד: ה\u0003תורה ניתנה בארבעים\u0004 יום, שעלה משה לשמים לקבלה. \u0003ו\u0004אף ה\u0003נשמה\u0004 שבאדם \u0003נוצרה בארבעים\u0004 יום, שרק אחרי ארבעים יום ליצירתו, הוולד נחשב כמי שיש בו נשמה. ללמדנו ש\u0003כל המשמר תורתו\u0004 — אף \u0003נשמתו משתמרת, וכל שאינו משמר את התורה\u0004 — \u0003אין נשמתו משתמרת.\u0004","בענין זה \u0003תנא דבי\u0004 \u0005[שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: משל לאדם שמסר צפור דרור לעבדו,\u0004 לשומרה. ו\u0003אמר\u0004 לו: \u0003כמדומה אתה שאם אתה מאבדה\u0004 — \u0003שאני נוטל ממך איסר\u0004 (מטבע קטנה) \u0003בדמיה\u0004 של ציפור זו שאבדת? לא כך הוא, אלא \u0003את\u0004 \u0003נשמתך אני נוטל ממך\u0004 כעונש על כך. ואף זה שאינו משמר את התורה שבידו, ומאבדה — עונשו מרובה וחמור.","ועוד בתיאור סדר עריכת לחם הפנים על השולחן. \u0003שני שולחנות היו\u0004 עומדים \u0003באולם\u0004 שלפני ההיכל \u0003מבפנים\u0004 האולם \u0003על פתח הבית\u0004 (ההיכל): שולחן \u0003אחד\u0004 — \u0003של שייש, ו\u0004שולחן \u0003אחד\u0004 — \u0003של זהב. על\u0004 השולחן \u0003של שייש\u0004 היו הכהנים \u0003נותנים\u0004 את \u0003לחם הפנים\u0004 החדש, המוכנס להיכל, לאחר שנאפה \u0003בכניסתו\u0004 להיכל, כדי שיתקרר הלחם מעט מחום התנור על ידי אבן השיש, ולא יתעפש. \u0003ועל\u0004 שולחן \u0003של זהב\u0004 היו מניחים את הלחם הישן, שהוסר מעל שולחן הפנים \u0003ביציאתו\u0004 מההיכל, והיה מונח שם עד שיוקטרו בזיכי הלבונה.","וטעם הדבר שהיה השולחן, עליו מונח עליו הלחם הישן, של זהב (ולא של שיש, כשולחן עליו הונח בכניסתו, ואף לא של כסף) — \u0003ש\u0004כלל הוא: \u0003מעלין\u0004 בהנהגת חשיבות \u0003ב\u0004דבר שהוא \u0003קודש, ולא מורידין\u0004 בחשיבותו. ולאחר שהיה הלחם נתון (כל השבוע) על שולחן הפנים שהוא מזהב, אין מניחים אותו במקדש על שולחן הפחות בערכו. \u0003ו\u0004מלבד שני שולחנות אלה, היה עוד שולחן \u0003אחד\u0004 העשוי מ\u0003של זהב,\u0004 ושולחן זה היה \u0003מבפנים\u0004 (בתוך ההיכל), \u0003שעליו\u0004 נתון \u0003לחם הפנים תמיד.\u0004 הוא הנקרא \"שולחן הפנים\".","\u0003ו\u0004כך הוא סדר עריכת לחם הפנים באופן שעל השולחן תמיד יהיה לחם הפנים: בכל יום שבת \u0003ארבעה כהנים נכנסין\u0004 פנימה להיכל, \u0003שנים\u0004 מהכהנים הללו נושאים \u0003בידם\u0004 את \u0003שני\u0004 ה\u0003סדרים\u0004 (מערכות) לחם הפנים, שש חלות בכל מערכת, \u0003ו\u0004ה\u0003שנים\u0004 האחרים נושאים \u0003בידם שני בזיכין\u0004 (כפות) של לבונה. \u0003וארבעה\u0004 כהנים אחרים \u0003מקדימין\u0004 להיכנס להיכל \u0003לפניהם, שנים\u0004 מארבעת הכהנים הללו באים \u0003ליטול\u0004 מעל השולחן את \u0003שני\u0004 ה\u0003סדרים\u0004 של לחם הפנים הישן המוסר עתה, \u0003ו\u0004ה\u0003שנים\u0004 האחרים באים \u0003ליטול\u0004 את \u0003שני\u0004 ה\u0003בזיכין\u0004 של הלבונה הנתונים סמוך ללחם הפנים המוסר עתה.","הכהנים \u0003המכניסים\u0004 עתה את הלחם החדש ואת הלבונה \u0003עומדים ב\u0004צד \u0003צפון\u0004 (שקדושתו גדולה משל צד דרום) של שולחן הפנים, \u0003ופניהם ל\u0004כיוון \u0003דרום.\u0004 שכן גדולה מצוותם של כהנים אלה, בהכנסת הלחם החדש. \u0003ו\u0004אילו הכהנים \u0003ה\u0004\u0003מוציאין\u0004 עתה את הלחם הישן \u0003עומדים ב\u0004צד \u0003דרום\u0004 של השולחן, \u0003ופניהם ב\u0004כיוון \u0003צפון.\u0004 וכך הריהם עושים במלאכתם באותה עת: \u0003אלו\u0004 המוציאים את הלחם הישן \u0003מושכין\u0004 אותו אל מחוץ לשולחן, \u0003ו\u0004באותה שעה \u0003אלו\u0004 המכניסים את הלחם החדש \u0003מניחין\u0004 אותו על השולחן. \u0003ו\u0004נעשה הדבר באופן זה ש\u0003טפחו\u0004 (שיעור טפח) \u0003של\u0004 לחם \u0003זה\u0004 היוצא מהשולחן היה \u0003כנגד טפחו של\u0004 לחם \u0003זה\u0004 הנכנס לשולחן, ובאופן זה, מעולם לא חסר לחם על השולחן, לקיים מה \u0003שנאמר\u0004 \"ונתת על השולחן לחם פנים \u0003לפני תמיד\"\u0004 (שמות כה, ל).","\u0003ר' יוסי אומר:\u0004 לא היתה חובה לנהוג דווקא כך בסידור לחם הפנים, אלא \u0003אפילו\u0004 אם \u0003אלו\u0004 הכהנים המוציאים את הלחם הישן \u0003נוטלין\u0004 בתחילה את הלחמים כולם מעל השולחן, \u0003ו\u0004לאחר מכן \u0003אלו\u0004 הכהנים המכניסים את הלחם החדש \u0003מניחין\u0004 אותו על השולחן — \u0003אף היא היתה\u0004 נקראת \"לפני \u0003תמיד\",\u0004 שהרי לא עבר השולחן לילה בלא לחם הפנים עליו.","וממשיכים בסדר הדברים הנעשים בלחם הפנים: \u0003יצאו\u0004 הכהנים עם שתים עשרה חלות הלחם הישן, \u0003ונתנום על שלחן הזהב שהיה באולם.\u0004 לאחר מכן \u0003הקטירו\u0004 על המזבח את \u0003ה\u0004לבונה שהיתה נתונה ב\u0003בזיכין\u0004 שהוסרו מהלחם הישן, \u0003ו\u0004לאחר מכן \u0003החלות\u0004 \u0003מתחלקות\u0004 לאכילה \u0003לכהנים\u0004 של משמר הכהנים המסיים עתה ביום השבת את שבוע העבודה שלו (\"היוצא\") ולכהנים של משמר הכהנים המתחיל עתה את שבוע העבודה שלו במקדש (\"הנכנס\").","אם \u0003חל יום\u0004 ה\u0003כיפורים להיות ב\u0004יום ה\u0003שבת,\u0004 שאי אפשר לאכול את החלות באותו יום — \u0003החלות מתחלקות לערב,\u0004 במוצאי שבת, לכשיסתיים צום הכיפורים. והלכה נוספת בענין דומה: אם \u0003חל\u0004 יום הכיפורים \u0003להיות בערב שבת\u0004 — קרבן \u0003שעיר\u0004 החטאת \u0003של יום הכפורים,\u0004 הנאכל לכהנים — \u0003נאכל\u0004 רק \u0003לערב\u0004 הבא, במוצאי יום הכיפורים שהוא ליל שבת (שכן זמן אכילתו של קרבן זה אינו אלא ביום הקרבתו ובלילה שלאחר מכן, עד חצות). \u0003ו\u0004מאחר ואין אפשרות לבשל את הקרבן (שהרי הוקרב ביום הכיפורים, ומשיצא יום הכיפורים נכנס יום השבת), \u0003הבבליים\u0004 (כהנים שעלו מבבל), \u0003אוכלין אותו\u0004 (את בשר הקרבן) \u0003כשהוא חי\u0004 (לא מבושל), ומסוגלים הם לאכול כך, \u0003מפני שדעתן יפה,\u0004 כלומר, שלא היו איסטניסים במאכלם.","שנינו במשנתנו כי סבור ר' יוסי שאף אם מוציאים בתחילה את לחם הפנים הישן ולאחר מכן מכניסים את לחם הפנים החדש — אף זה נחשב כקיומו של האמור בלחם הפנים שיהיה \"תמיד\" על השולחן. ובענין זה מביאים עוד, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 ש\u0003ר' יוסי אומר\u0004 כי \u0003אפילו\u0004 אם \u0003סילק\u0004 מעל שולחן הפנים \u0003את\u0004 מערכות הלחם \u0003הישנה\u0004 ב\u0003שחרית\u0004 (בוקר) של יום השבת, \u0003וסידר את החדשה\u0004 ב\u0003ערבית\u0004 של יום השבת — \u0003אין בכך כלום,\u0004 שאין הלחם נפסל בכך. \u0003אלא\u0004 ב\u0003מה\u0004 (באיזה אופן) \u0003אני מקיים\u0004 (מסביר) את הציווי האמור בלחם הפנים שיהיה \u0003\"לפני תמיד\"?\u0004 לומר: \u0003שלא ילין\u0004 (יעבור לילה) על \u0003שלחן\u0004 הפנים \u0003בלא\u0004 שיהיה עליו \u0003לחם.\u0004","\u0003אמר ר' אמי: מדבריו\u0004 אלה \u0003של ר' יוסי\u0004 האומר כי \"תמיד\" הריהו נחשב אף שלא היה הדבר ברצף זמן גמור, ודי במקצת זמן בשחרית ובערבית להחשיב הדבר כ\"תמיד\", \u0003נלמוד\u0004 גם ש\u0003אפילו לא שנה אדם אלא פרק אחד\u0004 של משנה ב\u0003שחרית\u0004 היום \u0003ופרק אחד\u0004 של משנה ב\u0003ערבית\u0004 היום — \u0003קיים\u0004 בכך את \u0003מצות \"לא ימוש ספר התורה הזה מפיך\u0004 והגית בו יומם ולילה\" (יהושע א, ח).","וכיוצא בדבר \u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחי: אפילו לא קרא אדם\u0004 בתורה \u0003אלא קרית\u0004 (קריאת) \u0003שמע\u0004 ב\u0003שחרית ו\u0004קריאת שמע ב\u0003ערבית\u0004 — \u0003קיים \"לא ימוש\", ו\u0004אולם \u0003דבר זה אסור לאומרו בפני עמי הארץ,\u0004 שלא יחשבו שבכך בלבד הם יוצאים ידי חובת לימוד התורה. \u0003ו\u0004אילו \u0003רבא אמר:\u0004 להיפך, \u0003מצוה\u0004 היא \u0003לאומרו בפני עמי הארץ,\u0004 שיבינו מתוך כך מה גדול הוא שכרם של הלומדים תורה יומם ולילה, ולא רק בזמנים קצרים ביום ובלילה.","ובענין זה מסופר כי \u0003שאל בן דמה, בן אחותו של ר' ישמעאל, את ר' ישמעאל: כגון אני, שלמדתי\u0004 את \u0003כל התורה כולה, מהו\u0004 דיני לענין \u0003ללמוד חכמת יונית,\u0004 האם מותר אני בה? \u0003קרא עליו\u0004 ר' ישמעאל את \u0003המקרא הזה \"לא ימוש ספר התורה הזה מפיך והגית בו יומם ולילה\".\u0004 ועתה שנאמר בכתוב במצות לימוד התורה שהיא ביום ובלילה, \u0003צא ובדוק\u0004 (חפש) \u0003שעה שאינה לא מן היום ולא מן הלילה, ולמוד בה חכמת יונית.\u0004","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוק]\u0006 ר' ישמעאל בכך על דעת \u0003ר' שמואל בר נחמני,\u0004 ש\u0003אמר ר'\u0004 \u0003שמואל בר נחמני, אמר ר' יונתן: פסוק זה\u0004 (\"והגית בו יומם ולילה\") \u0003אינו לא חובה ולא מצוה, אלא ברכה.\u0004 ועניינה של ברכה זו שהתברך בה יהושע: ש\u0003ראה הקדוש ברוך הוא את יהושע שדברי תורה חביבים עליו ביותר, ש\u0004כך \u0003נאמר\u0004 ביהושע \u0003\"ומשרתו יהושע בן נון נער לא ימיש מתוך האהל\"\u0004 (שמות לג, יא), \u0003אמר לו הקדוש ברוך הוא: יהושע, כל כך חביבין עליך דברי תורה?\u0004 מברכך אני ש\u0003לא ימוש ספר התורה הזה מפיך.\u0004","ומביאים עוד מדברי חכמים במצות לימוד התורה. \u0003תנא דבי\u0004 \u0005[שנה\u0006 ה\u0005חכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: דברי תורה לא יהו עליך חובה,\u0004 שתחוש שחייב אתה לעסוק בהם \u0003בתור מחוייבות,\u0004 \u0003ו\u0004מצד שני \u0003אי אתה רשאי לפטור עצמך מהן.\u0004","\u0003אמר\u0004 החכם \u0003חזקיה:\u0004 \u0003מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005זה\u0006 \u0005שנאמר]\u0006 \u0003\"ואף הסיתך מפי צר רחב לא מוצק תחתיה\"\u0004 (איוב לו, טז)? \u0003בוא וראה שלא כמדת\u0004 (הנהגת) \u0003הקדוש ברוך הוא מדת בשר ודם. מדת בשר ודם\u0004 היא \u0003ש\u0004\u0003אדם מסית\u0004 (מפתה) \u0003את חבירו\u0004 לדבר שיש בו העברה \u0003מדרכי חיים לדרכי מיתה. ו\u0004אילו \u0003הקדוש ברוך הוא מסית את האדם מדרכי מיתה לדרכי חיים, ש\u0004כן \u0003נאמר \"ואף הסיתך מפי צר\"\u0004 כלומר, הקדוש ברוך הוא מסיתך לצאת \u0003מגיהנם, שפיה צר, שעשנה צבור\u0004"],["\u0003בתוכה. ושמא תאמר: כשם שפיה\u0004 של גיהנום \u0003צר, כך כולה צרה\u0004 — לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בתיאור הגיהנום (\"תפתה\"): \"כי ערוך מאתמול תפתה גם היא \u0003למלך הוכן\u0004 \u0003העמיק הרחב\u0004 מדרתה אש ועצים הרבה נשמת ה' כנחל גפרית בוערה בה\" (ישעיהו ל, לג), שהיא עצמה עמוקה ורחבה.","\u0003ושמא תאמר\u0004 כי רק לאנשים פשוטים ערוכה היא הגיהנום, אבל לחשובים כ\u0003למלך\u0004 \u0003לא הוכנה\u0004 — לכך \u0003תלמוד לומר\u0004 בכתוב זה \u0003\"גם היא למלך הוכן\". ו\u0004עדיין \u0003שמא תאמר\u0004 כי \u0003אין בה עצים\u0004 — לכך \u0003תלמוד לומר\u0004 בכתוב זה \u0003\"מדרתה אש ועצים הרבה\". ושמא תאמר\u0004 כי רק \u0003זה\u0004 (ההצלה מהגיהנום) \u0003הוא שכרה\u0004 של התורה ולא יותר — לכך \u0003תלמוד לומר\u0004 \"יחלץ עני בעניו \u0003ויגל בלחץ אזנם. ואף הסיתך מפי צר לא מוצק תחתיה\u0004 \u0003ונחת שלחנך מלא דשן\"\u0004 (איוב לו, טו— טז), שהאדם השומע בקול ה', ופונה מדרכי מיתה לדרכי חיים, שניצול מן הגיהנום ואף זוכה למלוא נחת ורווחה.","שנינו במשנתנו שאם \u0003חל יום הכיפורים להיות ב\u0004יום ה\u0003שבת\u0004 — אוכלים את לחם הפנים במוצאי שבת. ואם חל יום הכיפורים בערב שבת — שעיר יום הכיפורים נאכל בליל שבת. ונמסר עוד במשנתנו כי במקרה שכזה היו הבבליים אוכלים את בשר השעיר כשהוא חי, מפני שדעתם יפה. ובענין זה \u0003אמר רבה בר בר חנה, אמר ר' יוחנן: לא בבליים\u0004 (הבאים מבבל) ממש \u0003הם\u0004 אותם הכהנים, \u0003אלא אלכסנדריים\u0004 (הבאים מאלכסנדריה שבמצרים) \u0003הם, ומתוך ששונאין\u0004 בארץ ישראל \u0003את\u0004 ה\u0003בבליים\u0004 — \u0003קורין\u0004 (קוראים) הם אף \u0003אותם\u0004 את האלכסנדריים, הנוהגים מנהג רעבתניים \u0003על שם\u0004 ה\u0003בבליים.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' יוסי אומר: לא בבליים הם\u0004 אלה הכהנים האוכלים את בשר השעיר כשהוא חי, \u0003אלא אלכסנדריים הם. ומתוך ששונאין את\u0004 ה\u0003בבליים\u0004 — \u0003קוראין\u0004 הם \u0003אותן על שם בבליים. אמר לו ר' יהודה\u0004 לר' יוסי, לאחר ששמעו מסביר כך את האמור במשנתנו, בלשון תודה: \u0003תנוח\u0004 עליך \u0003דעתך\u0004 (שתזכה למנוחת הדעת) על \u0003שהנחת\u0004 בדבריך אלה את \u0003דעתי,\u0004 להשמיעני שאין הבבליים עצמם נוהגים כך (שכן היה מוצא משפחתו של ר' יהודה מבבל).","אם \u0003סידר\u0004 הכהן \u0003את הלחם\u0004 (לחם הפנים) כמצוותו \u0003ב\u0004יום ה\u0003שבת ו\u0004אולם לא סידר \u0003את הבזיכין\u0004 בהם הלבונה ביום השבת כמצוותם \u0003אלא\u0004 \u0003לאחר השבת, והקטיר את ה\u0004לבונה שב\u0003בזיכין\u0004 הללו \u0003בשבת\u0004 הבאה, לאחר שהסיר את הלחם מעל שולחן הפנים — \u0003פסול\u0004 הלחם מלהיאכל, שכן הבזיכים שעמו לא היו אתו על השולחן בשבעת הימים שבין שבת לשבת. ומאחר שאין הקטרתם מתירה את הלחם להיאכל, \u0003אין חייבין עליהן\u0004 \u0003משום\u0004 איסור \u0003פיגול\u0004 (אם חשב בשעת הקטרת הבזיכים לאכול את הלחם שלא בזמן אכילתו, למחרת השבת), וכן משום \u0003נותר\u0004 (אם נותר מן הלחם למחרת השבת, ואכלו), \u0003ו\u0004כן משום \u0003טמא\u0004 (אם אכל את הלחם בטומאת הגוף). שאין איסורים אלה נוהגים אלא בהקטרה המתירה את הלחם לאכילה.","ואם \u0003סידר את הלחם ואת הבזיכין\u0004 כמצוותם הראויה, \u0003ב\u0004יום \u0003שבת\u0004 זה, \u0003ו\u0004אולם \u0003הקטיר את ה\u0004לבונה שב\u0003בזיכין\u0004 הללו \u0003רק\u0004 \u0003לאחר\u0004 יום \u0003השבת\u0004 הבא — \u0003פסולה\u0004 היא הקטרה זו, והלחם אינו מותר באכילה (שהרי ביום השבת, לא היתה הקטרת בזיכים), \u0003ו\u0004משום שהקטרה זו פסולה, \u0003אין חייבין עליהן משום פיגול נותר וטמא.\u0004","ואם \u0003סידר את הלחם ואת הבזיכין\u0004 לא ביום השבת עצמו, כמצוותו, אלא \u0003לאחר\u0004 יום \u0003השבת, והקטיר את הבזיכין ב\u0004יום ה\u0003שבת\u0004 הבא — \u0003פסולה\u0004 היא הקטרה זו, והלחם פסול (שכן לא שהה על שולחן הפנים שבעה ימים, משבת לשבת). \u0003כיצד יעשה\u0004 שלא ייפסלו הלחם והבזיכים שנסדרו למחרת השבת? לא יסלק את הלחם ואת הבזיכים בשבת הקרובה, אלא \u0003יניחנה לשבת הבאה\u0004 לאחר מכן, ונמצא שעבר על הלחם ועל הבזיכים שהות של לפחות שבעה ימים משבת לשבת על שולחן הפנים, והותרו בכך. ומסבירים: מותר להשאיר על השולחן את הלחם והבזיכים מעבר לשבעת ימים, \u0003ש\u0004הרי \u0003אפילו היא\u0004 מונחת \u0003על השולחן ימים רבים\u0004 — \u0003אין בכך כלום,\u0004 ואין זה נפסל.","שנינו בסוף משנתנו שניתן להשאיר על שולחן הפנים את הלחם והבזיכים יותר משבעה ימים, ואפילו ימים רבים, ואין הם נפסלים בכך בלינה. ולבירור ענין זה מביאים: \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה במסכת יומא\u0005]\u0006 בתיאור סדר עבודת יום הכיפורים, \u0003אמר להם הממונה\u0004 לכהנים: \u0003\"צאו\u0004 ועמדו על מקום גבוה במקדש, \u0003וראו\u0004 משם \u0003אם\u0004 כבר האיר היום ו\u0003הגיע זמן שחיטה\"\u0004 (שכן השחיטה פסולה בלילה). \u0003אם\u0004 כבר \u0003הגיע\u0004 הזמן — \u0003הרואה\u0004 את אור היום \u0003אומר:\u0004 \u0003\"ברקאי\"\u0004 — הבריק האור. ומעירים כי \u0003מתתיא בן שמואל,\u0004 שהיה הממונה באותו זמן על הפייסות במקדש, היה חולק על דעה זו, ו\u0003אומר\u0004 בלשון אחר: \"האם \u0003האיר פני כל\u0004 \u0003המזרח, עד\u0004 כדי כך \u0003ש\u0004הוא, האור, נראה אף \u0003בחברון\"\u0004 (והוא אור הגדול מ\"ברקאי\")? \u0003ו\u0004אם אכן כך היה, \u0003הוא\u0004 (הצופה) היה \u0003אומר: \"הן\". ו\u0004מסבירים:","\u0003למה הוצרכו\u0004 חכמים \u0003לכך,\u0004 להתקין שיעלה צופה ויבדוק היטב אם האיר היום, שהרי הוא לכאורה דבר הנראה לעין בכל מקום? — משום \u0003שפעם אחת\u0004 אירע ש\u0003עלה מאור הלבנה, ודימו\u0004 (חשבו בטעות) \u0003שהאיר\u0004 ה\u0003מזרח\u0004 בזריחת השמש, ו\u0003שחטו את\u0004 קרבן \u0003התמיד\u0004 לפני זמנו. \u0003ו\u0004כשגילו שהיה זה עדיין לילה, ונשחט התמיד בלילה, ונפסל בכך — \u0003הוציאוהו לבית השריפה,\u0004 כדין הקדשים שנפסלו. וכדי להמנע מטעות כגון זו, תיקנו חכמים שלעולם יהיו בודקים היטב אם זרחה כבר השמש.","\u0003ו\u0004\u0003לאחר שהיו מודיעים על תחילת היום,\u0004 \u0003הורידו\u0004 את ה\u0003כהן\u0004 ה\u0003גדול לבית הטבילה\u0004 קודם שיתחיל בעבודת היום. ומסבירים את עניינה של הטבילה לכהנים העובדים במקדש, \u0003זה הכלל היה\u0004 נוהג \u0003במקדש: כל המסיך את רגליו\u0004 (עושה צרכים גדולים) — \u0003הריהו\u0004 \u0003טעון טבילה\u0004 לאחר מכן, \u0003וכל המטיל מים\u0004 (עושה צרכים קטנים) — הריהו \u0003טעון קדוש\u0004 (רחיצת) \u0003ידים ורגלים\u0004 לאחר מכן.","ובענין ההלכה ששנינו במשנה כי קרבן התמיד שנשחט לפני עלות השחר פסול וצריך לשורפו, \u0003תני אבוה\u0004 \u0005[שנה אביו]\u0006 של \u0003ר' אבין\u0004 בברייתא: \u0003לא זו בלבד\u0004 אמרו חכמים שכך היא הלכה בשחיטת קרבן בהמה בלילה, \u0003אלא אפילו עולת העוף שנמלקה בלילה\u0004 ולא ביום, \u0003ומנחה שנקמצה בלילה\u0004 ולא ביום — פסולות הן, ו\u0003תצא לבית\u0004 השריפה. שלענין זה, דין המליקה בעוף והקמיצה במנחה כדין השחיטה בבהמה.","ושואלים על הלכה זו שבברייתא: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003עולת העוף\u0004 שנמלקה בלילה ולא ביום, הריהי נשרפת — \u0003משום\u0004 שכבר נמלקה עולת העוף, ומעתה \u0003לא אפשר\u0004 שוב \u0003לאהדורה\u0004 \u0005[להחזירה]\u0006 למצבה הקודם, שקודם מליקתה. וכיון שנפסלה במליקת לילה, הריהי נשרפת. \u0003אלא מנחה\u0004 שנקמצה בלילה, מדוע הריהי נשרפת, והרי \u0003אפשר דמהדר\u0004 \u0005[שיחזיר]\u0006 הכהן את ה\u0003קומץ\u0004 שנקמץ בלילה \u0003לדוכתיה\u0004 \u0005[למקומו]\u0006 הקודם במנחה (שעדיין קיימת היא, שהרי לא הוקטר הקומץ) ויחזור \u0003וקמיץ ביממא\u0004 \u0005[ויקמוץ ביום]!\u0006","ואומרים: \u0003הוא\u0004 אביו של ר' אבין זה ש\u0003תני לה\u0004 \u0005[שנה אותה,\u0006 את הברייתא הזו\u0005],\u0006 \u0003והוא\u0004 זה ש\u0003אמר לה\u0004 \u0005[אותה,\u0006 את התשובה לשאלה זו\u0005]:\u0006 אף הקמיצה שנעשתה בלילה אינה ניתנת שוב לתיקון, משום ש\u0003כלי שרת מקדשין\u0004 את הדברים הניתנים בהם אף \u0003שלא בזמנן\u0004 הראוי. ולכך, כיון שהניח את הקומץ בכלי שרת המיוחד לו, אף שהיה זה בלילה ושלא בזמן הראוי — התקדש הקומץ, ואי אפשר להחזירו שוב למנחה, ולקומצה פעם נוספת.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כלל זה ממה ששנינו ככלל: \u0003כל\u0004 קרבן \u0003הקרב ביום\u0004 — הריהו \u0003קדוש\u0004 (מתקדש) \u0003ביום,\u0004 וכל קרבן הקרב \u0003בלילה\u0004 — אינו נעשה \u0003קדוש\u0004 אלא \u0003בלילה.\u0004 וכל קרבן הקרב \u0003בין ביום ובין בלילה\u0004 — נעשה \u0003קדוש בין ביום ובין בלילה.\u0004","ומתוך מה ששנינו כאן כי \u0003כל הקרב ביום\u0004 הריהו \u0003קדוש ביום,\u0004 יש לדייק: \u0003ביום\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 הריהו מתקדש, ואילו \u0003בלילה,\u0004 שאין הוא זמנו הראוי — הוא \u0003לא\u0004 מתקדש. הרי שכלי שרת אינם מקדשים את הדברים הניתנים בהם שלא בזמנם! ומשיבים: אמנם הדבר הניתן בכלי שרת שלא בזמנו \u0003אינו קדוש,\u0004 ואולם הכוונה היא שהוא לא התקדש לענין \u0003ליקרב\u0004 על גבי המזבח, \u0003אבל\u0004 הריהו \u0003קדוש\u0004 לענין \u0003ליפסל\u0004 בפסולי המוקדשים (כגון ביציאה אל מחוץ לתחום המקדש). ולכך אף הקומץ שנקמץ בלילה, התקדש לענין זה ששוב אי אפשר להחזירו למנחה על מנת לקומצה שנית, ולכך דינו בשריפה.","\u0003מותיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' זירא\u0004 ממה ששנינו במשנתנו, שאם \u0003סידר את הלחם ואת הבזיכין\u0004 שלא בזמנו בשבת אלא \u0003אחר\u0004 ה\u0003שבת, והקטיר את הבזיכין בשבת\u0004 הבאה — הריהי \u0003פסולה. כיצד יעשה? יניחנה לשבת הבאה,\u0004 וטעם ההיתר לכך: \u0003ש\u0004כן \u0003אפילו היא\u0004 מונחת \u0003על השלחן ימים רבים\u0004 — \u0003אין בכך כלום,\u0004 שאין הלחם נפסל בכך בלינה.","\u0003ו\u0004מעתה יש לשאול: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר ש\u0003כלי שרת מקדשין\u0004 אף את הדברים שניתנו בהם \u0003שלא בזמנן\u0004 הראוי ליפסל — אף הלחם הניתן על שולחן הפנים שלא בזמנו \u0003ליקדוש\u0004 \u0005[שיתקדש]\u0006 בכך, \u0003ו\u0004מעתה \u0003ליפסול\u0004 \u0005[שיפסל]\u0006 בלינה!","\u0003אמר רבה\u0004 על שאלתו זו של ר' זירא: \u0003מאן דקא מותיב\u0004 \u0005[מי שהוא מקשה]\u0006 שאלה \u0003זו\u0004 — \u0003שפיר קא מותיב\u0004 \u0005[יפה הוא מקשה],\u0006 משום שהקושיה נראית, ואולם \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' אבין נמי\u0004 \u0005[גם כן]\u0006 לא מדעתו אמר כך אלא \u0003מתניתא קאמר\u0004 \u0005[ברייתא הוא אומר,\u0006 מביא\u0005],\u0006 ואין זה אם כן שאלה על דבריו אלא על הברייתא, ויש ליישב את הסתירה בינה לבין האמור במשנתנו באופן זה: התנא בברייתא שהביא אביו של ר' אבין \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כי \u0003לילה\u0004 לענין דבר שצריך להיעשות ביום, אף שהוא טרם זמנו \u0003אין\u0004 נחשב \u0003ל\u0004\u0003מחוסר זמן,\u0004 משום שהלילה והיום שלאחריו נחשבים כיחידה אחת. ולכן כלי שרת מקדשים את הקומץ הנקמץ בלילה (לענין שיפסל בפסולי המוקדשים). ואולם בהלכה \u0003הא\u0004 \u0005[זו]\u0006 שבמשנתנו מדובר באופן ששהו הלחמים על שולחן הפנים כמה \u0003ימים\u0004 טרם זמנם, שהרי זמנם הוא שבת וכשהונחו ביום ראשון הרי זמנם הוא השבת הבאה, וכל אותם הימים עד לשבת הם טרם זמנו — ובאופן זה נחשבים הם \u0003כ\u0004\u0003מחוסרין זמן,\u0004 ואין כלי שרת מקדשם, ולכך אין הם נפסלים בלינה.","ושואלים על רבא: \u0003סוף סוף\u0004"],["\u0003כי מטי ליליא דבי שימשי, ליקדוש וליפסול\u0004 \u0005[כאשר מגיע הלילה, בין השמשות\u0006 של ערב שבת, \u0005שיתקדש\u0006 הלחם על ידי \u0005השולחן\u0006 \u0005ויפסל]\u0006 בלינה! \u0003אמר רבא:\u0004 מדובר במשנתנו \u0003ב\u0004אופן \u0003שקדם\u0004 (הקדים) הכהן סמוך לחשיכה של ליל שבת \u0003וסילק\u0004 את הלחם מעל השולחן. שאז אין השולחן מקדש את הלחם, \u0003ורק לאחר שחשכה שב והחזירו.\u0004","\u0003מר זוטרא\u0004 אמר \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב אשי\u0004 הוא זה ש\u0003אמר\u0004 כן: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר במשנה \u0003ב\u0004אופן \u0003שלא קדם\u0004 הכהן \u0003וסילק\u0004 את הלחם מעל השולחן לפני חשיכה של ליל שבת, ושהה הלחם כל הימים על השולחן — אין הוא מתקדש על ידי השולחן. וטעם הדבר: \u0003כיון\u0004 ש\u0003סידרו\u0004 את הלחם מתחילה \u0003שלא כמצותו,\u0004 שלא בזמנו הראוי — \u0003נעשה\u0004 (נחשב) הדבר \u0003כמי שסדרו הקוף,\u0004 ובכגון זה אין הלחם מתקדש על ידי השולחן, ולכך אינו נפסל בלינה.","\u0003שתי הלחם\u0004 הבאות בחג השבועות \u0003נאכלות\u0004 (זמן אכילתן) על ידי הכהנים \u0003אין\u0004 הוא \u0003פחות משנים\u0004 ימים, \u0003ולא יותר על שלשה\u0004 ימים מזמן שנאפו. ומסבירים: \u0003כיצד?\u0004 חלות שתי הלחם הריהן \u0003נאפות מערב יום טוב\u0004 של חג השבועות (שאין אפייתם דוחה את יום טוב), והריהן קרבות ו\u0003נאכלות ביום טוב\u0004 — נמצא זמן אכילתן \u0003לשנים\u0004 ימים לאחר אפייתם. ואם \u0003חל יום טוב\u0004 של שבועות \u0003להיות אחר השבת\u0004 (ביום ראשון), ונאפות החלות ביום הששי (שהרי אין אפייתן דוחה את השבת) — נמצא שהם \u0003נאכלות לשלשה\u0004 ימים מאפייתם.","\u0003לחם הפנים\u0004 הבא בכל שבת \u0003נאכל אין פחות מתשעה\u0004 ימים לאחר אפייתו \u0003ולא יותר על אחד עשר\u0004 ימים לאחר אפייתו. ומפרטים: \u0003כיצד?\u0004 כרגיל לחם הפנים \u0003נאפה מערב שבת\u0004 ומסודר על שולחן הפנים למחרת בשבת, ושוהה על השולחן כל השבוע, והריהו מוסר מהשולחן \u0003ונאכל בשבת\u0004 הבאה — נמצא זמן אכילתו \u0003לתשעה\u0004 ימים מאפייתו. ואם \u0003חל יום טוב להיות\u0004 ב\u0003ערב שבת,\u0004 מאחר שאין אפייתו דוחה לא את השבת ולא את יום טוב, הריהו נאפה ביום הקודם, ביום חמישי, והריהו נאכל בשבת השניה — נמצא ש\u0003נאכל\u0004 הלחם \u0003לעשרה\u0004 ימים מזמן אפייתו.","ואם חלו \u0003שני ימים טובים של ראש השנה\u0004 לפני השבת, בימי חמישי וששי, והריהו נאפה בשל כך ביום הרביעי, ונאכל בשבת השניה — נמצא ש\u0003נאכל לאחד עשר\u0004 ימים מאפייתו. \u0003ו\u0004טעם הדבר הוא, כנזכר למעלה, משום שמעשה שתי הלחם ולחם הפנים \u0003אינו דוחה לא את השבת ולא את יום טוב. רבן שמעון בן גמליאל אומר משום\u0004 (בשם) \u0003ר' שמעון בן הסגן:\u0004 אפיית הלחם \u0003דוחה את יום טוב,\u0004 אבל \u0003אינו דוחה את יום צום\u0004 (הכיפורים), ולכך אם חל יום הכיפורים ביום ששי — אין אופים בו את לחם הפנים. שנינו במשנתנו שאין אפיית שתי הלחם דוחה את השבת ואת יום טוב. ובענין זה מביאים \u0003מה ש\u0004\u0003אמר רבינא: לדברי\u0004 החכם \u0003האומר\u0004 שקרבנות \u0003נדרים ונדבות אין קריבין ביום טוב\u0004 — \u0003לא תימא\u0004 \u0005[אל תאמר,\u0006 תפרש\u0005]\u0006 את השיטה הזו ש\u0003מדאורייתא מיחזא חזו\u0004 \u0005[מדין תורה\u0006 אכן \u0005ראויים הם]\u0006 להיקרב ביום טוב, \u0003ו\u0004רק \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003הוא\u0004 ש\u0003גזרו\u0004 ואסרו את הקרבתם ביום טוב, מהטעם \u0003שלא ישהא\u0004 אדם מלהקריב את קרבנות נדריו ונדבותיו עד יום טוב (שאז הריהו עולה לירושלים). \u0003אלא מדאורייתא נמי\u0004 \u0005[מדין תורה גם כן]\u0006 קרבנות הנדרים והנדבות \u0003לא חזו\u0004 \u0005[אינם ראויים]\u0006 להקרבה, שהרי אין זמן הקרבתם קבוע למועד.","","וראיה לדבר שדין תורה הוא: \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שתי הלחם\u0004 ש\u0003חובת היום הוא,\u0004 שאין הם באים אלא בחג השבועות, \u0003ו\u0004מעתה \u0003ליכא למימר\u0004 \u0005[אין מקום לומר]\u0006 בהם גזירה זו \u0003שמא ישהא\u0004 את קרבנותיו לזמן מאוחר יותר. \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שונה הוא\u0006 התנא \u0005במשנתנו\u0006\u0005]\u0006 בדין שתי הלחם שמעשה אפייתו \u0003אינו דוחה לא את השבת ולא את יום טוב,\u0004 ואם כן הוא הדין לגבי הקרבת הנדרים והנדבות ביום טוב, שאין איסורם משום גזירת חכמים אלא מדין תורה. \u0003ה\u0004סולת והשמן שהוקדשו ל\u0003מנחות, ו\u0004כן יין שהוקדש ל\u0003נסכים\u0004 (שכל עוד לא ניתנו בכלי שרת עדיין לא נתקדשו בקדושת הגוף), \u0003שנטמאו עד שלא\u0004 \u0003קדשו בכלי\u0004 שרת — \u0003יש להם פדיון,\u0004 שרשאי לפדותם בכסף, ותחול קדושתם על הכסף, ויקנה בו מנחות ונסכים אחרים. ואולם אם נטמאו המנחות והנסכים \u0003משקידשו\u0004 (לאחר שכבר התקדשו) \u0003בכלי\u0004 שרת — \u0003שוב\u0004 \u0003אין להם פדיון,\u0004 והריהם נשרפים, ככל קרבן שנטמא.","","","\u0003העופות\u0004 שהוקדשו (לקרבן העוף), \u0003ו\u0004כן \u0003העצים\u0004 שהוקדשו לעצי המזבח, \u0003ו\u0004כן \u0003הלבונה\u0004 שהוקדשה, \u0003וכלי שרת, משנטמאו\u0004 (מאחר שנטמאו) — שוב \u0003אין להן פדיון.\u0004 וטעם הדבר — \u0003לפי\u0004 \u0003שלא נאמר\u0004 דין \u0003פדיון\u0004 קדשים שנטמאו או שנפסלו להקרבה \u0003אלא בבהמה\u0004 שהוקדשה לקרבן ונפל בה מום, ולא בשאר קדשים.","שנינו במשנתנו כי המנחות והנסכים שנטמאו, וקדושת דמים עליהם, הריהם נפדים. \u0003אמר שמואל:\u0004 לא רק כאשר נטמאו המנחות והנסכים הריהם נפדים, אלא \u0003אפילו הן טהורין\u0004 הריהם גם כן \u0003נפדין.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 כל \u0003כמה\u0004 (כל עוד) ש\u0003לא קדשי\u0004 \u0005[לא התקדשו]\u0006 המנחות והנסכים \u0003בכלי\u0004 שרת — \u0003ב\u0004\u0003קדושת דמים נינהו\u0004 \u0005[הם]\u0006 קדושים, ולא בקדושת הגוף, \u0003ו\u0004כל הדברים הקדושים ב\u0003קדושת דמים נפדין\u0004 בכל מקרה.","ומקשים על הלכה זו: \u0003והא\u0004 \u0005[והרי]\u0006 \"המנחות והנסכים \u0003ש\u0004\u0003נטמאו\" תנן\u0004 \u0005[שנינו]\u0006 במשנתנו, ללמד שרק אם נטמאו יש בהם דין פדיון! ומשיבים: \u0003הוא הדין דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא נטמאו\u0004 הריהם נפדים, \u0003ו\u0004הטעם שהזכירה המשנה \"שנטמאו\": \u0003איידי דקא בעי מיתנא סיפא\u0004 \u0005[מתוך שהוא,\u0006 התנא, \u0005רוצה לשנות\u0006 את \u0005סוף\u0006 אותה הלכה\u0005],\u0006 ש\u0003משקידשו בכלי\u0004 שוב \u0003אין להן\u0004 \u0003פדיון,\u0004 שבהלכה זו \u0003אפילו\u0004 אם \u0003נטמאו,\u0004 ונפסלו איפוא להקרבה, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 ייפדו, \u0003לכך\u0004 \u0003תנא נמי רישא\u0004 \u0005[שנה גם כן בראש\u0006 אותה הלכה\u0005]:\u0006 \u0003שנטמאו עד שלא קדשו\u0004 \u0003בכלי.\u0004","ושואלים על סופה של הלכה זו, שמשעה שהתקדשו בכלי שוב אין להם פדיון: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא הדבר, שהרי ב\u0003קדושת הגוף נינהו\u0004 \u0005[הם]\u0006 קדושים, ואי אפשר לפדותם!","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, \u0003שכן\u0004 \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ובעל מום איקרי\u0004 \u0005[נקרא]\u0006 \u0003\"טמא\",\u0004 וכדרך שיתפרש בהמשך הדברים, ובהמת קרבן (הקדושה בקדושת הגוף) שנפל בה מום, הריהי נפדית, אם כן \u0003טמא נמי\u0004 \u0005[גם\u0006 \u0003כן]\u0004 \u0003כבעל מום דמי\u0004 \u0005[\u0006הריהו \u0005נחשב],\u0006 שיש בו דין של בעל מום, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 שהריהו \u0003קדוש קדושת הגוף, כי נפיל ביה\u0004 \u0005[כאשר נופל בו]\u0006 \u0003מום\u0004 — הריהו \u0003מיפריק\u0004 \u0005[נפדה].\u0006 ומעתה יש מקום לומר כי \u0003הני נמי\u0004 \u0005[אלה\u0006 המנויים במשנתנו, אף שקדושים בקדושת הגוף, \u0005גם כן]\u0006 \u0003ליפרוק\u0004 \u0005[שייפדו].\u0006 לכך \u0003קמשמע לן\u0004 \u0005[הוא,\u0006 התנא \u0005משמיע לנו],\u0006 \u0003דלאו כי האי\u0004 \u0005[שלא כמו,\u0006 לא לענין \u0003זה]\u0004 \u0003\"טמא\" קרייה רחמנא\u0004 \u0005[קראה,\u0006 החשיבה \u0005אותו התורה]\u0006 \u0003לבעל מום,\u0004"],["שכן דבר שהתקדש \u0003מ\u0004היותו ב\u0003כלי שרת לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 בו \u0003ש\u0004\u0003מיפריק\u0004 \u0005[נפדה].\u0006","למעלה נאמר כי התורה קוראת לבעל מום \"טמא\", ושואלים: \u0003ובעל מום היכא איקרי\u0004 \u0005[היכן נקרא]\u0006 בתורה \u0003\"טמא\"? דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 מה שנאמר בפדיון קדשים \u0003\"ואם כל בהמה טמאה אשר לא יקריבו ממנה קרבן לה'\u0004 והעמיד את הבהמה לפני הכהן. והעריך הכהן אותה בין טוב ובין רע כערכך הכהן כן יהיה. ואם גאול יגאלנה ויסף חמישיתו על ערכך\" (ויקרא כז, יא— יג) — \u0003ב\u0004בהמות שהן \u0003בעלי מומין שנפדין הכתוב מדבר,\u0004 ונקראות \"טמאות\" משום שאינן ראויות להקרבה.","ודנים בדבר: \u0003אתה אומר\u0004 כי \u0003בבעלי מומין שנפדו\u0004 הכתוב מדבר, \u0003או אינו אלא בבהמה טמאה ממש\u0004 הכתוב מדבר, כמשמעו של מקרא. ולהורות שאם הקדיש בעל חיים טמא — הריהו נפדה? \u0003כשהוא,\u0004 הכתוב באותה פרשה, שב ו\u0003אומר: \"ואם בבהמה הטמאה ופדה\u0004 \u0003בערכך\u0004 ויסף חמישיתו עליו...\" (שם כז) — \u0003הרי בהמה טמאה\u0004 ממש כבר \u0003אמורה\u0004 שהיא נפדית\u0003, הא\u0004 \u0005[הרי]\u0006 מעתה \u0003מה אני מקיים\u0004 (כיצד אני מסביר) את \u0005הכתוב\u0006 \u0003\"ואם כל בהמה טמאה\"?\u0004 — \u0003בבעלי מומין שנפדו\u0004 (שהריהם נפדים) \u0003הכתוב\u0004 הזה \u0003מדבר.\u0004","וממשיכים ודנים \u0005בהלכה זו:\u0006 \u0003יכול\u0004 יהא הדין ש\u0003יפדו\u0004 קדשים אף \u0003על מום עובר\u0004 שנפל בהם? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בהמשך כתוב זה \u0003\"אשר לא יקריבו ממנה קרבן לה' \"\u0004— אין הדברים אמורים אלא ב\u0003מי שאינה קריבה לה' כל עיקר, יצתה\u0004 (יצאה) \u0003זו\u0004 שיש בה מום עובר \u0003ש\u0004אמנם \u0003אינה קריבה היום\u0004 כשהיא \u0005בעלת מום,\u0006 \u0003ו\u0004אולם הריהי \u0003קריבה למחר\u0004 (לאחר זמן) כשיעבור המום. ומכאן למדנו, שבעל מום נקרא בתורה \"טמא\".","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003רב הונא בר מנוח\u0004 על דברי שמואל, האומר שאף המנחות והנסכים הטהורים נפדים, כיון שעדיין לא התקדשו בכלי שרת, ממה ששנינו במשנתנו כי \u0003העופות והעצים והלבונה וכלי שרת שנטמאו\u0004 — \u0003אין להן פדיון, ש\u0004הרי \u0003לא נאמר פדיון אלא בבהמה.\u0004 ויש לדון \u0005בדברים:\u0006 \u0003בשלמא\u0004 \u0005[נניח,\u0006 זה מובן\u0005]\u0006 מדוע \u0003עופות\u0004 אינם נפדים — שכן ב\u0003קדושת הגוף נינהו\u0004 \u0005[הם]\u0006 קדושים, \u0003ולא נאמר\u0004 פדיון בדבר הקדוש בקדושת הגוף \u0003אלא בבהמה\u0004 בלבד.","\u0003אלא עצים ולבונה\u0004 שעדיין \u0005לא התקדשו בקדושת הגוף בנתינתם בכלי שרת, שנטמאו,\u0006 \u0003ו\u0004כן \u0003כלי שרת\u0004 עצמם שנטמאו, שאינם קדושים בקדושת הגוף — \u0003ליפרקו\u0004 \u0005[שייפדו]!\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 טעם הדבר הוא \u0003משום\u0004 שכלל הוא בפדיון הקדשים כי \u0003טהורין בעלמא\u0004 \u0005[בכלל]\u0006 \u0003אין נפדין,\u0004 ואף שאינם קדושים בקדושת הגוף.","\u0003ו\u0004מעתה \u0003הני\u0004 \u0005[אלה,\u0006 עצים ולבונה וכלי שרת שנטמאו\u0005],\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 אינם נפדים, \u0003שכן\u0004 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003נטמאו\u0004 — \u0003כטהורים דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 שכן \u0003עצים ולבונה\u0004 — \u0003לאו בני אשויי אוכלא נינהו\u0004 \u0005[לא בני היעשות אוכל הם],\u0006 ומשום כך הם לא היו צריכים להיות טמאים כלל, \u0003אלא חיבת הקודש משוה להו אוכלא\u0004 \u0005[עושה אותם כאוכל]\u0006 שיקבלו טומאה.","וכן \u0003עצים\u0004 כל \u0003כמה\u0004 (עוד) \u0005ש\u0006\u0003לא\u0004 \u0003משפי להו לגזירין\u0004 \u0005[לא משפה,\u0006 מקציע \u0005אותם לגזירי\u0006 עץ\u0005]\u0006 הם \u0003לא מיתכשרי\u0004 \u0005[לא מתכשרים]\u0006 לקבל טומאה. וכן \u0003לבונה נמי\u0004 \u0005[גם כן]\u0006 כל \u0003כמה\u0004 \u0005ש\u0006\u0003לא קידשה בכלי שרת\u0004 — \u0003לא מיתכשרה\u0004 \u0005[לא התכשרה]\u0006 לקבל טומאה. וכן \u0003כלי שרת נמי\u0004 \u0005[גם כן]\u0006 \u0003הואיל ואית להו\u0004 \u0005[ויש להם]\u0006 \u0003טהרה במקוה\u0004 נחשבים הם כטהורים, ואינם נפדים. הרי שקדשים טהורים אינם נפדים, ושלא כדברי שמואל!","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003טהורין\u0004 כגון זה \u0003בעלמא\u0004 \u0005[בכלל]\u0006 הריהם \u0003נפדין, והני\u0004 \u0005[ואלה,\u0006 עצים ולבונה וכלי שרת\u0005]\u0006 אינם \u0005נפדים אף שאינם קדושים בקדושת הגוף, מפני גזירת חכמים, וטעם הדבר:\u0006 \u0003משום\u0004 שכשהם טהורים — \u0003לא שכיחי\u0004 \u0005[לא מצויים]\u0006 \u0003הוא,\u0004 ואם הנודרים אותם למקדש יפדום, שוב לא יימצאו לעבודת המקדש.","ומקשים על הסבר זה: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לבונה וכלי שרת\u0004 — \u0003לא שכיחי\u0004 \u0005[לא מצויים]\u0006 הם. \u0003אלא עצים\u0004 מדוע נאסר פדיונם, והרי \u0003מישכח שכיחי\u0004 \u0005[מצויים]\u0006 הם! ומשיבים: \u0003עצים נמי\u0004 \u0005[גם כן]\u0006 אינם מצויים לעבודה במקדש, שכן \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בדין העצים כי \u0003כל עץ שנמצא בו תולעת\u0004 הריהו \u0003פסול לגבי\u0004 \u0005[אצל,\u0006 לענין\u0005]\u0006 ה\u0003מזבח, הילכך לא שכיחי\u0004 \u0005[לכך לא מצויים]\u0006 כל כך עצים למזבח.","ועוד לענין שיטת שמואל, \u0003אמר רב פפא: אי שמיעא ליה\u0004 \u0005[אם היתה נשמעת,\u0006 נודעת \u0005לו]\u0006 \u0003לשמואל הא דתניא\u0004 \u0005[\u0006הלכה \u0005זו ששנויה\u0006 בברייתא\u0005]\u0006 האומרת ש\u0003המתפיס\u0004 (המקדיש) בעלי חיים (בהמות טהורות) \u0003תמימים\u0004 (שאין בהם מום) \u0003ל\u0004קדשי \u0003בדק הבית\u0004 במקום למזבח כראוי להן — כאשר הם נפדים על ידי ההקדש, \u0003אין פודין אותן\u0004 גזברי ההקדש \u0003אלא ל\u0004צורך \u0003מזבח\u0004 שנמכרים למי שחייב בהקרבת אותו מין, ויקרבו על ידו על המזבח. ואין נפדים לחולין, לפי שכלל הוא \u0003שכל\u0004 דבר הקדש \u0003הראוי למזבח,\u0004 אף שהוקדש לבדק הבית \u0003אינו יוצא מידי מזבח לעולם. ו\u0004משמע מכאן ש\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שב\u0003קדושת דמים\u0004 בלבד \u0003נינהו\u0004 \u0005[הם]\u0006 קדושים — \u0003אין\u0004 הם \u0003נפדין\u0004 לחולין \u0003הואיל וטהורים הם\u0004 (וראויים למזבח). אם היה שומע זאת \u0003הוה הדר ביה\u0004 \u0005[היה חוזר בו].\u0006","ודוחים: \u0003ולא היא,\u0004 אינו כן, \u0003שמיעא ליה\u0004 \u0005[נשמעה,\u0006 ידועה היתה \u0005לו,\u0006 לשמואל\u0005]\u0006 ברייתא זו, \u0003ו\u0004בכל זאת \u0003לא\u0004 \u0003הדר ביה\u0004 \u0005[לא חזר בו]\u0006 מדבריו. שכך אמר שמואל בהסברה של \u0005אותה ברייתא:\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003אמרת התם\u0004 \u0005[שם]\u0006 בברייתא בטעם \u0005הדבר שאין פודים לחולין את העצים והלבונה וכלי השרת שהוקדשו לבדק הבית מ\u0006\u0003כיון\u0004 שהם \u0003לא שכיחי\u0004 \u0005[אינם מצויים]\u0006 לעבודה, ולכן \u0003לא מיפרקי\u0004 \u0005[לא נפדים]?\u0006","\u0003הכא\u0004 \u0005[כאן]\u0006 בבהמה תמימה שהוקדשה לבדק הבית \u0003נמי\u0004 \u0005[גם כן]\u0006 יש לומר כי מ\u0003כיון דשכיחי\u0004 \u0005[שמצויים]\u0006 הם ה\u0003מומין דפסלי\u0004 \u0005[שפוסלים]\u0006 \u0003בבהמה,\u0004 שהרי \u0003אפילו\u0004 מום קל כזה ש\u0003בדוקין שבעין נמי פסלי\u0004 \u0005[גם כן פוסלים],\u0006 \u0003הילכך\u0004 \u0005[לכך]\u0006 בהמות תמימות הראויות \u0003להקרבה\u0004 \u0003לא שכיחי\u0004 \u0005[אינן מצויות],\u0006 ולכך גזרו בהן חכמים שאין פודים אותן אלא למזבח, שתהיינה בהמות הראויות להקרבה. מה שאין כן במנחות ונסכים (שבהם דיבר שמואל), שמצויים הם, ולכך הריהם נפדים אפילו הם טהורים.","ולאחר שנידונה שיטת שמואל הסבור שאף המנחות והנסכים הטהורים שלא קדשו עדיין בכלי שרת נפדים, מביאים דעה החלוקה על שיטתו. \u0003רב כהנא אמר:\u0004 המנחות והנסכים שלא קדשו עדיין בכלי שרת, ה\u0003טמאין\u0004 — \u0003נפדין,\u0004 ה\u0003טהורין\u0004 — \u0003אין נפדין.\u0004 ומציינים, \u0003וכן אמר ר' אושעיא:\u0004 המנחות והנסכים שלא קדשו עדיין בכלי שרת, ה\u0003טמאין\u0004 — \u0003נפדין,\u0004 ה\u0003טהורין\u0004 — \u0003אין נפדין.\u0004 ומעירים: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך \u0003אמר ר' אושעיא: אפילו טהורין\u0004 — \u0003נפדין.\u0004","\u0003ר' אלעזר אומר:\u0004 כל המנחות \u0003כולן\u0004 דינן שווה לענין פדיונן, שה\u0003טמאין\u0004 — \u0003נפדין,\u0004 וה\u0003טהורין\u0004 — \u0003אין נפדין, חוץ מעשירית האיפה\u0004 סולת \u0003של מנחת חוטא\u0004 (מנחת דלי דלות בקרבן עולה ויורד הבאה על חטא בשבועת העדות או בשבועת ביטוי או בטומאת מקדש וקדשיו) הנפדית אפילו היא טהורה.","וטעם הדבר: \u0003שהרי אמרה תורה\u0004 בדינו של העשיר בקרבן עולה ויורד (המביא קרבנותיו מן הצאן) \"וכפר עליו הכהן \u0003מחטאתו\"\u0004 (ויקרא ה, ו), וכן נאמר בדינו של העני בקרבן עולה ויורד (המביא קרבנותיו מן העופות) \"וכפר עליו הכהן מחטאתו אשר חטא...\" (שם י), ואילו בדלי דלות (המביא קרבנותיו מעשירית האיפה סולת) נאמר \"וכפר עליו הכהן \u0003על חטאתו\u0004 אשר חטא מאחת מאלה ונסלח לו...\" (שם יג). ובא שינוי הלשון \"על חטאתו\" במקום \"מחטאתו\" להורות שאם הדל שבדלים הפריש עשירית האיפה למנחתו, ולאחר מכן העשיר — שהוא פודה את מנחתו זו, ומוסיף על הדמים שהתקבלו עליה עוד (\"על חטאתו\"), וקונה בהם קרבן הראוי לו עתה. ומכאן למדים אנו שנפדית מנחה זו אף כשלא נטמאה.","ומביאים עוד מה ש\u0003אמר ר' אושעיא: שמעתי\u0004 (קבלתי במסורת חכמים) בדינו של זה ש\u0003פיגל במנחה\u0004 (שחשב בשעת עבודה בה לאוכלה שלא בזמנה הראוי, ונאסרה בכך בהנאה), שאותה מנחה \u0003ל\u0004דעת \u0003ר' שמעון אינו מטמא\u0004 (מקבל) \u0003טומאת אוכלין. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הערלה, וכלאי הכרם,\u0004"],["\u0003ו\u0004בשרו של \u0003שור הנסקל\u0004 (שנגמר דינו בבית דין להיסקל), \u0003ו\u0004בשרה של \u0003עגלה ערופה,\u0004 \u0003ו\u0004בשרם של \u0003צפורי מצורע,\u0004 \u0003ו\u0004בשרו של \u0003פטר חמור\u0004 שנערף כדינו, \u0003ובשר\u0004 שהתבשל \u0003בחלב,\u0004 שאף שהם אסורים באכילה — מכל מקום \u0003כולם מטמאין\u0004 (ראויים לקבל) \u0003טומאת אוכלין.\u0004","\u0003ר' שמעון אומר: כולן אין מטמאין טומאת אוכלין,\u0004 משום שהם אסורים בהנאה, ואינם נחשבים כאוכל. \u0003ו\u0004אולם \u0003מודה ר' שמעון בבשר\u0004 שהתבשל \u0003בחלב שמטמא טומאת אוכלין,\u0004 וטעם הדבר: \u0003הואיל והיתה לו,\u0004 לכל אחד מהם, לבשר ולחלב, \u0003שעת הכושר\u0004 (זמן שהיה ראוי בו) לקבל טומאה, לפני שהתבשלו כאחד.","\u0003ואמר רב אסי, אמר ר' יוחנן:\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 שיטתו של \u0003ר' שמעון\u0004 שדבר האסור בהנאה אינו מיטמא טומאת אוכלין? — \u0003נאמר\u0004 \u0003\"מכל האכל אשר יאכל\u0004 אשר יבוא עליו מים יטמא...\" (ויקרא יא, לד), ובא כפל הלשון \"האוכל אשר יאכל\" להורות: דווקא \u0003אוכל שאתה יכול להאכילו לאחרים\u0004 — הוא ה\u0003קרוי אוכל\u0004 לענין קבלת טומאת אוכלין. ואולם \u0003אוכל שאי\u0004 (שאין) \u0003אתה יכול להאכילו לאחרים\u0004 — \u0003אינו קרוי אוכל\u0004 לענין זה. ומכאן שהאסור בהנאה, שאסור להאכילו גם לאחרים, אינו נחשב אוכל לענין קבלת טומאה.","\u0003ו\u0004מסכם ר' אושעיא את שמועתו: \u0003הא\u0004 \u0005[הרי]\u0006 כש\u0003פיגל במנחה נמי\u0004 \u0005[גם כן]\u0006 נאסרה המנחה בהנאה, ו\u0003אוכל שאי אתה יכול להאכילו לאחרים הוא,\u0004 ולכך לדעת ר' שמעון אינה טומאת אוכלין.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היא שיטת ר' שמעון, \u0005שכל אוכל שאין אתה יכול להאכילו לאחרים\u0006 — אינו מקבל טומאה, \u0005מעתה\u0006 \u0003בשר\u0004 שהתבשל \u0003בחלב\u0004 \u0003נמי תיפוק ליה\u0004 \u0005[גם כן יצא,\u0006 יילמד, \u0005לו\u0006 לר' שמעון\u0005],\u0006 שראוי לקבל טומאת אוכלין משום ש\u0003אוכל שאתה יכול להאכילו לאחרים הוא.\u0004 שהרי לשיטת ר' שמעון אין בשר וחלב נאסרים בהנאה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: בשר\u0004 שהתבשל \u0003בחלב\u0004 אף שהוא \u0003אסור באכילה,\u0004 \u0003מותר בהנאה, ש\u0004כן \u0003נ\u0004 \u0003אמר\u0004 באיסור בשר וחלב \u0003\"כי עם קדוש אתה לה' אלהיך לא תבשל גדי בחלב אמו\"\u0004 (דברים יד, כא), \u0003ולהלן\u0004 \u0005[ושם,\u0006 בספר שמות\u0005]\u0006 הוא הכתוב \u0003אומר \"ואנשי קדש תהיון לי ובשר בשדה טרפה לא תאכלו\"\u0004 (שמות כב, ל), \u0003מה להלן\u0004 בשר טריפה (שנאמר בו \"אנשי קודש\") \u0003אסור באכילה\u0004 אבל \u0003מותר בהנאה, אף כאן\u0004 בשר שהתבשל בחלב (שנאמר בו \"עם קדוש\") \u0003אסור באכילה ומותר בהנאה!\u0004","ומשיבים: \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 מדוע בשר בחלב מקבל טומאה, \u0003ועוד\u0004 טעם נוסף \u0003קאמר\u0004 \u0005[הוא,\u0006 ר' שמעון \u0005אמר],\u0006 ומפרטים: טעם \u0003חדא\u0004 \u0005[אחד],\u0006 משום ש\u0003אוכל שאתה יכול להאכילו לאחרים הוא,\u0004 ולכך הריהו נקרא אוכל לענין קבלת טומאה. \u0003ועוד\u0004 טעם, משום שאף \u0003לדידיה נמי\u0004 \u0005[לו עצמו,\u0006 לישראל, שעתה הוא אסור באכילתו, \u0005גם כן]\u0006 הרי \u0003היתה לו\u0004 לבשר זה וכן לחלב \u0003שעת הכושר\u0004 שבו היו מותרים באכילה, ולכך אף עתה הריהם ראויים לקבל טומאה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו עוד בברייתא ש\u0003ר' שמעון אומר\u0004 כי \u0003יש\u0004 קרבן ה\u0003נותר\u0004 (שלא נאכל בתוך זמן אכילתו הראוי, ונאסר בהנאה) \u0003שהוא מטמא טומאת אוכלין, ויש נותר שאינו מטמא טומאת אוכלין,\u0004","\u0003כיצד?\u0004 אם \u0003לן\u0004 (עבר עליו לילה) \u0003לפני זריקה\u0004 של דמו על המזבח — \u0003אינו מטמא טומאת אוכלין.\u0004 שכיון שלא נזרק דמו, לא הוכשר באכילה עד שנאסר. ואולם אם לן \u0003לאחר זריקה,\u0004 שהוקרב כדינו — הריהו \u0003מטמא טומאת אוכלין,\u0004 שכן היתה לו שעת הכושר.","\u0003(והא)\u0004 \u0003ו\u0004בשר ה\u0003פיגול\u0004 (שחשב בשעת עבודה לאוכלו מחוץ לזמנו הראוי ונפסל), \u0003בין ב\u0004קרבנות \u0003קדשי קדשים בין ב\u0004קרבנות \u0003קדשים קלים\u0004 — \u0003אינו מטמא טומאת אוכלין,\u0004 שהרי \u0003נאסר באכילה בשעת עבודה, ולא היתה לו שעת הכושר. ואולם אם\u0004 \u0003פיגל\u0004 הכהן \u0003במנחה\u0004 (שחשב לאוכלה שלא בזמנה הראוי) — הריהי \u0003מטמא טומאת אוכלין,\u0004 שכן היתה לה שעת הכושר (בעודה קמח לפני שהתקדשה למנחה). והרי זה בניגוד לשמועה ששמע ר' אושעיא בדברי ר' שמעון שאין המנחה שהתפגלה ראויה לקבל טומאת אוכלין!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 שאמר ר' שמעון בברייתא שהמנחה שהתפגלה ראויה לקבל טומאת אוכלין מדובר כ\u0003שהיתה לה שעת הכושר\u0004 קודם שהתקדשה. ואילו \u0003כאן\u0004 ששיטת ר' שמעון (לשמועתו של ר' אושעיא) שהמנחה שהתפגלה אינה מקבלת טומאת אוכלין מדובר כ\u0003שלא היתה לה\u0004 לפני כן \u0003שעת הכושר.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 אתה יכול למצוא מנחה ש\u0003לא היתה לה שעת הכושר,\u0004 והרי לפני שהוקדש קמח החיטים למנחה, היה מותר באכילה? ומשיבים: \u0003במקרה\u0004 \u0003דאקדשינהו\u0004 \u0005[שהקדיש אותם,\u0006 את החיטים\u0005]\u0006 עוד \u0003ב\u0004היותם \u0003מחובר\u0004 לקרקע שאז אין הם מקבלים טומאה). ולכשנקצרו לא היו ראויים לקבל טומאה, שהרי נאסרו באכילה.","\u0003ו\u0004שואלים: אף אלה היתה להם שעת הכושר לאכילה, שהרי יכול היה \u0003ליפרקינהו\u0004 \u0005[לפדות אותם],\u0006 שכל עוד לא התקדשו בקדושת הגוף על ידי כלי שרת יכולים לפדותם! ומסייגים את השאלה: \u0003הניחא להך לישנא\u0004 \u0005[זה נוח,\u0006 אין זו שאלה, \u0005ללשון זו]\u0006 ש\u0003אמר ר' אושעיא\u0004 כי מנחות ונסכים שטרם התקדשו בכלי, ה\u0003טמאין\u0004 — \u0003נפדין,\u0004 ואילו ה\u0003טהורין\u0004 — \u0003אין נפדין,\u0004 אם כן \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן הדבר\u0005],\u0006 מדוע החיטים שהוקדשו בעודם במחובר לקרקע אינן נחשבות שהיתה להם שעת הכושר, שהרי אין אפשרות לפדותן מפני שטהורות הן.","\u0003אלא להך לישנא\u0004 \u0005[ללשון זו,\u0006 השניה\u0005]\u0006 \u0003ש\u0004\u0003אמר\u0004 ר' אושעיא, ש\u0003אפילו\u0004 ה\u0003טהורין נפדין,\u0004 הרי כיון שהוקדשו החיטים במחובר היתה להם שעת הכושר, שהרי יכול \u0003לפרקינהו\u0004 \u0005[לפדות אותן]\u0006 עכשיו, אף שהן טהורות!","ומשיבים: אם אמנם היה פודה אותן — היתה זו נחשבת להן כשעת הכושר, ואולם \u0003השתא מיהא\u0004 \u0005[עכשיו על כל פנים]\u0006 הוא \u0003לא פריק\u0004 \u0005[לא פדה]\u0006 אותן, ולכך אין זו נחשבת כשעת הכושר.","ודוחים: אף שבפועל לא פדה אותן, \u0003ו\u0004אולם \u0003כיון דאי בעי, פריק ליה\u0004 \u0005[שאם רצה, היה פודה אותן],\u0006 נחשב הדבר כשעת הכושר, אף שלא פדה אותן בפועל. שכן \u0003שמעינן ליה\u0004 \u0005[שמענו אותו]\u0006 את \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 \u0003ש\u0004\u0003כל\u0004 דבר \u0003העומד לפדות\u0004 — \u0003כפדוי דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: פרה\u0004 אדומה, אף שנשחטה, והריהי אסורה בהנאה, \u0003מטמאה טומאת אוכלין, הואיל והיתה לה שעת הכושר\u0004 להיפדות, ולהיאכל. \u0003ו\u0004יותר מכך \u0003אומר ריש לקיש\u0004 ש\u0003אומר היה ר' שמעון\u0004 כי \u0003פרה\u0004 אדומה \u0003נפדית\u0004 אפילו כאשר היא כבר נתונה \u0003על גב מערכתה\u0004 ועומדת להישרף!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משוה]\u0006 פרה אדומה לדין המנחה. שהרי \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 מדוע ה\u0003פרה עומדת לפדות היא\u0004 כל עוד לא נשרפה, \u0003ש\u0004כן \u0003אם מצא\u0004 פרה אדומה \u0003אחרת נאה הימנה\u0004 (ממנה), הרי זו \u0003מצוה לפדותה\u0004 ולקנות בדמיה את הפרה האחרת. \u0003אלא הני\u0004 \u0005[אלה]\u0006 ה\u0003מנחות\u0004 וכי יש \u0003מצוה לפדותן?!\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 במקרה ש\u0003לן\u0004 הבשר \u0003לפני זריקה,\u0004 ש\u0003מצוה למיזרקיה\u0004 \u0005[לזורקו]\u0006 את הדם, \u0003ואי בעי\u0004 \u0005[ואם רצה]\u0006 \u0003זרק\u0004 את הדם ולא היה הקרבן נפסל, ויש לומר אף כאן כל העומד להיזרק כזרוק דמי, וייחשב כנזרק כבר, והיתה לו איפוא לבשר שעת הכושר, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה]\u0006 ר' שמעון בברייתא ש\u0003אין מטמא\u0004 הנותר \u0003טומאת אוכלין,\u0004 כיון שלא היתה לו שעת הכושר!","ודוחים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 בברייתא \u0005במה,\u0006 באיזה מקרה, \u0005אנו עוסקים]?\u0006 כ\u0003שלא היתה שהות ביום למיזרקיה\u0004 \u0005[לזורקו],\u0006 את הדם, וכגון שנשחט הקרבן סמוך \u0005לשקיעת החמה, ולכך אינו עומד להיזרק.\u0006","ושואלים: \u0003אבל\u0004 נוכל איפוא לדייק כי במקרה שנשחט הקרבן במשך היום, \u0003ו\u0004\u0003היתה לו שהות ביום\u0004 לזרוק את הדם, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין לשיטת ר' שמעון? שבשר הנותר \u0003מטמא טומאת אוכלין,\u0004 אם כן,","\u0003אדתני\u0004 \u0005[עד ש\u0006התנא \u0005שונה]\u0006 בברייתא להבחין בין הבשר הלן לפני זריקה (שאינו מיטמא טומאת אוכלין) לבין \u0003לן לאחר זריקה\u0004 שהריהו \u0003מטמא טומאת אוכלין\u0004 — \u0003ליפלוג בדידה\u0004 \u0005[שיחלק בה עצמה,\u0006 כשלן הבשר \u0005קודם זריקה\u0006\u0005],\u0006 ויאמר כך: \u0003במה דברים אמורים\u0004 שכאשר לן הבשר לפני הזריקה אינו מיטמא טומאת אוכלין? כ\u0003שלא היתה לו שהות ביום\u0004 לזרוק את הדם, \u0003אבל\u0004 אם \u0003היתה לו שהות ביום\u0004 — הריהו \u0003מטמא טומאת אוכלין!\u0004","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 כלומר, זו משמעות דבריו בברייתא, שאם \u0003לן\u0004 הבשר \u0003קודם שיראה\u0004 (שהיה דמו ראוי) \u0003לזריקה\u0004 — \u0003אינו מטמא טומאת אוכלין,\u0004 ואם לן \u0003לאחר שיראה\u0004 (שנעשה הדם ראוי) \u0003לזריקה\u0004 — \u0003מטמא טומאת אוכלין.\u0004","ומקשים עוד: האם אמר ר' שמעון שכל העומד להיפדות נחשב כבר כפדוי, ולכך הריהו כמי שהיה לו שעת הכושר (אף שלא נפדה בפועל): \u0003והא\u0004 \u0005[והרי]\u0006 שנינו עוד בברייתא שאם \u0003פיגל, בין בקדשי קדשים\u0004 ו\u0003בין בקדשים קלים\u0004 — אין הם מיטמאים בטומאת אוכלין, שכן לא היתה להם שעת הכושר, ואולם כיון שקודם שהתפגלו היתה \u0003מצוה למיזרקיה\u0004 \u0005[לזורקו],\u0006 את דמם,"],["\u0003ואי בעי\u0004 \u0005[ואם רצה]\u0006 היה \u0003זריק\u0004 \u0005[זורק]\u0006 את דמם של הקרבנות הללו כראוי. \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה]\u0006 ר' שמעון בברייתא שבשר קרבן שהתפגל \u0003אינו מטמא טומאת אוכלין, מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר ש\u0003פיגל ב\u0004שעת ה\u0003זריקה,\u0004 ולשיטת ר' שמעון שכל העומד להיזרק נחשב כזרוק, וכל העומד להיפדות נחשב כפדוי, הרי היתה שעת הכושר לקרבנות הללו לפני כן! ומשיבים: \u0003לא,\u0004 הברייתא מדברת כש\u0003פיגל\u0004 כבר \u0003ב\u0004עבודת \u0003ה\u0004\u0003שחיטה,\u0004 ולא עמד הדם לזריקה, ולכך אין הקרבן נחשב כמי שהיתה לו שעת הכושר.","ומקשים: \u0003אבל\u0004 לפי זה, נוכל לדייק ולומר שאם \u0003פיגל בזריקה מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 שבשר הקרבן \u0003מטמא טומאת אוכלין\u0004 משום שהיתה לו שעת הכושר.","אם כן \u0003אדתני\u0004 \u0005[עד ש\u0006התנא \u0005שונה]\u0006 להבחין בין המפגל בזבחים \u0005ובין זה ש\u0006\u0003פיגל במנחה\u0004 שהיא \u0003מטמא טומאת אוכלין,\u0004 \u0003ליפלוג בדידה\u0004 \u0005[שיחלק בה עצמה,\u0006 במפגל בקדשים\u0005],\u0006 ויאמר כך: המפגל בקדשים — אין בשרם מיטמא בטומאת אוכלין. \u0003במה דברים אמורים?\u0004 בזמן ש\u0003פיגל\u0004 כבר \u0003בשחיטה, אבל\u0004 אם \u0003פיגל בזריקה\u0004 — בשרם \u0003מטמא טומאת אוכלין!\u0004","ומשיבים: העדיף התנא להבחין בין המפגל בקדשים לבין המפגל במנחה, משום שהלכה זו של \u0003פיגל במנחה איצטריכא ליה\u0004 \u0005[נצרכה לו]\u0006 לשנותה, מפני \u0005שיש בכך חידוש,\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003פיגל\u0004 את המנחה כבר \u0003ב\u0004עבודת ה\u0003קמיצה,\u0004 וכלל בידינו שעבודת ה\u0003קומץ במנחה כ\u0004עבודת ה\u0003שחיטה\u0004 בקרבנות \u0003דמי\u0004 \u0005[היא נחשבת],\u0006 וקרבן שנתפגל בעבודת השחיטה אינו מיטמא טומאת אוכלין, \u0003אפילו הכי\u0004 \u0005[כך]\u0006 המפגל בקמיצה במנחות — המנחה \u0003מטמא טומאת אוכלין, הואיל והיתה לו שעת הכושר מעיקרו\u0004 לפני שקמץ. למעלה הוסבר כי אין להקשות מדברי ר' שמעון שבברייתא בענין בשר הנותר. שכוונת דבריו לחלק בין לינת הבשר קודם שנראה להיזרק, וללינתו לאחר שנראה להיזרק. וכן אין להקשות מדבריו שם בענין פיגול הקדשים, שכן כוונת דבריו היא דווקא כשפיגל בזריקה ולא כשפיגל בשחיטה.","ובענין זה \u0003אמר רב אשי: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה,\u0006 ההלכה הבאה \u0005לפני]\u0006 \u0003רב נחמן:\u0004 אין אנו נזקקים להסברים אלה, \u0003שהרי\u0004 \u0003אפילו\u0004 אם \u0003תימא\u0004 \u0005[תאמר]\u0006 שכוונת ר' שמעון בברייתא בענין הלינה שהבשר \u0003לן ממש\u0004 קודם זריקת הדם, \u0003ו\u0004כמו כן \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שכוונתו בענין הפיגול ש\u0003פ\u0004 \u0003יגל\u0004 \u0003בזריקה\u0004 ולא בשחיטה — עדיין אין להקשות מדוע לא ייחשב הדבר לשיטת ר' שמעון כמי שהיתה להם שעת הכושר, אף שלדעתו כל העומד להיפדות הריהו כפדוי.","וטעם הדבר: כי \u0003דאי בעי פריק\u0004 \u0005[שאם רצה היה פודה]\u0006 ולכך כל העומד להיפדות נחשב כפדוי — אמנם \u0003אמר\u0004 ר' שמעון, שהפדיון הוא דבר קל, הנעשה בדיבור פה בלבד. ואולם הקביעה האומרת \u0003אי בעי הוה זריק\u0004 \u0005[אם רצה היה זורק]\u0006 ולכך ייחשב כל שעומד להיזרק כזרוק — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 שכן כרוך הדבר במעשה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב אשי הללו ממה ששנינו בתחילת מסיכת מעילה, \u0003כלל אמר ר' יהושע\u0004 בענין מעילה בקדשים שנפסלו: \u0003כל\u0004 קרבן \u0003שהיתה לו\u0004 כבר \u0003שעת היתר\u0004 (אכילה) \u0003לכהנים\u0004 לפני שנפסל — \u0003אין מועלין בה\u0004 עוד, כיון שהמעילה היא דווקא בקדשים המוגדרים כ\"קדשי ה' \", שאין בהם צד הנאה לאדם. ומשעה שהותר הקרבן לאכילת כהנים, שוב אינו בכלל זה, אף שחזר ונפסל אחר כך מאכילה. \u0003וכל שלא היתה לו שעת היתר\u0004 אכילה \u0003לכהנים\u0004 לפני שנפסל — הרי הוא עדיין בכלל \"קדשי ה' \", ו\u0003מועלין בה. ו\u0004מסבירים:","\u0003איזהו\u0004 קרבן שהיתה לו \u0003שעת היתר\u0004 אכילה \u0003לכהנים?\u0004 כגון \u0003ש\u0004לאחר זריקת הדם \u0003לנה\u0004 בשר הקרבן בלא שנאכל, ונעשה נותר, \u0003ו\u0004כן זו \u0003שנטמאת\u0004 בשר הקרבן, \u0003ו\u0004כן \u0003זה\u0004 \u0003שיצאה\u0004 אל מחוץ לעזרה — אין בכל אלה דין מעילה, אף שבשר הקרבן עתה אסור לכהנים, כיון שהיתה שעה שהיה הבשר מותר באכילה לפני שנפסל.","\u0003ואיזו היא שלא היתה לו שעת היתר לכהנים?\u0004 שבזמן \u0003שנשחטה\u0004 חשב עליה לאוכלה או לזרוק את דמה או להקטיר את אימוריה \u0003חוץ לזמנה\u0004 הראוי, \u0003ו\u0004כן זה שחשב לעשות כן \u0003חוץ למקומה\u0004 הראוי, או \u0003שקבלו\u0004 את דם הקרבן כהנים ה\u0003פסולין\u0004 לעבודה, \u0003ו\u0004כן אם \u0003זרקו\u0004 הפסולים \u0003את דמה.\u0004 שבכל אלו, כיון שלא היתה שעה שבשר הקרבן היה מותר באכילה, הרי זה בכלל \"קדשי ה' \", ומועלים בו.","ומדייקים בדברים: \u0003קתני מיהא רישא\u0004 \u0005[שנה\u0006 התנא \u0005על כל פנים בהתחלה]\u0006 בבשר הקדשים \u0003שלנה ושנטמאת ושיצאה\u0004 שהיה לו שעת הכושר, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ש\u0003לנה ממש,\u0004 לפני זריקת הדם, ולא נזרק הדם, \u0003ו\u0004הרי איפוא \u0003הכא\u0004 \u0005[כאן]\u0006 במקרה זה, \u0003דאי בעי הוה זריק הוא\u0004 \u0005[שאם רצה היה זורק]\u0006 ולא היה נפסל הקרבן, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה\u0006 בו התנא\u0005]\u0006 ש\u0003אין מועלין\u0004 בו, משום שהיתה לו שעת הכושר ובודאי משום שכל העומד להיזרק כזרוק הוא נחשב, ושלא כדברי רב אשי!","ודוחים: \u0003לא,\u0004 הכוונה בדברי המשנה שיצא בזמן שהיא \u0003ראויה לצאת,\u0004 לאחר שכבר נזרק הדם, והותר הבשר באכילה \u0003ו\u0004נטמא בזמן שהוא \u0003ראויה לטמא,\u0004 לאחר שכבר \u0003נזרק הדם,\u0004 \u0003ו\u0004לן בזמן שהוא \u0003ראויה ללין,\u0004 לאחר שכבר נזרק הדם. ומשום כך, כמי שהיתה לו שעת הכושר, ויצא מכלל מעילה.","ושואלים עוד על דברי רב אשי: \u0003אבל\u0004 לשיטה זו, אם היתה זו \u0003לינה ממש\u0004 של הבשר קודם זריקת הדם, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003מועלין\u0004 בבשר, שהרי לא היתה שעת הכושר לכהנים לאכילתו שטרם נזרק הדם. אם כן \u0003האי\u0004 \u0005[זה]\u0006 ששנינו בברייתא \u0003\"כל שהיה לו שעת היתר לכהנים\" ו\"כל שלא היתה לו שעת היתר לכהנים\"\u0004 אינם לשונות ראויים, שכן עולה מהן שהדבר הקובע הוא אם היתה שעה שהיה הבשר ראוי לאכילה, אף שלא הותר בפועל ממש לאכול.","אלא \u0003\"כל שיש לו\u0004 (בפועל) \u0003שעת היתר\u0004 אכילה \u0003לכהנים אין מועלין בה\", ו\"כל שאין לה שעת היתר לכהנים מועלין בה\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לתנא לשנות\u0005]!\u0006","\u0003אלא אמר רב אשי\u0004 הסבר אחר במשנה: אכן מדובר שלן הבשר קודם זריקת הדם, ויצא הבשר מכלל מעילה משום שכל העומד להיזרק כזרוק הוא נחשב. ואולם לדעתו תמוהים דברי המקשה מכאן על דברי ר' שמעון בענין הראוי לקבלת טומאת אוכלין, וכי מדין \u0003מעילה\u0004 על דין \u0003ט\u0004 \u0003ומאה קא רמית\u0004 \u0005[אתה משליך,\u0006 מראה סתירה\u0005]?\u0006","והרי אלה דינים שונים, שכן הדין ב\u0003מעילה\u0004 \u0003משום קדושה ולאו\u0004 \u0005[ולא]\u0006 \u0003קדושה היא\u0004 נקבעת. שרק דבר שהוא בכלל \"קדשי ה' \" — יש בו דין מעילה. ולכך, \u0003לבתר\u0004 \u0005[לאחר]\u0006 שכבר \u0003פ\u0004 \u0003קעה לה קדושתיה\u0004 \u0005[קדושתו]\u0006 של בשר הקרבן, בשעה שעומד דמו להיזרק, \u0003במאי הדרא רכבא לה\u0004 \u0005[במה חוזרת\u0006 קדושה זו ו\u0005רוכבת,\u0006 חלה, \u0005עליו\u0006 שוב\u0005]?\u0006","ואילו הדין בקבלת \u0003טומאה משום אוכלא\u0004 \u0005[אוכל]\u0006 \u0003ולאו (משום) אוכלא\u0004 \u0005[ולא אוכל]\u0006 \u0003היא,\u0004 שכל שיש עליו \u0003שם אוכל —\u0004 הריהו מקבל טומאת אוכלין, וכל שאין עליו \u0003שם אוכל —\u0004 אינו מקבל טומאת אוכלין. ולכך, \u0003כל היכא דאי בעי זריק מצי זריק ליה\u0004 \u0005[כל מקום שאם רצה לזרוק יכול הוא לזרוק],\u0006 ועל ידי זריקתו זו — הריהו \u0003משוי ליה אוכלא\u0004 \u0005[עושה אותו אוכל],\u0006 \u0003ומטמא טומאת אוכלין.\u0004 וכל \u0003היכא דאי בעי (מצי) זריק לא מצי זריק\u0004 \u0005[מקום שאם רצה לזרוק\u0006 את הדם \u0005אינו יכול לזרוק],\u0006 ואף אם זרקו — לא הועיל — \u0003לא משוי ליה אוכלא\u0004 \u0005[לא עושה אותו אוכל],\u0006 \u0003ו\u0004לכן הוא \u0003לא מטמא טומאת אוכלין.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על דברי רב אשי שאין אומרים שהעומד להיזרק כזרוק הוא נחשב לענין קבלת טומאה, ממה ששנינו: אדם \u0003המביא אשם תלוי\u0004 על ספק עבירה בשוגג שבידו, כגון שהיו לפניו שתי חתיכות, ואכל אחת מהן מתוך מחשבה ששתיהן מותרות באכילה והתברר לו שאחת מהן היתה חלב ואחת שומן, ואינו יודע איזו מהן אכל, והביא קרבן אשם תלוי כראוי לו, \u0003ו\u0004לאחר מכן \u0003נודע\u0004 לו \u0003שלא חטא,\u0004 שהחתיכה שאכל היתה שומן, \u0003אם עד שלא נשחט\u0004 האשם \u0003נודע לו\u0004 כך — \u0003יצא\u0004 האיל המוקדש \u0003וירעה בעדר\u0004 כחולין גמורים, משום שהיה זה הקדש בטעות, אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004"],["אין דינו כבהמת חולין, אלא כאשם שנפסל, ולכן \u0003ירעה\u0004 בחוץ \u0003עד שיסתאב\u0004 (שיפול בו מום), \u0003ו\u0004אז \u0003ימכר, ויפלו\u0004 (יעברו) \u0003דמיו לנדבה\u0004 (לקרבן עולה של ציבור). \u0003ר' אליעזר אומר:\u0004 קרבן זה \u0003יקריב\u0004 כמות שהוא, \u0003שאם אינו בא על חטא זה\u0004 שלא חטא בו — \u0003הרי הוא בא על חטא אחר\u0004 שודאי שבמהלך חייו חטא ולא נודע לו עליו.","\u0003אם\u0004 \u0003מש\u0004 כבר \u0003נשחט\u0004 האשם התלוי, וקיבל דמו בכוס כדי לזורקו על המזבח \u0003נודע לו\u0004 שלא חטא — לא יזרק \u0003הדם,\u0004 אלא \u0003ישפך\u0004 לאמה העוברת בעזרה, \u0003והבשר ישרף\u0004 בבית השריפה, כדין קרבן פסול.","ואם \u0003נזרק הדם\u0004 על המזבח קודם שנודע לו, והבשר עדיין קיים — \u0003הבשר יאכל\u0004 לכהנים, כדינו, שמשעה שנזרק הדם נגמרה כפרתו, והותר הבשר לאכילת כהנים. \u0003ור' יוסי אומר: אפילו\u0004 היה \u0003הדם\u0004 נתון עדיין \u0003בכוס\u0004 כשנודע לו שלא חטא — \u0003יזרק\u0004 הדם על המזבח, \u0003והבשר יאכל.\u0004 שכבר התקדש הדם בכלי.","\u0003ואמר רבא\u0004 בהסבר טעמו: \u0003ר' יוסי בשיטת ר' שמעון אמר\u0004 דבר זה, ש\u0003אמר\u0004 ר' שמעון: \u0003כל העומד לזרוק\u0004 — \u0003כזרוק דמי\u0004 \u0005[נחשב],\u0006 ואף דם זה כיון שהוא נתון בכוס, ועומד להיזרק, נחשב כזרוק הן לענין היתר אכילת הבשר והן לענין זריקת הדם בפועל. ומכאן קושיה על שיטת רב אשי הסובר שאין אומרים כל העומד להיזרק הריהו כזרוק!","ומשיבים: \u0003מידי\u0004 \u0005[כלום]\u0006 זה \u0003הוא טעמא\u0004 \u0005[הטעם]\u0006 לשיטת ר' יוסי? והרי \u0003אמרי במערבא משמיה\u0004 \u0005[אומרים\u0006 חכמים ש\u0005בארץ ישראל משמו]\u0006 של \u0003ר' יוסי בר חנינא: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' יוסי, דקסבר\u0004 \u0005[שסבור הוא]:\u0006 \u0003כלי שרת מקדשין\u0004 אף \u0003את הפסולין לכתחילה ליקרב\u0004 על המזבח.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: מדאמר\u0004 \u0005[מ\u0006מה \u0005שאמר]\u0006 \u0003ר' שמעון\u0004 ש\u0003כל העומד לזרוק כזרוק דמי\u0004 \u0005[נחשב],\u0006 מסתבר שלדעתו אף \u0003כל העומד לשרוף נמי\u0004 \u0005[גם כן]\u0006 — \u0003כשרוף\u0004 הוא \u0003דמי\u0004 \u0005[נחשב],\u0006 ואם כן, בשר הקרבן ה\u0003נותר ו\u0004בשר ה\u0003פרה\u0004 אדומה משנשחטה שלדעת ר' שמעון (כפי ששנינו בברייתא בעמוד הקודם) הם מיטמאים טומאת אוכלין, שכן היתה להם שעת הכושר, \u0003אמאי\u0004 \u0005[מדוע]\u0006 הם \u0003מטמאין\u0004 ב\u0003טומאת אוכלין?\u0004 והלא \u0003עפרא בעלמא נינהו\u0004 \u0005[עפר סתם הם],\u0006 שהרי הם עומדים \u0005להישרף, ושוב אינם בכלל אוכל!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא לרב אשי: אף שאינם אוכל, מכל מקום \u0003חיבת הקודש מכשרתן\u0004 להיחשב כאוכל, ולכך מקבלים טומאת אוכלין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 \u0003נהי דמהניא להו\u0004 \u0005[אם אמנם שמועילה להם]\u0006 \u0003חיבת הקודש לאיפסולי דגופיה\u0004 \u0005[לפסול את גופו],\u0006 שייחשב בשר הנותר והפרה האדומה כאוכל לענין שהוא עצמו ייטמא בטומאת אוכלין, ואולם האם מועילה גם \u0003ליקרויי\u0004 \u0005[לקוראו,\u0006 להחשיבו\u0005]\u0006 כ\u0003טמא\u0004 ממש \u0003נמי\u0004 \u0005[גם כן],\u0006 לענין שיטמא אחרים במגעו, ומעתה \u0003יש\u0004 \u0003למימני ביה\u0004 \u0005[למנות בו]\u0006 את דרגות הטומאה השונות, שאם נגע \u0003בשר זה באב הטומאה ייחשב ל\u0004\u0003ראשון\u0004 לטומאה, \u0003ו\u0004הנוגע בו ייחשב ל\u0003שני\u0004 לטומאה?!","שהרי אם כך היא הלכה, \u0003תפשוט\u0004 \u0005[תפתור]\u0006 מכאן בעיה זו \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003ריש לקיש\u0004 בדינו של \u0003צריד\u0004 (החלק היבש והקשה) \u0003של מנחות,\u0004 שלא נבלל בשמן (ולא הוכשר איפוא לקבל טומאה מדין תורה. ואין טומאתו אלא משום חיבת הקודש), האם \u0003מונין בו ראשון ושני או אין מונין בו ראשון ושני!\u0004","ומשיבים: \u0003כי מיבעיא ליה\u0004 \u0005[כאשר נשאלה לו]\u0006 \u0003לריש לקיש\u0004 שאלתו זו בענין הצריד — הרי זה לענין דין \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ולענין שישרף אף השני לטומאה (שנטמא על ידי \u0003הצריד).\u0004 \u0003כי קאמרינן\u0004 \u0005[כאשר אמרנו]\u0006 כאן, לענין בשר הנותר ופרה אדומה בטומאת אוכלין — הרי זה לענין דין \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 ולענין שיתלו (שאינו נאכל ואינו נשרף) את השני לטומאה, אך לא לשורפו, שאין שורפים קדשים הטמאים מדברי חכמים בלבד\u0005.\u0006","\u0003האומר\u0004 בלשון נדר \u0003\"הרי עלי\u0004 להביא מנחה הנעשית \u0003במחבת\" והביא\u0004 מנחה שנעשתה \u0003במרחשת,\u0004 או שאמר \"הרי עלי להביא מנחה הנעשית \u0003במרחשת\" והביא\u0004 מנחה שנעשתה \u0003במחבת\u0004 — \u0003מה שהביא הביא,\u0004 שכשרה היא המנחה שהביא, אבל \u0003ידי חובתו\u0004 לקיום נדרו \u0003לא יצא\u0004 בהקרבתה, וצריך להביא מנחה אחרת, וכפי שנדר.","היה לפניו עשרון סולת, ואמר בלשון נדבה \"הרי \u0003זו\u0004 מנחה \u0003להביא\u0004 \u0003במחבת\"\u0004 \u0003והביא\u0004 אותה \u0003במרחשת.\u0004 או שאמר \"הרי זו מנחה להביא \u0003במרחשת\" והביא\u0004 אותה \u0003במחבת\u0004 — \u0003הרי זו פסולה,\u0004 שהרי לא קיים את מה שאמר.","\u0003האומר\u0004 בלשון נדר \u0003\"הרי עלי שני עשרונות\u0004 סולת למנחה \u0003להביא\u0004 אותה \u0003בכלי אחד\", והביא\u0004 שתי מנחות בנות עשרון \u0003בשני כלים,\u0004 וקמץ משתיהן שתי קמיצות. או שאמר \"הרי עלי להביא שני עשרונים סולת לשתי מנחות \u0003בשני כלים\", והביא\u0004 מנחה אחת בת שני עשרונים \u0003בכלי אחד,\u0004 וקמץ ממנה קמיצה אחת — \u0003מה שהביא הביא,\u0004 שכשרה היא מנחה זו לנדבה, \u0003ו\u0004אולם \u0003ידי\u0004 מנחת \u0003חובתו\u0004 (כפי שנדר) \u0003לא יצא,\u0004 וצריך להביא מנחה אחרת כפי שנדר.","היו לפניו שני עשרונים סולת, ואמר \"הרי \u0003אלו\u0004 מנחה להביא \u0003בכלי אחד\" והביא\u0004 אותם כשתי מנחות \u0003בשני כלים,\u0004 או שאמר \"הרי אלו מנחות להביא \u0003בשני כלים\", והביא\u0004 אותם כמנחה אחת בת שני עשרונים \u0003בכלי אחד\u0004 — \u0003הרי אלו פסולין.\u0004 שהרי כשנדר להביאם כמנחה אחת, התכוין שתיעשה בהם קמיצה אחת, וכשהביא אותם כשתי מנחות ונקמצו בשתי קמיצות — נמצא שהוסיף בקמיצות על מה שנדר. וכן כשנדר להביאם כשתי מנחות, התכוין שתיעשנה בהן שתי קמיצות, וכשהביא אותם כמנחה אחת ונקמצה זו בקמיצה אחת — נמצא שמיעט בקמיצות ממה שנדר.","אם אמר בלשון נדר \u0003\"הרי עלי שני עשרונות\u0004 סלת \u0003להביא\u0004 מנחה \u0003בכלי אחד\" והביא\u0004 אותם כשתי מנחות הנתונות \u0003בשני כלים,\u0004 ו\u0003אמרו לו\u0004 להזכירו: לא כך נדרת, אלא \u0003בכלי אחד נדרת\u0004 להביא. ולאחר שהזכירוהו עמד \u0003ו\u0004\u0003הקריבן בשני כלים\u0004 כשתי מנחות — הריהם \u0003פסולין\u0004 אף כמנחת נדבה, וצריך להביא מנחה אחרת לחובתו. שכיון שהזכירוהו היה עליו להשיב להם כי הוא מביא את המנחות הללו לא כתשלום נדר זה, ומתוך שלא אמר כן, גילה דעתו שמביאן כתשלום מנחת נדרו, וכיון ששינה בהן ממה שנדר, הריהן פסולות. ואולם אם לאחר שהזכירוהו, עמד והקריבן \u0003בכלי אחד\u0004 — \u0003כשרין,\u0004 שהרי הקריב כפי שנדר.","אם אמר \u0003\"הרי עלי שני עשרונות\u0004 סולת \u0003להביא\u0004 בשתי מנחות \u0003בשני כלים\", והביא\u0004 אותם כמנחה אחת \u0003בכלי אחד,\u0004 ו\u0003אמרו לו\u0004 להזכירו: לא כך נדרת אלא \u0003בשני כלים נדרת\u0004 להביא, אם לאחר מכן \u0003הקריבן בשני כלים\u0004 וכפי שנדר בתחילה — הריהם \u0003כשרין\u0004 ויצא ידי נדרו. ואם עמד ו\u0003נתנו\u0004 לשני העשרונים הללו \u0003לכלי אחד\u0004 כמנחה אחת — דינה \u0003כ\u0004דינן של \u0003שתי מנחות\u0004 שלא נקמצו עדיין, \u0003ש\u0004נפלו לכלי אחד, ו\u0003נתערבו\u0004 זו בזו. שנקבע בהן (לעיל מנחות כג,א) שאם ניתן לקמוץ מכל אחת מהן קומץ בלי תערובת של המנחה האחרת, הריהן כשרות. ואם לא ניתן לעשות כן, הריהן פסולות.","שנינו במשנתנו את דין המנחה ודין הנודר להביא מנחת כלי מסויים (מחבת, מרחשת) והביא מנחת כלי אחר, וכן את דין המנחה ודין הנודר להביא מנחה בכלי אחד או בשני כלים, והביא שלא כנדרו. ובשני האופנים הללו המנחה כשרה, ולא יצא ידי חובתו, וצריך להביא מנחה אחרת כפי שנדר. ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שני הדינים הללו.","\u0003דאי אשמעינן הך קמייתא\u0004 \u0005[ש\u0006כן \u0005אם\u0006 התנא \u0005היה משמיע לנו\u0006 רק את \u0005זו\u0006 ההלכה \u0005הראשונה],\u0006 הייתי אומר שלא יצא בכך ידי נדרו, \u0003משום\u0004 שנדר ו\u0003אמר \"במחבת\" וקא מייתי\u0004 \u0005[והוא מביא]\u0006 \u0003במרחשת,\u0004 והרי זו מנחה אחרת. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בהלכה השניה, בזה ששינה ממספר המנחות שנדר, \u0003דאידי ואידי\u0004 \u0005[שזו\u0006 המנחה שנדר, \u0005וזו\u0006 המנחה שהביא בפועל\u0005]\u0006 שתיהן \u0003הן\u0004 \u0003במחבת ו\u0004כמו כן \u0003אידי ואידי\u0004 \u0005[וזו וזו]\u0006 היא \u0003במרחשת\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003ידי נדרו נמי\u0004 \u0005[גם כן]\u0006 \u0003יצא,\u0004 ואין השינוי במספר המנחות נחשב שלא יצא ידי חובתו. ולכך התנא צריך להשמיענו גם את ההלכה השניה.","\u0003ו\u0004מן הצד האחר, \u0003אי אשמעינן הך\u0004 \u0005[אם\u0006 התנא \u0005היה משמיענו\u0006 רק את \u0005ההלכה\u0006 \u0005הזו,\u0006 בזה המשנה ממספר המנחות שנדר\u0005],\u0006 ולא היה משמיע לנו גם את ההלכה הראשונה, בזה המשנה בסוג הכלי בו נעשית המנחה, הייתי אומר שלא יצא בכך ידי נדרו, \u0003משום דקא פליג להו\u0004 \u0005[שהוא מחלק אותם,\u0006 את שני העשרונים המיועדים למנחה אחת, לשתי מנחות\u0005]\u0006 שלא כפי שנדר. \u0003אבל התם\u0004 \u0005[שם,\u0006 בהלכה הראשונה שבמשנה\u0005],\u0006 בזה המשנה בסוג הכלי בו נעשית המנחה, ש\u0003לא פליג ביה\u0004 \u0005[לא חילק אותו,\u0006 את הסולת למנחה\u0005]\u0006 אלא רק עשאה בכלי אחר — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 כך יהיה דינו אלא יצא ידי חובתו בכך, ופרע נדרו בזאת. על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 התנא לשנות את שתי ההלכות הללו.","ועוד בדינו של הנודר להביא מנחה באופן מסויים (בכלי, או במספר המנחות) והביא באופן אחר, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא, ובדומה לשנוי במשנתנו, כי \u0003מה שהביא הביא,\u0004 וכשרות המנחות הללו, \u0003ו\u0004אולם \u0003ידי נדרו לא יצא\u0004 בכך. \u0003ר' שמעון אמר: אף ידי נדרו נמי\u0004 \u0005[גם כן]\u0006 \u0003יצא\u0004 בכך. כיון שאין קביעתו של הנודר, אם לענין סוג הכלי או \u0003באשר לכמה כלים תבוא המנחה, נחשבת כשינוי בנדר, ויצא ידי חובתו.\u0004","עוד שנינו במשנתנו שאם היה עשרון סולת מונח לפניו, ואמר \"הרי \u0003זו\u0004 מנחה \u0003להביא במחבת\"\u0004 והביא במרחשת \u0003—\u0004 הריהי פסולה. ומקשים על כך: \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 כי בכגון זה \u0003לא קידשום כלי שרת\u0004 את המנחה שניתנה בהם, כיון שהרי אלה כלי שרת שונים מכפי שנדר, והרי איפוא המנחה עדיין חולין, ולא מנחה פסולה! \u0003אמר אביי:\u0004 כוונת דברי הברייתא ש\u0003לא קידשום\u0004 לענין \u0003ליקרב\u0004 על המזבח. \u0003אבל\u0004 על כל פנים \u0003קידשום\u0004 לענין \u0003ליפסל,\u0004 שגדולה קדושת הכלי להחיל עליהם מקצת קדושה לפסול.","שנינו במשנה שהאומר על עשרון סולת המונח לפניו \"הרי זו מנחה להביאה במחבת\" והביאה במרחשת שהיא פסולה, לפי ששינה את המנחה ממה שנדר בה. \u0003ו\u0004על כך \u0003אמר אביי: לא שנו\u0004 כן"],["\u0003אלא שקבען\u0004 אם יבואו במחבת אם במרחשת \u0003בשעת\u0004 ה\u0003נדר,\u0004 כשאמר \"הרי עלי להביא את זו במחבת\" (וכיוצא בדבר, במרחשת). שבכך נקבע דינם להיעשות דווקא כמו שאמר. \u0003אבל\u0004 אם כשנדר להביא מנחה אמר סתם \"הרי עלי \u0003מנחה\", ו\u0004\u0003בשעת הפרשה\u0004 של הסולת למנחה קבעה לשם מנחה מסויימת, וכגון שאמר \"זו אביא לשם נדרי, ובמחבת\" — בכך \u0003לא\u0004 נקבע שתיעשה דווקא במחבת, ואם הביאה כמנחת מרחשת — יצא בה ידי נדרו.","וטעם הדבר, שכן נאמר בחובת קיום הנדרים \u0003\"מוצא שפתיך תשמור ועשית כאשר נדרת\u0004 לה' אלהיך נדבה אשר דברת בפיך\" (דברים כג, כד), והדגיש הכתוב \"ועשית \u0003כאשר נדרת...\u0004 אשר דברת בפיך\" — ולמעט: \u0003ולא כאשר הפרשת\u0004 את נדרך.","\u0003ומעירים:\u0004 \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 אותו דבר בשם אמורא אחר, ש\u0003אמר ר' אחא בר חנינא, אמר ר' אסי, אמר\u0004 \u0003ר' יוחנן: לא שנו\u0004 שאם שינה ממה שנדר, שהמנחה פסולה, \u0003אלא\u0004 בזמן ששינה ממה \u0003שקבען בשעת נדר, אבל\u0004 אם שינה ממה שקבען \u0003בשעת הפרשה\u0004 — \u0003לא\u0004 נפסלה בכך המנחה, שנאמר בחיוב קיום הנדר \"ועשית \u0003כאשר\u0004 \u0003נדרת\" ולא כאשר הפרשת.\u0004","\u0003האומר\u0004 בלשון נדר \u0003\"הרי עלי\u0004 להביא \u0003מנחה מן השעורים\",\u0004 והרי מנחת נדבה באה רק מן החיטים — \u0003יביא מן החטים.\u0004 האומר \"הרי עלי להביא מנחה מן ה\u0003קמח\"\u0004 — \u0003יביא סולת\u0004 למנחתו, שכן מנחת נדבה באה מן הסולת (\"סלת יהיה קרבנו\". ויקרא ב, א). האומר \"הרי עלי להביא מנחה \u0003בלא שמן ובלא לבונה\"\u0004 — \u0003יביא\u0004 עם מנחתו \u0003שמן ולבונה,\u0004 שכן מנחת נדבה טעונה שמן ולבונה.","האומר \"הרי עלי להביא מנחה של \u0003חצי עשרון\u0004 סולת\" — \u0003יביא\u0004 מנחה של \u0003עשרון\u0004 סולת \u0003שלם,\u0004 שכן אין מנחת נדבה באה בפחות מעשרון סולת. האומר \"הרי עלי להביא מנחה של \u0003עשרון ומחצה\u0004 סולת\" — \u0003יביא שנים\u0004 עשרונים סולת, שהרי אין מביאים במנחה אלא עשרונים שלמים, ולא חצאים. \u0003ר' שמעון פוטר\u0004 בכל האופנים הללו מלהביא מנחה כלל, שלדעתו לא חל נדר זה, כיון \u0003שלא התנדב כדרך המתנדבין.\u0004","שנינו במשנתנו כי האומר \"הרי עלי להביא מנחה מן השעורים\", חל נדרו, אבל מביא מנחה מן החיטים, כמצוותו. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 חל הנדר? \u0003הלא\u0004 \u0003נדר ופתחו\u0004 (חרטתו, יציאתו מהנדר) \u0003עמו הוא,\u0004 ואין הנדר חל כלל. שהרי כשאמר \"הרי עלי להביא מנחה\" — אכן נדר, ואולם כשהוסיף ואמר \"מן השעורים\" — הרי בכך התחרט וחזר בו מן הנדר, שהרי יודע שאין המנחה באה מן השעורים!","\u0003אמר חזקיה: הא\u0004 \u0005[זו]\u0006 משנתנו כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 כשיטת \u0003בית שמאי היא, דאמרי\u0004 \u0005[שאומרים]\u0006 ככלל שכאשר אומר אדם דבר אחד ולאחר מכן אומר דבר הסותר את דבריו הראשונים, שיש ל\u0003תפוס\u0004 כעיקר את ה\u0003לשון\u0004 ה\u0003ראשון.\u0004 ולכך בענייננו, כיון שבלשונו הראשון אמר \"הרי עלי מנחה\", אף שאמר לאחר מכן \"מן השעורים\", וכמבקש לבטל את דבריו הראשונים — דבריו הראשונים קיימים. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0003]:\u0004 האומר \u0003\"הריני נזיר\u0004 \u0003מן הגרוגרות\u0004 (תאנים מיובשות) \u0003ומן\u0004 \u0003הדבילה\u0004 (גוש של תאנים מיובשות)\" — \u0003בית שמאי אומרים:\u0004 הריהו \u0003נזיר\u0004 גמור, שבמה שאמר \"הריני נזיר\" — קיבל על עצמו נזירות, ומה שהוסיף ואמר \"מן הגרוגרות ומן הדבילה\" אין בדבריו ממש. \u0003ובית הלל אומרים: אינו נזיר,\u0004 שמסוף דבריו רואים שלא קיבל עליו נזירות.","ואילו \u0003ר' יוחנן אמר: אפילו\u0004 אם \u0003תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו היא כשיטת \u0003בית הלל,\u0004 לא יקשה על משנתנו, שכן מדובר בה \u0003באומר\u0004 הנודר, לכשאומרים לו שאין נודרים כך למנחה, \u0003\"אילו הייתי יודע שאין נודרין כך\u0004 למנחה (מדבר שאין המנחה באה ממנו, כגון שעורים), \u0003לא הייתי נודר כך אלא כך\u0004 (מחיטים)\".","ובעקבות דברי חזקיה ור' יוחנן אלה מביאים עוד מה ש\u0003אמר חזקיה: לא שנו\u0004 שכך הדין \u0003אלא\u0004 בזה ש\u0003אמר\u0004 בנדרו \"הרי עלי להביא \u0003מנחה מן\u0004 \u0003השעורים\", אבל\u0004 אם \u0003אמר\u0004 \"הרי עלי להביא \u0003מנחה מן העדשים\"\u0004 — \u0003לא\u0004 חל עליו הנדר כלל.","ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003חזקיה כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 \u0003אמר לשמעתיה\u0004 \u0005[את שמועתו]?\u0006 — \u0003כ\u0004דעת \u0003בית שמאי, ובית שמאי,\u0004 \u0003משום\u0004 שלדעתם בכל מקרה של סתירה בין דבריו הראשונים של האדם לבין דבריו האחרונים יש ל\u0003תפוס לשון ראשון הוא.\u0004 אם כן, \u0003מה לי\u0004 אם אמר \"הרי עלי להביא מנחה \u0003מן\u0004 \u0003השעורין\" מה לי\u0004 אם אמר \"הרי עלי להביא מנחה \u0003מן העדשים\",\u0004 בשני האופנים יש לתפוס לשון ראשון, וחייב להביא מנחה! ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 חזקיה מסברתו המעמידה את דברי המשנה כשיטת בית שמאי, ומפרש גם הוא כר' יוחנן.","\u0003ו\u0004שואלים: \u0003מ\u0004\u0003אי טעמא הדר ביה\u0004 \u0005[מה טעם חזר בו]?\u0006 \u0003אמר רבא: מתניתין קשיתיה\u0004 \u0005[משנתנו היתה קשה לו],\u0006 \u0003מאי איריא דתני\u0004 \u0005[מה שייך,\u0006 מהו הענין \u0005ש\u0006בגללו \u0005שנה\u0006 התנא\u0003]\u0004 במשנתנו דווקא שאמר \"הרי עלי להביא \u0003מנחה מן השעורים\"? ליתני\u0004 \u0005[שישנה]\u0006 חידוש גדול יותר, שאמר \"הרי עלי להביא מנחה \u0003מן העדשים\",\u0004 שאפילו בכגון זה הריהו חייב במנחה!","\u0003אלא\u0004 מתוך ש\u0003אמרה המשנה כך,\u0004 \u0003שמע מינה\u0004 \u0005[למד ממנה,\u0006 מכאן\u0005]\u0006 שעיקר טעמה הוא \u0003משום דטעי\u0004 \u0005[שטעה]\u0006 \u0003הוא\u0004 הנודר, שחשב שמביאים מנחה אף מן השעורים. ואולם \u0003בשעורים טעי\u0004 \u0005[טועה],\u0006 שהרי יש מנחת יחיד הבאה מן השעורים (מנחת קנאות), אבל \u0003בעדשים לא טעי\u0004 \u0005[לא טועה]\u0006 לחשוב שמביאים מנחה מהם, ולכן וודאי התכוון לבטל את דבריו הראשונים.","\u0003ו\u0004אילו \u0003ר' יוחנן אמר:\u0004 לשיטת המשנה \u0003אפילו\u0004 אם אמר \"הרי עלי להביא מנחה \u0003מן העדשים\",\u0004 חל הנדר. ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003ר' יוחנן כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 \u0003אמרה לשמעתיה\u0004 \u0005[את שמועתו],\u0006 כלומר, כשיטת מי הוא מפרש את דברי משנתנו — \u0003כ\u0004דעת \u0003בית הלל, ו\u0004הרי טעמם של \u0003בית הלל\u0004 שחל הנדר הוא \u0003משום דטעי\u0004 \u0005[שטועה]\u0006 \u0003הוא\u0004 בזה שאמר \"מן השעורים\", ומעתה יש לומר כי \u0003בשעורין טעי\u0004 \u0005[טועה]\u0006 אדם וסבור שמנחה באה מהן, אך \u0003בעדשים\u0004 אדם \u0003לא טעי\u0004 \u0005[לא טועה]\u0006 לחשוב שמביאים מהן מנחה!","ומשיבים: אכן ר' יוחנן עצמו סבור שאין דין משנתנו אמור אלא באומר \"מן השעורים\" ולא באומר \"מן העדשים\". ואולם מה שאמר ר' יוחנן שמשנתנו אמורה אף באומר \"מן העדשים\" — כמענה \u0003לדבריו\u0004 של \u0003חזקיה קאמר ליה\u0004 \u0005[אמר לו]\u0006 ר' יוחנן, שכך אמר לו: \u0003את מאי טעמא הדרת\u0004 \u0005[אתה מה טעם חזרת]\u0006 \u0003בך\u0004 מהסברך שמשנתנו כשיטת בית שמאי? \u0003משום\u0004 ש\u0003לא קתני\u0004 \u0005[לא שנה]\u0006 התנא במשנתנו \u0003\"מן העדשים\",\u0004 שהוא חידוש דין גדול יותר מ\"מן השעורים\" — על כך יש להשיב כי","\u0003דלמא\u0004 \u0005[שמא]\u0006 המשנה בסדר של \u0003\"\u0004\u0003לא מיבעיא\" קאמר\u0004 \u0005[\"לא נצרכה\" אמר,\u0006 נסדרה המשנה\u0005],\u0006 ובאופן זה: \u0003לא מיבעיא\u0004 \u0005[אין צריך]\u0006 לומר שאם אמר \"הרי עלי להביא מנחה \u0003מן העדשים\",\u0004 שחייב במנחה, משום \u0003דאיכא למימר מהדר הוא דהדר ביה\u0004 \u0005[שיש מקום לומר\u0006 שבסיום \u0005ח\u0006 זר בו] מדבריו הראשונים, \u0003ו\u0004חייב במנחה משום שיטת בית שמאי האומרת כי יש ל\u0003תפוס לשון ראשון. אלא אפילו\u0004 כשאמר \"הרי עלי להביא מנחה \u0003מן השעורין\" נמי\u0004 \u0005[גם כן]\u0006 \u0005חל נדרו, למרות\u0006 \u0003דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 כי \u0003מיטעא\u0004 \u0005[טעות]\u0006 \u0003הוא דקא טעי\u0004 \u0005[שהוא טעה],\u0006 ואילו היה יודע שאין מביאים מן השעורים לא היה נודר כלל — \u0003אפילו הכי\u0004 \u0005[כך]\u0006 חל הנדר והריהו חייב במנחה, משום הכלל \u0003תפוס לשון ראשון.\u0004"],["ועוד בפירוש דברי משנתנו בדין הנודר \"הרי עלי להביא מנחה מן השעורים\" שחל נדרו, \u0003אמר זעירי: לא שנו\u0004 שתופסים את תחילת דבריו שאמר \"הרי עלי להביא מנחה\", \u0003אלא\u0004 כאשר \u0003אמר\u0004 את המלה \u0003\"מנחה\"\u0004 בצורת נפרד, שמה שאמר לאחר מכן \"מן השעורים\" אין בו כדי לבטל את ראשית דבריו. \u0003אבל\u0004 כאשר \u0003לא אמר\u0004 את המלה \u0003\"מנחה\"\u0004 בצורת נפרד, אלא בצורת נסמך, וכגון \"הרי עלי להביא מנחת שעורים\" — \u0003לא\u0004 חל הנדר, ואינו חייב בהבאת מנחה. שכן מנוסח לשונו משמע שלא קיבל עליו להביא אלא מנחת שעורים.","ונמסר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב נחמן וקאמר לה להא שמעתא\u0004 \u0005[ואמר אותה, את השמועה,\u0006 ההלכה \u0005הזו]\u0006 של זעירי. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 על הלכה זו ממה ששנינו במשנתנו, שאם אמר בלשון נדרו \u0003\"קמח\"\u0004 ולא אמר \"סולת\" — התחייב במנחה, אף שאין המנחה באה מן הקמח, ו\u0003יביא סולת.\u0004 ומדייק רבא: \u0003לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003כש\u0004\u0003לא אמר\u0004 \"הרי עלי להביא \u0003מנחה\",\u0004 אלא \"הרי עלי להביא קמח\", ובכל זאת הריהו חייב במנחה. הרי שאין צורך לומר את המלה \"מנחה\" ובצורת נפרד, כדי להתחייב? השיב רב כהנא לרבא: \u0003לא,\u0004 אלא מדובר כש\u0003אמר\u0004 הנודר \"הרי עלי להביא \u0003מנחה\u0004 של קמח\".","חזר רבא והקשה כיוצא בזה ממה ששנינו עוד במשנתנו, בנודר להביא \u0003\"בלא שמן ולבונה\",\u0004 שחל נדרו, ו\u0003יביא\u0004 מנחה ב\u0003שמן ולבונה. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר במקרה ש\u0003לא אמר\u0004 לשון \u0003\"מנחה\",\u0004 ובכל זאת חל הנדר! השיב רב נחמן: \u0003לא,\u0004 אלא מדובר כש\u0003אמר\u0004 הנודר \"הרי עלי להביא \u0003מנחה\u0004 בלא שמן\" או שאמר \"הרי עלי להביא מנחה בלא לבונה\".","חזר רבא והקשה עוד ממשנתנו, בנודר להביא מנחה של \u0003חצי עשרון\u0004 סולת שחל עליו הנדר, ו\u0003יביא\u0004 \u0003עשרון שלם\u0004 של סולת. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר ש\u0003לא אמר\u0004 לשון \u0003\"מנחה\",\u0004 ובכל זאת חל הנדר! השיב רב נחמן: \u0003לא,\u0004 אלא מדובר כש\u0003אמר\u0004 הנודר \"הרי עלי להביא \u0003מנחה\u0004 של חצי עשרון סולת\".","הוסיף רבא והקשה: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבכל האופנים המדוברים במשנתנו אמר הנודר \"מנחה\", \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף]\u0006 המשנה, ששנינו בה שאם נדר \u0003\"עשרון ומחצה\"\u0004 שחל נדרו, ו\u0003יביא שנים.\u0004 והרי \u0003כיון\u0004 ש\u0003אמר\u0004 לשון \u0003\"מנחה\"\u0004 — כבר \u0003איחייב ליה\u0004 \u0005[התחייב לו]\u0006 בכך \u0003ב\u0004הבאת \u0003עשרון\u0004 סולת. ומעתה, \u0003כי\u0004 \u0005[כאשר]\u0006 הוסיף ו\u0003אמר \"חצי עשרון\"\u0004 — \u0003לא כלום קאמר\u0004 \u0005[אומר]\u0006 \u0003הוא,\u0004 שהרי זה נאמר ללא המלה \"מנחה\", שבלעדיה אין אדם מתחייב במנחה לשיטת זעירי!","השיב לו רב נחמן: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו להיאמר אלא כש\u0003אמר \"הרי עלי מנחה חצי עשרון ועשרון\",\u0004 ש\u0003כיון\u0004 ש\u0003אמר \"מנחה\"\u0004 — \u0003איחייב ליה\u0004 \u0005[התחייב לו]\u0006 \u0003בעשרון\u0004 סולת הבא למנחה. ומעתה, \u0003כי\u0004 \u0005[כאשר]\u0006 הוסיף ו\u0003אמר \"\u0004\u0003חצי עשרון\"\u0004 — \u0003ו\u0004\u0003לא כלום קאמר\u0004 \u0005[אמר],\u0006 שאין בדבריו אלה כל משמעות הלכתית, שהרי אין מנחה באה בחצי עשרון סולת. ואחר כך, \u0003כי הדר\u0004 \u0005[כאשר חזר]\u0006 ו\u0003אמר \"עשרון\"\u0004 — \u0003מייתי\u0004 \u0005[מביא]\u0006 \u0003עשרון אחרינא\u0004 \u0005[אחר]\u0006 במנחתו, ולכך חייב להביא שני עשרונים.","הוסיף רבא עוד ושאל: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מדובר במשנתנו, זה ששנינו עוד במשנתנו ש\u0003ר' שמעון פוטר\u0004 את הנודר מהבאת מנחה, בכל המקרים השנויים במשנתנו, משום \u0003שלא התנדב כדרך\u0004 \u0003המתנדבין,\u0004 יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוא פוטר? הרי כאן יש נדר ממש, שהרי אמר הנודר \"מנחה\"? \u0003אמר רבא: ר' שמעון בשיטת ר' יוסי אמרה,\u0004 ש\u0003אמר\u0004 ר' יוסי \u0003אף בגמר דבריו אדם מתפיס,\u0004 ולכן אף שאמר הנודר בתחילת דבריו \"מנחה\", כיון שאמר בסוף דבריו דברים שאינם נוהגים במנחת נדבה — אין נדרו חל.","\u0003מתנדב אדם\u0004 להביא \u0003מנחה\u0004 אף \u0003של ששים עשרון\u0004 סולת, \u0003ו\u0004הריהו \u0003מביא\u0004 את כל ששים העשרונים \u0003בכלי אחד. (אם אמר\u0004 בלשון נדר \u0003\"הרי עלי\u0004 להביא מנחה של \u0003ששים עשרון\"\u0004 — הריהו \u0003מביא\u0004 את כל ששים העשרונים \u0003בכלי אחד).\u0004 ו\u0003אם אמר \"הרי עלי\u0004 להביא מנחה של \u0003ששים ואחד\u0004 עשרונים סולת\" — הריהו \u0003מביא\u0004 שתי מנחות, מנחה אחת בת \u0003ששים\u0004 עשרונים \u0003בכלי אחד, ו\u0004מנחה שניה בת עשרון \u0003אחד\u0004 אף היא \u0003בכלי אחד,\u0004 משום שאין מביאים יותר מששים עשרונים סולת בכלי אחד. וטעם הדבר שאין מביא היחיד במנחתו יותר מששים עשרונים סולת בכלי אחד, \u0003שכן\u0004 המספר הרב ביותר של עשרונים סולת \u0003ש\u0004\u0003הציבור מביא\u0004 הריהו ששים ואחד. שהציבור מביא \u0003ביום טוב הראשון של חג\u0004 (הסוכות) \u0003שחל להיות ב\u0004יום \u0003ה\u0004\u0003ש\u0004\u0003בת,\u0004 בסך הכל \u0003ששים ואחד\u0004 עשרונים. שהרי ביום זה קרבים שלושה עשר פרים, שני אלים, ארבעה עשר כבשים, שני תמידים, ושני כבשי מוסף של שבת, ועם כל אחד מהם באים מנחות לפי חשבון זה: מנחתו של כל פר הריהי שלושה עשרונים סולת — הרי אלה שלושים ותשעה עשרונים; מנחתו של כל איל הריהי שני עשרונים — הרי אלה ארבעה עשרונים; מנחתו של כל כבש עשרון — הרי אלה ארבעה עשר עשרונים נוספים; מנחתו של כל אחד משני התמידים — עשרון אחד; מנחת כל אחד משני כבשי מוסף של שבת — עשרון אחד. הרי הכל ששים ואחד עשרונים.","ומעתה נאמר, כי \u0003דיו ל\u0004מנחתו של ה\u0003יחיד שהוא פחות מן הציבור\u0004 בעשרון \u0003אחד,\u0004 ויביא לכל היותר ששים עשרונים בכלי אחד.","\u0003אמר ר' שמעון:\u0004 מה הראיה ממנין העשרונים הבאים ביום טוב ראשון של חג הסוכות שחל בשבת, \u0003והלא\u0004 אין העשרונות הללו ניתנים בכלי אחד, שהרי עשרונות \u0003אלו\u0004 באים \u0003ל\u0004קרבנות ה\u0003פרים\u0004 ואילים, \u0003ו\u0004אילו \u0003עשרונות\u0004 \u0003אלו\u0004 באים \u0003ל\u0004קרבנות ה\u0003כבשים, ואינם נבללים זה עם זה,\u0004 שהרי אין מערבים בכלי אחד את המנחות של הפרים והאילים (שדרך בלילתם שווה: שני לוגים שמן לעשרון סולת) במנחות של הכבשים (שדרך בלילתם שונה: שלושה לוגים שמן לעשרון סולת)! \u0003אלא\u0004 טעם הדבר שאין מביאים יותר מששים עשרונים סולת בכלי אחד, הוא משום ש\u0003עד ששים\u0004 עשרונים — \u0003יכולין\u0004 הם \u0003ליבלל\u0004 בכלי אחד בשיעור לוג אחד שמן הניתן בהם, ואילו ששים ואחד עשרונים הנתונים בכלי אחד — אינם יכולים להיבלל בלוג אחד של שמן.","\u0003אמרו לו\u0004 חכמים בתמיהה: וכי \u0003ששים\u0004 עשרונים עדיין \u0003נבללין\u0004 בלוג שמן אחד, \u0003וששים ואחד\u0004 עשרונים \u0003אין נבללין?!\u0004 וכי תוספת מועטה של עשרון אחד, גורמת לכך שמעתה אין הם יכולים שוב להיבלל? \u0003אמר להם\u0004 ר' שמעון לחכמים: אין לתמוה על כך, שהרי \u0003כל מדות חכמים כן\u0004 הן, שיש להן גבול. ודוגמא לדבר: \u0003ב\u0004מקוה מים שיש בו שיעור \u0003ארבעים סאה\u0004 מים ראויים — \u0003הוא,\u0004 הטמא, \u0003טובל,\u0004 ונטהר\u0003.\u0004 \u0003ו\u0004אילו \u0003ב\u0004מקוה שיש בו \u0003ארבעים סאה\u0004 מים \u0003חסר קרטוב\u0004 (משהו) — הטמא \u0003אינו יכול לטבול בהן\u0004 כדי להיטהר מטומאתו.","\u0003שאיל\u0004 \u0005[שאלו]\u0006 חכמים \u0003שאילה למעלה\u0004 (לפני) \u0003מר' יהודה בר אילעאי: מנין\u0004 להלכה זו שה\u0003אומר \"הרי עלי ששים ואחד\u0004 עשרון למנחה\" שהוא \u0003מביא ששים\u0004 עשרונים \u0003בכלי אחד, ו\u0004עשרון \u0003אחד\u0004 נוסף \u0003בכלי אחד?\u0004","\u0003פתח ר' יהודה בר אילעאי\u0004 שהוא \u0003ראש המדברים בכל מקום, ואמר:\u0004 טעם הדבר, \u0003שכן מצינו\u0004 (מצאנו) ב\u0003ציבור\u0004 ש\u0003מביאין ביום טוב הראשון של חג\u0004 הסוכות \u0003שחל להיות ב\u0004יום ה\u0003שבת\u0004 מנחות שבכולן יחד \u0003ששים ואחד\u0004 עשרונים. ויש לומר כי \u0003דיו ליחיד שיפחות מן הציבור\u0004 עשרון \u0003אחד,\u0004 ולא יביא יתר על ששים עשרונים בכלי אחד.","\u0003אמר לו ר' שמעון:\u0004 אין ללמוד מכאן, \u0003והלא\u0004 אין העשרונות הללו ניתנים בכלי אחד, שהרי עשרונות \u0003אלו\u0004 (חלקם) באים לקרבנות ה\u0003פרים ואילים\u0004 שדרך בלילתם אחת, \u0003ו\u0004אילו \u0003עשרונות\u0004 \u0003אלו\u0004 באים לקרבנות ה\u0003כבשים,\u0004 שדרך בלילתם שונה. \u0003אלו,\u0004 מנחות הפרים והאילים, ניתנים בהם שני לוגים שמן לעשרון אחד של סולת ולכך \u0003בלילתן\u0004 (העיסה הנוצרת מהבלילה) \u0003עבה,\u0004 \u0003ואלו,\u0004 מנחות הכבשים, ניתנים בהם שלושה לוגים שמן לעשרון אחד של סולת ולכך \u0003בלילתן\u0004 \u0003רכה. אלו\u0004 (מנחת התמיד הקרב בבוקר ומנחת המוספים) \u0003בלילתן\u0004 נעשית \u0003ב\u0004\u0003שחרית ואלו\u0004 (מנחת התמיד הקרב בין הערביים) \u0003בלילתן\u0004 נעשית \u0003בין הערבים, ואין\u0004 הם \u0003נבללין מזה על זה,\u0004 ונמצא איפוא שלעולם אין הציבור מביא ששים ואחד עשרונים בכלי אחד!","\u0003אמרו לו\u0004 חכמים לר' שמעון: אם כן, \u0003אמור אתה\u0004 מה מקור הלכה זו. \u0003אמר להם: הרי הוא\u0004 הכתוב בדין המנחות \u0003אומר \"וכל מנחה בלולה בשמן\u0004 \u0003וחרבה\u0004 לכל בני אהרן תהיה איש כאחיו\" (ויקרא ז, י) — הרי מכאן נלמד, כי \u0003כבר אמרה תורה: הבא מנחה\u0004 באופן \u0003ש\u0004היא \u0003יכולה להיבלל\u0004 בשמן, ואילו ששים ואחד עשרונים סולת אינם יכולים להיבלל בלוג אחד של שמן.","\u0003אמר לו\u0004 ר' יהודה לר' שמעון בתמיהה על דבריו: וכי \u0003בששים\u0004 עשרונים הריהם \u0003נבללין\u0004 בלוג אחד של שמן, אך \u0003בששים ואחד\u0004 עשרונים \u0003אין\u0004 הם \u0003נבללין\u0004 בלוג אחד של שמן?! וכי בגלל תוספת עשרון סולת אחד, שוב אין כל המנחה נבללת?! \u0003אמר לו\u0004 ר' שמעון לר' יהודה: אין זו שאלה, שהרי \u0003כל מדת\u0004 (קביעות שיעורים) של \u0003חכמים כן הוא,\u0004 שיש שיעור מדוייק בדברים. ומביא ר' שמעון דוגמאות לדבר: \u0003ב\u0004מקוה מים שיש בו שיעור \u0003ארבעים סאה\u0004 מים ראויים — \u0003הוא,\u0004 הטמא, \u0003טובל,\u0004 ונטהר מטומאתו. ואילו \u0003ב\u0004מקוה שיש בו שיעור \u0003ארבעים סאה\u0004 מים \u0003חסר קרטוב\u0004 (משהו) — הטמא \u0003אינו יכול לטבול\u0004 כדי להיטהר מטומאתו.","וכיוצא בזה, כל דבר מאכל שיש בו \u0003כ\u0004שיעור \u0003ביצה\u0004 — הריהו \u0003מטמא טומאת אוכלין.\u0004 ואילו זה שיש בו \u0003כ\u0004שיעור \u0003ביצה חסר שומשום\u0004 (שהוא שיעור קטן ביותר) — \u0003אין מטמא טומאת אוכלין.\u0004 וכיוצא בדבר, בגד שיש בו כשיעור של \u0003שלשה\u0004 טפחים אורך \u0003על שלשה\u0004 טפחים רוחב — הריהו \u0003מטמא\u0004 (ראוי להיטמא) בטומאת \u0003מדרס\u0004 הזב, היושב או השוכב על בגד זה. ואילו בגד שיש בו כשיעור של \u0003שלשה על שלשה חסר נימא\u0004 \u0005[חוט]\u0006 \u0003אחת,\u0004 שהוא שיעור מועט ביותר — \u0003אינו מטמא מדרס.\u0004","ושואלים על הסברו זה של ר' שמעון: \u0003ו\u0004אולם גם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אין\u0004 ששים ואחד עשרונים סולת \u0003נבללין\u0004 בלוג אחד של שמן, \u0003מאי הוי\u0004 \u0005[מה קרה\u0006 בכך\u0005]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו]\u0006 שאף שמצוה לבלול את המנחה בשמנה, ואולם \u0003אם לא בלל\u0004 — הרי זה \u0003כשר!\u0004 \u0003אמר ר' זירא:\u0004 הלכה זו אמורה דווקא במנחה הראויה להיבלל, שמנחה כזו אף אם לא נבללה בפועל הריהי כשרה. ואולם מנחה שיש בה ששים ואחד עשרונים אינה ראויה כלל להיבלל. וכלל הוא: \u0003כל הראוי לבילה\u0004 (בלילה) — \u0003אין\u0004 ה\u0003בילה\u0004 בפועל \u0003מעכבת בו,\u0004 אבל \u0003כל שאינו ראוי לבילה\u0004 — ה\u0003בילה מעכבת בו.\u0004","ומתוך שהובאו שיעורים שנקבעו בדיני טומאה, מביאים עוד בענין זה. \u0003אמר ר' ביבי, אמר ר' יהושע בן לוי: מעשה בפרדה אחת של בית רבי\u0004 (ר' יהודה הנשיא) \u0003שמתה,\u0004 ויצא ממנה דם, \u0003ושיערו חכמים את דמה\u0004 זה שיש בו שיעור \u0003ב\u0004כדי \u0003רביעית,\u0004 המטמא.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' יצחק בר ביסנא\u0004 ממה ששנו חכמים, ש\u0003העיד ר' יהושע ור' יהושע בן בתירא\u0004 במסורת מפי חכמים, \u0003על דם נבילות שהוא טהור. ו\u0004כיוצא בדבר, \u0003אמר ר' יהושע בן בתירא\u0004 כי אירע \u0003מעשה והיו נוחרין\u0004 (ממיתים בדקירת הגרון בסכין, שלא בדרך שחיטה) \u0003ערודיאות\u0004 (חמורי בר) כדי להאכיל את \u0003בשרם\u0004 \u0003לאריות\u0004 המצויים \u0003באיסטריא\u0004 (איצטדיון) \u0003של מלך, והיו עולי רגלים\u0004 העושים את \u0003דרכם לירושלים, ונזהרים מלהיטמא,\u0004 \u0003שוקעין עד רכובותיהן\u0004 (קרסוליהם) \u0003בדם\u0004 זה של הערודים, \u0003ולא אמרו להם\u0004 חכמים \u0003דבר\u0004 על כך, שלא מחו בהם שהם טמאים. משמע שאין דם הנבילות מטמא!","\u0003אישתיק\u0004 \u0005[שתק]\u0006 ר' יהושע בן לוי, ולא השיב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זריקא\u0004 לר' יהושע בן לוי: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא קא מהדר מר\u0004 \u0005[\u0006לא \u0005משיב אדוני]\u0006 על שאלה זו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע בן לוי לר' זריקא: \u0003היכי אהדר ליה\u0004 \u0005[איך אשיב לו,\u0006 לר' יצחק בר ביסנא\u0005],\u0006 שהרי כבר \u0003אמר ר' חנין\u0004 בדרשת הכתוב בתוכחה \"והיו חייך תלואים לך מנגד ופחדת לילה ויומם ולא תאמין בחייך\" (דברים כח, סו), שכך הם משמעם של דברים: \u0003\"והיו חייך תלאים לך מנגד\"\u0004 — \u0003זה הלוקח\u0004 (הקונה) \u0003תבואה משנה לשנה,\u0004 שאינו בטוח שתימצא לו תבואה אף בשנה שלאחריה.","\u0003\"ופחדת לילה ויומם\"\u0004 — \u0003זה הלוקח תבואה מערב שבת לערב שבת. \"ואל תאמן בחייך\"\u0004 — \u0003זה הסומך על הפלטר\u0004 (האופה), שיתן לו את לחמו, שאין לו תבואה משל עצמו כלל."],["ואמר ר' יהושע בן לוי: \u0003ו\u0004אף \u0003ההוא גברא\u0004 \u0005[אותו אדם]\u0006 כלומר, אני, \u0003על פלטר סמיך\u0004 \u0005[סומך],\u0006 ואין דעתי מיושבת לענות לו כראוי.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]?\u0006 כלומר, כיצד מתרצים קושי זה? \u0003אמר רב יוסף: ר' יהודה מוריינא דבי נשיאה הוה\u0004 \u0005[מורה ההוראה של בית הנשיא היה]\u0006 \u0003ואורי ליה כשמעתיה\u0004 \u0005[והורה לו\u0006 לבית הנשיא \u0005כשמועתו,\u0006 כמסורת הלכה שבידו\u0005]\u0006 שדם הנבילה מטמא.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: ששה דברים\u0004 הריהם \u0003מקולי\u0004 (הקלות) של \u0003בית שמאי ומחומרי\u0004 (חומרות) של \u0003בית הלל,\u0004 ואחד מהם הוא דינו של \u0003דם נבילות\u0004 — ש\u0003בית שמאי\u0004 מקילים ו\u0003מטהרין\u0004 דם נבילות (שאין דם נבילות מטמא), \u0003ו\u0004אילו \u0003בית הלל\u0004 מחמירים בדין זה ו\u0003מטמאין\u0004 דם נבילות. ולכך הורה ר' יהודה לבית הנשיא להחמיר בדם הפרידה שמתה. שכן \u0003אמר ר' יוסי בר' יהודה: אף כשטמאו בית הלל\u0004 בדם הנבילה — \u0003לא טמאו אלא ברביעית\u0004 דם דווקא. וטעמו של שיעור זה: \u0003הואיל ו\u0004דם שיש בו שיעור רביעית \u0003יכול לקרוש ולעמוד\u0004 כדבר מוצק \u0003על\u0004 כשיעור \u0003כזית,\u0004 כשיעור בשר הנבילה המטמא.","\u0003אין מתנדבין\u0004 לנסכים יין בשיעור \u0003לוג\u0004 אחד, או \u0003שנים\u0004 או \u0003חמשה\u0004 לוגים. שאין שיעורי יין אלה נוהגים במנחות הנסכים. \u0003אבל מתנדבין שלשה\u0004 לוגים של יין (כשיעור נסכי כבש \"רביעית ההין\". במדבר טו, ד), \u0003ו\u0004כן \u0003ארבעה\u0004 כשיעור נסכי איל, \"שלשית ההין\". שם ו), \u0003ו\u0004כן \u0003ששה\u0004 כשיעור נסכים לפר, \"חצי ההין\". שם י). \u0003ומששה\u0004 לוגים \u0003ולמעלה\u0004 נודבים כל שיעור. שהרי מכאן ואילך כל מספר לוגים יכול להתחלק באופן שחלק ממנו ראוי לנסכים של פר, וחלק אחר — לנסכים של איל, וחלק אחר — לנסכים של כבש.","שנינו במשנתנו שאין יכול אדם לנדוב לנסכים חמישה לוגים יין, לפי שאין שיעור זה נוהג בנסכים. ובענין זה מביאים, \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]:\u0006 האם \u0003יש קבע לנסכים,\u0004 שכאשר נדר שיעור מסויים של לוגי יין, נקבעו כולם כאחד, ואינו יכול לחלקם ולהקריבם לחוד, \u0003או אין קבע לנסכים,\u0004 ויכול לחלקם ולהקריבם לחוד?","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003כגון דאייתי\u0004 \u0005[שהביא,\u0006 שנדר להביא\u0005]\u0006 \u0003חמשה\u0004 לוגים של יין. ומעתה יש לדון: \u0003אי אמרת\u0004 \u0005[אם אתה\u0006 \u0003אומר]\u0004 ש\u0003אין קבע לנסכים\u0004 — \u0003משיך\u0004 \u0005[מושך]\u0006 מתוך חמשת הלוגים שנדר \u0003ומקריב ארבעה מינייהו\u0004 \u0005[מהם],\u0006 \u0003דחזי\u0004 \u0005[שראויים]\u0006 \u0003ל\u0004נסכי \u0003איל, ואידך\u0004 \u0005[ו\u0006הלוג \u0005האחר,\u0006 החמישי\u0005],\u0006 שאינו שיעור הראוי לנסכים — \u0003הוי\u0004 \u0005[הינו]\u0006 \u0003נדבה,\u0004 שיפדוהו, והדמים שהתקבלו עבורו יקנו בהם קרבנות עולה הקרבים על המזבח בשעה שאין קרבים בו קרבנות אחרים (\"קיץ המזבח\"). \u0003ו\u0004אולם \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003יש קבע לנסכים,\u0004 ואין להפריד בין הלוגים \u0003להקריבם לחוד\u0004 — \u0003עד\u0004 שינדוב עוד לוגי יין, באופן \u0003דממלי להו\u0004 \u0005[שימלא אותם,\u0006 שישלים את מספר לוגי היין שנדב\u0005]\u0006 לכלל המספר הראוי לנסכים, \u0003לא קרבי\u0004 \u0005[לא קרבים].\u0006","אם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין? \u0003אמר אביי:\u0004 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו \u0005ממה ששנינו במשנה כי\u0006 \u0003ששה\u0004 שופרות (קופות שצורתן כצורת שופר, פיו צר מלמעלה — לקבלת המעות בו, והולך ומתרחב כלפי למטה — להכיל בו את המעות) היו במקדש \u0003ל\u0004צורך מעות \u0003נדבה. ואמרינן\u0004 \u0005[ואומרים אנו]:\u0006 \u0003כנגד מי\u0004 היו עושים שישה שופרות אלה? האחד, \u0003כנגד מותר חטאת,\u0004 אם הפריש מעות לקרבן חטאת שהתחייב בו, וקנה בהן בהמה לקרבנו, ונשאר בידו מן המעות — הריהו מניח מעות אלה בשופר עליו היה כתוב \"מותר חטאת\". \u0003ו\u0004השני ל\u0003מותר אשמות,\u0004 שהמעות שהשתיירו בידו לאחר שקנה בהן אשם, היה מניח בשופר עליו היה כתוב \"מותר אשמות\". \u0003ו\u0004כן בשאר השופרות שהיו מיועדים לצורך \u0003מותר אשם נזיר, ומותר אשם מצורע, ומותר קינין, ומותר מנחת חוטא.\u0004","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לומר שהנודר חמישה לוגים יין, יפריש מהם ארבעה לנסכי איל והלוג החמישי ילך לנדבה, \u0005אם כן\u0006 \u0003ליתקין\u0004 \u0005[שיתקינו]\u0006 במקדש \u0003שופר אחרינא\u0004 \u0005[אחר],\u0006 נוסף, \u0003כנגד מותר נסכים!\u0004","ודוחים: אפשר לומר כי לא תיקנו במקדש שופר מיוחד למותר נסכים, שכן דווקא ב\u0003הנך\u0004 \u0005[אלה]\u0006 הששה תיקנו שופרות במקדש, משום \u0003ש\u0004\u0003לנדבת צבור\u0004 (להקרבת העולה ל\"קיץ המזבח\", שהוא מקרבנות הציבור) \u0003אזלי\u0004 \u0005[הולכות]\u0006 המעות הללו, ונדרש זמן עד שתצטברנה די מעות כדי לקנות בהן בהמה, ומשום כך התקינו להן שופרות, שתישמרנה בהם בינתיים. מה שאין כן, \u0003הני\u0004 \u0005[אלה]\u0006 מותרות נסכים, הריהם \u0003שכיחי\u0004 \u0005[מצויים],\u0006 ואין צורך לשומרם בינתים, שהרי \u0003אפשר דמצטרפי\u0004 \u0005[שיצטרפו]\u0006 מותרות נסכים \u0003דמר ודמר בהדי הדדי\u0004 \u0005[של אדם זה ושל אדם זה ביחד],\u0006 כדי שיעור נסכים ראוי, \u0003וקרבי\u0004 \u0005[ויקרבו\u0006\u0003]\u0004 מיד, ולכך לא תיקנו להן שופר מיוחד.","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו בבריייתא על הנאמר בפרשת הנסכים \"כל ה\u0003אזרח\u0004 יעשה ככה את אלה להקריב אשה ריח ניחוח לה' \" (במדבר טו, יג) — כתוב יתר זה \u0003מלמד שמתנדבין נסכים\u0004 לעצמם, ולא רק כנסכים הבאים עם הקרבן. \u0003וכמה\u0004 הוא שיעור הנסכים אותו מתנדבים? — \u0003שלשת לוגין,\u0004 שהוא כשיעור הנמוך ביותר של נסכי הקרבנות (של נסכי הכבשים).","\u0003ומנין\u0004 לנו \u0003שאם רצה להוסיף\u0004 על שיעור זה ש\u0003יוסיף? תלמוד לומר\u0004 (מלמדנו הנאמר) הכתוב בדין הנסכים \"ונסכיהם חצי ההין יהיה לפר ושלישית ההין לאיל ורביעת ההין לכבש יין...\" (שם כח, יד), ובאה לשון הריבוי \u0003\"יהיה\u0004 לפר\" להורות — שיש נסכים נוספים הבאים לעצמם. \u0003יכול\u0004 יהא הדין \u0003ש\u0004\u0003יפחות\u0004 בנדבת הנסכים אף משלושה לוגים יין? \u0003תלמוד לומר:\u0004 \"כל האזרח יעשה \u0003ככה\",\u0004 להדגיש שאין לפחות משלושה לוגים יין.","ומעתה יש לברר את הנאמר בברייתא זו: \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003יוסיף,\u0004 שלמדתנו הברייתא שמותר להוסיף על שיעור שלושה לוגים יין? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה ללמד שמותר לנדב לנסכים גם \u0003ארבעה וששה\u0004 לוגים יין — לכך אין צורך בלימוד מיוחד, שהרי \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 במה התייחד\u0005]\u0006 שיעור \u0003שלשה\u0004 לוגים שמותר לנודבו? — משום \u0003דחזו\u0004 \u0005[שראויים]\u0006 \u0003ל\u0004נסכי \u0003כבש,\u0004 אם כן \u0003ארבעה וששה\u0004 לוגים \u0003נמי חזו\u0004 \u0005[גם כן ראויים\u0006 הם\u0005]\u0006 ששיעור זה ראוי \u0003ל\u0004נסכי \u0003איל\u0004 (ארבעה לוגים) \u0003ו\u0004לנסכי \u0003פר\u0004 (ששה לוגים)! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 כוונת \"יוסיף\" ל\u0003חמשה\u0004 לוגים יין, שאף אלה נידבים, הגם שאין כשיעור זה בנסכים הקרבים עם הקרבנות. \u0003ו\u0004מעתה \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003אין קבע לנסכים.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","\u0003אמר רב אשי\u0004 בשאלה: \u0003והא אנן\u0004 \u0005[והרי אנחנו]\u0006 \u0003לא תנן הכי\u0004 \u0005[לא שנינו\u0006 \u0003כך\u0004 במשנתנו\u0003]\u0004 שמתנדבים חמישה לוגים! שהרי שנינו במשנתנו כי \u0003אין מתנדבין לוג שנים וחמשה,\u0004 ומתוך ש\u0003קתני\u0004 \u0005[שנה]\u0006 התנא במשנה דינם של \u0003חמשה\u0004 לוגים \u0003דומיא\u0004 \u0005[בדומה]\u0006 לדינם של \u0003שנים\u0004 לוגים, ודאי שווים הם בדינם. ומעתה נאמר: \u0003מה שנים\u0004 לוגים, הכוונה היא ש\u0003לא חזו\u0004 \u0005[לא ראויים]\u0006 \u0003כלל,\u0004 שהרי הם פחותים משיעור נסכים. \u0003אף חמשה\u0004 לוגים \u0003נמי\u0004 \u0005[גם כן]\u0006 הכוונה ש\u0003לא חזו\u0004 \u0005[לא ראויים]\u0006 \u0003כלל,\u0004 שאין הם כשיעור נסכים, ויש קבע לנסכים ולכך אי אפשר להפריד ארבעה מהם ולהקריבם!","ודוחים: \u0003מידי איריא\u0004 \u0005[וכי שייכים\u0006 הדברים\u0005]?\u0006 \u0003הא כדאיתא, והא כדאיתא\u0004 \u0005[זה כמו שהוא, וזה כמו שהוא],\u0006 ששני לוגים אכן אינם ראויים כלל, ואילו חמישה לוגים — ארבעה מהם ראוים להקרבה, והחמישי ילך לנדבה.","\u0003אמר אביי: אם תמצא לומר\u0004 ולהכריע כי \u0003אין קבע לנסכים\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין קבע לנסכים,\u0004 ואין מקום לדיון נוסף בענין. ואולם \u0003אם תמצא לומר\u0004 כי \u0003יש קבע לנסכים,\u0004 יש \u0003לומר כי כל נדר\u0004 \u0003עד עשרה\u0004 לוגים יין \u0003פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי\u0004 מהו דינו. שהרי הנודר לוג אחד, וכן שנים, וכן חמישה לוגים — אינם קרבים, עד שישלים מספר הלוגים כשיעור הקרב; שלושה לוגים וכן ארבעה וששה — הריהם קרבים, שהרי שיעורם הוא כשיעור נסכי הכבש והאיל והפר. ואף מכאן והלאה, שנדרשים אנו לצירופים שונים לכלל שיעור נסכים, הרי אלה צירופים ברורים (שבעה לוגים — מהם שלושה ראויים לכבש, וארבעה לאיל; שמונה — ראויים לשני אילים; תשעה — מהם ששה ראויים לפר, ושלושה לכבש; עשרה — מהם ששה ראויים לפר, וארבעה לאיל). ואולם ב\u0003אחד עשר\u0004 לוגים"],["\u0003מיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי\u0004 השאלה \u0003מאי\u0004 \u0005[מה]\u0006 דינם? וצדדי הבעיה: האם \u0003גברא\u0004 \u0005[האדם]\u0006 הנודר אחד עשר לוגים יין — \u0003ל\u0004כשיעורם של נסכי \u0003שני פרים\u0004 (שהם שנים עשר לוג) \u0003קא מכוין\u0004 \u0005[הוא מתכוין],\u0006 \u0003ו\u0004לכך \u0003עד\u0004 (כל עוד שלא) \u0003דממלי להו\u0004 \u0005[שישלים אותם]\u0006 אחד עשר לוגים, שיוסיף עליהם לוג נוסף — \u0003לא קרבי\u0004 \u0005[לא קרבים],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003ל\u0004שיעור נסכיהם של \u0003שני אילים\u0004 (שמונה לוגים) \u0003וכבש אחד\u0004 (שלושה לוגים) \u0003קמכווין\u0004 \u0005[הוא מתכוין],\u0006 אחד עשר לוגים, ויכול הוא להקריבם כמות שהם. ויסוד השאלה הוא: לשיעור המבוסס על \u0003תרי מחד מינא\u0004 \u0005[שני\u0006 נסכים \u0005ממין אחד,\u0006 כנסכי שני אילים\u0005]\u0006 \u0003וחד מחד מינא\u0004 \u0005[ו\u0006נסך \u0005אחד ממין אחד\u0006 אחר, כנסכי כבש\u0005]\u0006 \u0003אמרינן\u0004 \u0005[א\u0006 \u0003ומרים אנו]\u0004 שהתכוון. \u0003או לא\u0004 התכוון אלא לבאים ממין אחד, וכגון לשני פרים. \u0003מאי\u0004 \u0005[מה]\u0006 הפתרון לבעיה זו? ומסכמים כי בעיה זו לא נפתרה, \u0005ו\u0006\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003מתנדבין יין\u0004 לנסכים לעצמם, ובלא נדבת סולת ושמן, ומנסכים יין זה לעצמו על המזבח, ויורד לשיתין. \u0003ואין מתנדבין שמן\u0004 לעצמו. אלו \u0003דברי ר' עקיבא.\u0004 ו\u0003ר' טרפון\u0004 חולק ו\u0003אומר\u0004 כי \u0003מתנדבין\u0004 גם \u0003שמן\u0004 לעצמו. ו\u0003אמר ר' טרפון\u0004 בהסבר שיטתו: \u0003מה מצינו\u0004 (מצאנו) \u0003ביין\u0004 למנחה \u0003שהוא בא\u0004 ב\u0003חובה\u0004 (במנחת נסכים) \u0003ו\u0004הוא \u0003בא\u0004 גם כמנחת \u0003נדבה\u0004 לעצמה, ואינו נלווה לקרבנות, \u0003אף שמן,\u0004 שמצאנו בו \u0003שהוא בא\u0004 ב\u0003חובה\u0004 (במנחת נסכים), הריהו \u0003בא\u0004 גם כמנחת \u0003נדבה\u0004 לעצמה. \u0003אמר לו ר' עקיבא\u0004 לר' טרפון: \u0003לא,\u0004 אין יסוד להשוואה שהרי \u0003אם אמרת ביין\u0004 שהוא קרב כמנחת נדבה, לעצמו — טעם יש בדבר: \u0003שכן\u0004 אף כאשר היין \u0003קרב עם חובתו\u0004 (במנחת נסכים), הריהו \u0003קרב\u0004 \u0003בפני עצמו,\u0004 שאינו מעורב במנחה, אלא מתנסך על גבי המזבח לעצמו. האם \u0003תאמר\u0004 כן \u0003בשמן, שאינו קרב עם חובתו בפני עצמו\u0004 אלא מעורב בה?","","ועוד בדין נדבת סולת למנחה: \u0003אין שנים\u0004 מצטרפים זה לזה כשותפים במנחה שיהיו שניהם \u0003מתנדבין עשרון אחד,\u0004 \u0003אבל\u0004 מצטרפים שנים לשותפות והם \u0003מתנדבין עולה ו\u0004כן \u0003שלמים, ו\u0004כן בקרבן \u0003עוף\u0004 — מצטרפים שנים לשותפות \u0003אפילו\u0004 ב\u0003פרידה\u0004 (יחידה, תור או גוזל) \u0003אחת.\u0004","שנינו במשנתנו מחלוקתם של ר' עקיבא ור' טרפון בדין נדבת שמן לעצמו, ובענין זה \u0003אמר רבא: מדברי שניהם\u0004 שלא נחלקו אלא לענין שמן, ואולם מוסכם על שניהם כי מתנדב אדם שמן וסולת למנחת נסכים, \u0003נלמוד\u0004 כי \u0003מתנדב אדם מנחת נסכים בכל יום.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, ומה בא רבא להשמיענו! ומשיבים: נצרך רבא להשמיענו כן, שהרי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מנחת נדבה גלי\u0004 \u0005[גילתה]\u0006 \u0003בה רחמנא\u0004 \u0005[התורה]\u0006 כי יש בה חמישה סוגים (מנחת סולת, מנחת מחבת, מנחת מרחשת, מאפה תנור, רקיקים), והיה איפוא מקום לומר כי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003חמשה\u0004 ה\u0003מנחות\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מקריבים, ואולם \u0003טפי\u0004 \u0005[יותר]\u0006 מאלה שיביא מנחת נסכים לעצמה — \u0003לא.\u0004 לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 רבא \u0005משמיע לנו]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאין אלא חמש מנחות נדבה — אמורים במביא מנחה \u0003בסתמא\u0004 \u0005[בסתם],\u0006 שלא פירש שהריהי למנחת נסכים. \u0003אבל היכא דפריש\u0004 \u0005[היכן שפירש]\u0006 ואמר כי השמן והסולת שהוא נודר הריהם נסכים — הרי \u0003פריש\u0004 \u0005[פירש],\u0006 וחל נדרו.","שנינו עוד במשנתנו כי \u0003אין שנים\u0004 \u0003מתנדבין\u0004 עשרון אחד. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר, מה מקורה של הלכה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שטעם הדבר \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 במנחה \"ונפש כי \u0003תקריב\u0004 מנחה\" (ויקרא ב, א) שהוא לשון יחיד — בקרבן \u0003עולה נמי הא כתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 בלשון יחיד, \"אדם כי \u0003יקריב\u0004 מכם קרבן...\" (שם א, ב), והרי שותפים מתנדבים עולה, כמבואר במשנתנו!","\u0003אלא עולה מאי טעמא\u0004 \u0005[מה טעם]\u0006 באה אף \u0005בשותפות, למרות שנאמר בה לשון יחיד? משום\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בה, בלשון רבים \"אלה תעשו... \u0003לעלתיכם\u0004 ולמנחותיכם ולנסכיכם ולשלמיכם\" (במדבר כט, לט). ואולם אם משום כך, ב\u0003מנחה נמי הא כתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 לשון רבים \"ו \u0003למנחתיכם\"! אלא\u0004 טעם הדבר שאין מביאים מנחה בשותפות — \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה\u0004 במנחה הלשון \u0003\"נפש\"\u0004 (\"ונפש כי תקריב מנחה\"), לומר שאינה באה אלא על ידי היחיד, ולא בשנים.","ומוסיפים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003רבי אומר\u0004 על הכתוב \u0003\"...\u0004 \u0003אשר יקריב קרבנו לכל נדריהם ולכל נדבותם אשר יקריבו לה'\u0004 לעולה\" (שם כב, יח): מלשון רבים שאחז בה הכתוב בקרבנות, למדנו כי \u0003הכל,\u0004 כל \u0003הקרבנות,\u0004 \u0003באין\u0004 אף \u0003בשותפות,\u0004 ו\u0003לא סילק הכתוב\u0004 מכלל הקרבנות הבאים בשותפות \u0003אלא\u0004 את \u0003ה\u0004\u0003מנחה\u0004 בלבד, שאין המנחה באה בשותפות, משום \u0003שנאמר\u0004 בה \u0003\"נפש\".\u0004","ועוד בדרשת המלה \"נפש\" האמורה דווקא במנחה, \u0003אמר ר' יצחק: מפני מה נשתנית מנחה\u0004 משאר הקרבנות, \u0003שנאמר בה \"נפש\"? אמר הקדוש ברוך הוא: מי דרכו להביא מנחה\u0004 כנדבה? \u0003עני. מעלה אני עליו כאילו הקריב נפשו לפני.\u0004 ועוד \u0003אמר ר' יצחק\u0004 בטעם ייחודה של המנחה משאר קרבנות: מפני \u0003מה נשתנית מנחה, שנאמר בה חמשה מיני טיגון הללו\u0004 (שיש בה אופני שימוש שונים בשמן, בחמשת מיניה של המנחה)? \u0003משל למלך בשר ודם שעשה לו אוהבו סעודה, ויודע בו\u0004 המלך באותו אוהב \u0003שהוא עני. אמר לו\u0004 המלך: \u0003עשה לי מן חמשה מיני טיגון, כדי\u0004 \u0003שאהנה ממך\u0004 ותתקבל לפני, אף על פי שאתה נותן רק סעודה קטנה.","","","הנודר \u0003\"הרי עלי\u0004 להביא \u0003עשרון\u0004 סולת למנחה\" — \u0003יביא\u0004 למנחה עשרון סולת \u0003אחד.\u0004 אמר \"הרי עלי להביא מנחה של \u0003עשרונות\"\u0004 — \u0003יביא\u0004 מנחה של \u0003שנים\u0004 עשרונים סולת, שמיעוט לשון רבים הוא שניים. אמר \"בשעה \u0003שנדרתי\u0004 \u0003פירשתי\u0004 (אמרתי במדוייק) מספר עשרונים שאני נודר למנחה, ואולם עתה נשכח ממני, \u0003ואיני יודע מה פירשתי\"\u0004 — \u0003יביא\u0004 מנחה שיש בה \u0003ששים עשרון,\u0004 שהרי אין מנחה באה ביותר מששים עשרונים. ואף אם נדר מנחה בת עשרון אחד — יהא עשרון אחד לחובתו, והשאר לנדבה. אמר \u0003\"הרי עלי\u0004 להביא \u0003מנחה\",\u0004 ולא פירש איזו מנחה — \u0003יביא איזו\u0004 מנחה \u0003שירצה\u0004 מחמש המנחות שבתורה (מנחת סולת, מנחת מחבת, מנחת מרחשת, מנחת מאפה חלות, ומנחת מאפה רקיקים). \u0003ר' יהודה אומר: יביא מנחת הסולת, שהיא\u0004 המנחה \u0003ה\u0004\u0003מיוחדת שב\u0004כל ה\u0003מנחות.\u0004","","אמר \"הרי עלי להביא \u0003מנחה\" או\u0004 שאמר \"הרי עלי להביא \u0003מין המנחה\"\u0004 — \u0003יביא\u0004 \u0003אחת.\u0004 אמר \"הרי עלי להביא \u0003מנחות\", או\u0004 שאמר: \"הרי עלי להביא \u0003מין מנחות\"\u0004 — \u0003יביא שתים\u0004 מנחות. אמר \"בשעה \u0003שנדרתי\u0004 \u0003פירשתי\u0004 אלו ממיני המנחות נדרתי להביא, ונשכח ממני, \u0003ואיני יודע איזה מהן פירשתי\"\u0004 — \u0003יביא\u0004 את כל \u0003חמשתן\u0004 (חמשת מיני המנחות). אמר \"בשעה שנדרתי \u0003פירשתי\u0004 שעלי להביא \u0003מנחה של\u0004 כמה \u0003עשרונים\u0004 בכלי אחד, ואולם עתה נשכח ממני \u0003ואיני יודע כמה\u0004 עשרונים \u0003פירשתי\u0004 בנדרי\" — \u0003יביא\u0004 מנחה שיש בה \u0003ששים עשרון,\u0004 ויצא בה ידי נדרו. \u0003רבי אומר:\u0004 לא יצא ידי נדרו עד ש\u0003יביא\u0004 ששים \u0003מנחות של\u0004 מספר \u0003עשרונות\u0004 שונים בכל מנחה ומנחה, \u0003מ\u0004מנחה שיש בה עשרון \u0003אחד,\u0004 ומנחה שיש בה שני עשרונים, וכן הלאה, \u0003ועד\u0004 מנחה שיש בה \u0003ששים\u0004 עשרונים (ונמצא סך כל העשרונים המובאים על ידו עולה לאלף שמונה מאות ושלושים עשרונים). ותהא מנחה אחת מאלה לשם נדרו, ושאר המנחות באות לשם נדבה. שנינו במשנתנו שהאומר בנדרו \"הרי עלי \u0003עשרון\", מביא מנחה בת עשרון אחד. ושואלים:\u0004 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, ואין צורך לאמרו. ומשיבים: הלכה זו נצרכת רק משום המשכה באומר \"הרי עלי \u0003עשרונות\"\u0004 — \u0003יביא שתים איצטריכא ליה\u0004 \u0005[נצרכה לו]\u0006 לשנותה. ושואלים: \u0003הא נמי פשיטא\u0004 \u0005[\u0006הלכה \u0005זו גם כן\u0006 הריהי \u0005פשוטה],\u0006 ואין צורך לשנותה. ומשיבים: הלכה זו משום חידוש שבה, ש\u0003מיעוט עשרונות שתים איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לשנותה. עוד שנינו במשנתנו שמי שאמר כי בשעה שנדרתי \u0003פירשתי\u0004 כמה עשרונים אביא בנדרי, ועתה שכחתי \u0003ואיני יודע מה\u0004 מספר העשרונים ש\u0003פירשתי\"\u0004 — \u0003יביא\u0004 מנחה אחת \u0003של\u0004 \u0003ששים עשרון.\u0004 ומבררים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 שסבור כן?","","","","\u0003אמר חזקיה:\u0004 ש\u0003לא כ\u0004דעת \u0003רבי\u0004 הנשנית בסוף משנתנו. ונימוקו: \u0003דאי\u0004 \u0005[שאם]\u0006 משנתנו זו היא כדעת \u0003רבי, האמר\u0004 \u0005[הרי אמר]\u0006 רבי שהאומר \"פרשתי שאביא מספר מסויים של עשרונים, ואיני יודע עתה כמה עשרונים אמרתי\", \u0003יביא\u0004 ששים \u0003מנחות של עשרונות\u0004 שונים, החל \u0003מ\u0004מנחה שיש בה עשרון \u0003אחד ועד\u0004 למנחה שיש בה \u0003ששים\u0004 עשרונים. \u0003ו\u0004אילו \u0003ר' יוחנן אמר:\u0004 \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהלכה זו היא כשיטת \u0003רבי,\u0004 ואין בכך קושי, שכן לא נחלק רבי על חכמים אלא במי שפירש בשעת נדרו שיביא מספר מסויים של עשרונות וקבעם בכלי (שאמר שיביא אותם בכלי אחד). שבאופן זה סבור רבי שהריהו מביא ששים מנחות בששים כלים. ואילו \u0003ב\u0004הלכה זו שבמשנתנו מדובר כש\u0003אומר \"פירשתי עשרונות, אבל לא קבעתים בכלי\u0004 אחד\". שבמקרה זה דינו \u0003דמייתי שיתין\u0004 \u0005[שמביא ששים]\u0006 \u0003עשרונות\u0004 בלבד, \u0003בשיתין מאני\u0004 \u0005[בששים כלים],\u0006 שבכל אחד מהם עשרון אחד\u0005.\u0006","","עוד שנינו במשנתנו שהאומר \u0003\"הרי עלי מנחה\"\u0004 לדעת תנא קמא דינו ש\u0003יביא איזהו\u0004 מנחה ממיני המנחות \u0003שירצה,\u0004 ולדעת ר' יהודה יביא מנחת סולת דווקא. ובהסבר שיטת ר' יהודה \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: הריהו מביא מנחת סולת, \u0003הואיל ופתח בו הכתוב תחלה\u0004 בפרשת המנחות (ויקרא פרק ב).","ומקשים: \u0003אלא מעתה,\u0004 אף \u0003האומר \"הרי עלי עולה\"\u0004 ולא פירש איזו עולה היא — \u0003יביא\u0004 לעולתו דווקא מ\u0003בן בקר,\u0004 לעולת בהמה, \u0003הואיל ופתח בו הכתוב\u0004 בפרשת קרבנות העולה"],["\u0003תחלה\u0004 (\"אם עולה קרבנו מן הבקר זכר תמים יקריבנו...\". ויקרא א, ג).","וכיוצא בדבר זה שנדר \"הרי עלי להביא עולה \u0003מן הצאן\"\u0004 — ש\u0003יביא\u0004 דווקא \u0003כבש, הואיל ופתח בו הכתוב תחלה\u0004 בעולות הצאן (\"ואם מן הצאן קרבנו מן הכשבים או מן העזים לעולה זכר תמים יקריבנו\". שם י).","וזה שנדר \"הרי עלי להביא עולה \u0003מן העוף\"\u0004 — ש\u0003יביא\u0004 דווקא מן ה\u0003תורים,\u0004 \u0003הואיל ופתח בו הכתוב תחלה\u0004 בעולות העוף (\"ואם מן העוף עולה קרבנו לה' והקריב מן התורים או מן בני היונה את קרבנו\". שם יד).","ו\u0003אלמה תנן\u0004 \u0005[מדוע שנינו\u0006 במשנה קז,א\u0005]\u0006 שהנודר \u0003\"הרי עלי\u0004 להביא \u0003עולה\"\u0004 ולא פירש איזו עולה — \u0003יביא כבש\u0004 זכר לעולתו, שהוא הפחות שבעולות בהמה. \u0003ר' אלעזר בן עזריה אומר:\u0004 מביא לנדרו \u0003תור או בן יונה. ולא פליג\u0004 \u0005[ולא חלק]\u0006 \u0003ר' יהודה\u0004 על כך!","\u0003אלא\u0004 כך צריך לפרש, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 דברי ר' יהודה במשנתנו שמנחת הסולת היא \u0003מיוחדת שבמנחות?\u0004 — \u0003דלית ליה\u0004 \u0005[שאין לה]\u0006 \u0003שם לווי,\u0004 שהיא נקראת \"מנחה\" בלבד, בעוד שלשאר המנחות יש שם לוואי (כגון \"מנחת מחבת\", \"מנחת מרחשת\").","ומקשים: \u0003והא תנא\u0004 \u0005[והרי שנה]\u0006 בברייתא בהסבר דברי ר' יהודה \u0003הואיל ופתח בו הכתוב\u0004 \u0003תחלה קאמר\u0004 \u0005[הוא אומר]!\u0006 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונתו\u0005]:\u0006 \u0003איזהו מנחה\u0004 המכונה על ידי ר' יהודה \u0003\"מיוחדת שבמנחות\", דלית ליה\u0004 \u0005[שאין לה]\u0006 \u0003שם לווי?\u0004 — \u0003זו\u0004 המנחה \u0003שפתח בו הכתוב תחלה,\u0004 היא מנחת הסולת. ולפי זה הטעם שמביאים דווקא ממנחת הסולת אינו משום שפתח בה הכתוב, אלא משום שאין בה שם לוואי.","ומקשים: לא היה צריך ר' יהודה לומר שפתח בה הכתוב במנחה זו תחילה, שהרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא \u0003שהרי\u0004 \u0003מנחת הסולת קאמר\u0004 \u0005[אומר הוא]\u0006 ר' יהודה שעליו להביא. ומשיבים: לא אמר זאת ר' יהודה כטעם לדינו, אלא רק כ\u0003סימנא בעלמא\u0004 \u0005[סימן בלבד],\u0006 לזכרון, שלא נשכח באיזו מנחה המדובר, לכך נתן בה סימן שהיא המנחה שפתח בה הכתוב תחילה\u0005.\u0006","שנינו במשנתנו שאם אמר בנדרו \"הרי עלי להביא \u0003מנחה\"\u0004 או שאמר \"הרי עלי להביא \u0003מין המנחה\",\u0004 כיון שאמר בלשון יחיד — הרי זה מביא מנחה אחת. ואם אמר \"הרי עלי להביא מנחות\" או שאמר \"הרי עלי להביא מן המנחות\", כיון שאמר בלשון רבים — יביא שתי מנחות. ובעקבות הדברים הללו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם אמר \u0003\"הרי עלי להביא\u0004 \u0003מיני מנחה\",\u0004 שיש בנדרו הן לשון רבים \u0005(\"מיני\"), והן לשון יחיד (\"מנחה\"),\u0006 \u0003מהו\u0004 הדין?","וצדדי הספק: האם \u0003כיון\u0004 ש\u0003אמר \"מיני\"\u0004 — \u0003תרתי קאמר\u0004 \u0005[שתים\u0006 מנחות \u0005הוא אומר],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 טעם\u0005]\u0006 אמר \u0003\"מנחה\"\u0004 בלשון יחיד? שכן \u0003כולה\u0004 \u0005[כולן],\u0006 כל ה\u0003מנחות נמי\u0004 \u0005[גם כן]\u0006 \u0003\"מנחה\" מיקריין\u0004 \u0005[נקראות],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפרשת המנחות \u0003\"וזאת תורת המנחה\"\u0004 (ויקרא ו, ז), משמע ש\"מנחה\" משמעה אף כלל המנחות.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003אמר \"מנחה\"\u0004 — \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003מנחה\u0004 \u0005קאמר\u0006 \u0005[הוא אומר],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 טעם\u0005]\u0006 אמר \u0003\"מיני מנחה\"\u0004 בלשון רבים? \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונתו\u0005]:\u0006 \u0003\"ממיני\u0004 ה\u0003מנחה חדא\u0004 \u0005[אחת]\u0006 \u0003מנחה עלי\u0004 להביא\"?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה שהכוונה במקרה זה היא לשתי מנחות, שכן שנינו במשנתנו שהאומר \"הרי עלי להביא \u0003מנחה\"\u0004 או \"הרי עלי להביא \u0003מין מנחה\"\u0004 — \u0003יביא אחת.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם אמר \"הרי עלי להביא \u0003מיני מנחה\"\u0004 — יביא \u0003שתים.\u0004","ודוחים: אין זו ראיה שכן \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005הסוף\u0006 של משנתנו\u0005]:\u0006 מי שאמר \"הרי עלי להביא \u0003מנחות\"\u0004 או שאמר \"הרי עלי להביא \u0003מין מנחות\"\u0004 — \u0003יביא שתים,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם אמר \"הרי עלי \u0003מיני מנחה\"\u0004 — יביא רק מנחה \u0003חדא\u0004 \u0005[אחת].\u0006 \u0003אלא\u0004 ודאי \u0005כי\u0006 \u0003מהא ליכא למשמע מינה\u0004 \u0005[מ\u0006משנתנו \u0005זו אין לשמוע ממנה]\u0006 בדרך הדיוק פתרון לבעייתו של רב פפא.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו בברייתא: \u0005מי שאמר\u0006 \u0003\"מין מנחות עלי\"\u0004 — \u0003יביא שתי מנחות ממין אחד\u0004 מחמשת מיני המנחה (מנחת סולת, מנחת מחבת, מנחת מרחשת, מנחת מאפה תנור של חלות, ומנחת מאפה תנור של רקיקים). ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 נלמד מכאן שאם אמר \u0003\"ממיני מנחה\u0004 עלי\" — מנחה \u0003חדא\u0004 \u0005[אחת]\u0006 יביא!","ודוחים: אין זה דיוק הכרחי, \u0003דלמא\u0004 \u0005[שמא]\u0006 כך יש לדייק מדברי הברייתא: \u0003הא\u0004 \u0005[הרי]\u0006 נלמד מכאן שאם אמר \u0003\"מיני מנחה\u0004 עלי\" — \u0003מביא שתי מנחות משני מינין.\u0004","ומקשים על דחייה זו: \u0003והא לא תני הכי\u0004 \u0005[והרי לא שנינו כך],\u0006 ששנינו בהמשכה של אותה ברייתא, האומר \u0003\"מין מנחות עלי\"\u0004 — \u0003מביא שתי מנחות ממין אחד\u0004 מחמשת מיני המנחות. ואם אמר \u0003\"מיני מנחות עלי\"\u0004 — \u0003מביא שתי מנחות משני מינין.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 שאם אמר \u0003\"מיני מנחה\u0004 עלי\" — מנחה \u0003חדא\u0004 \u0005[אחת]\u0006 הוא מביא!","\u0005ומשיבים: אף זו אינה ראיה,\u0006 \u0003דלמא הא מני\u0004 \u0005[שמא\u0006 ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 בדינו של הנודר מנחת מאפה תנור, שאם רצה להביא \u0003מחצה\u0004 מלחמיה כ\u0003חלות ומחצה\u0004 מלחמיה כ\u0003רקיקין\u0004 — \u0003יביא, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 המשתמע מדברי הברייתא שמי שאמר \u0003\"מיני מנחה\u0004 עלי\" מביא מנחה אחת? הכוונה ל\u0003מנחה\u0004 אחת \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה תרי מיני\u0004 \u0005[שני מינים].\u0006","\u0003אבל\u0004 לשיטת \u0003רבנן דאמרי\u0004 \u0005[חכמים שאומרים]\u0006 כי \u0003מחצה חלות ומחצה רקיקין\u0004 — \u0003לא יביא,\u0004 ויש להביא את כל הלחמים ממין אחד, לכן האומר \"מיני מנחה עלי\" — \u0003מביא שתי מנחות משני מינין.\u0004","שנינו במשנתנו שהאומר \u0003\"פירשתי\u0004 בשעה שנדרתי אלו מיני מנחות אביא, ולאחר מכן שכחתי, \u0003ו\u0004עתה \u0003איני יודע מה\u0004 \u0003פירשתי\"\u0004 — \u0003יביא\u0004 \u0003חמשתן\u0004 (כל חמש המנחות: מנחת סולת, מנחת מחבת, מנחת מרחשת, ומנחות מאפה תנור של חלות ושל רקיקים). ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ששנה זאת?","\u0003אמר ר' ירמיה:\u0004 תנא זה שיטתו היא ש\u0003לא כ\u0004דעת \u0003ר' שמעון, דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא כדעת \u0003ר' שמעון\u0004 — \u0003כיון\u0004 ש\u0003אמר\u0004 ר' שמעון שהרוצה להביא למנחת מאפה תנור \u0003מחצה חלות ומחצה רקיקין יביא,\u0004 אף","\u0003אי נמי סבר לה\u0004 \u0005[אם גם כן סבור הוא]\u0006 \u0003כר' יהודה\u0004 ש\u0003אמר\u0004 ש\u0003כל המנחות באות עשר\u0004 עשר חלות (ולא כר' מאיר הסבור שכל המנחות באות שתים עשרה שתים עשרה חלות), מדוע במקרה זה שבמשנתנו הריהו מביא מן הספק רק חמש מנחות (המנויות למעלה), שהרי \u0003איכא לספוקה\u0004 \u0005[יש מקום להסתפק בו]\u0006 \u0003בארבע עשרה מנחות\u0004 שונות (שכן מלבד שלוש המנחות: מחבת, מרחשת וסולת, יש עוד אחד עשר אופנים שונים, לשיטת ר' שמעון, של הבאת עשרה לחמי מנחת מאפה תנור, בצירופים שונים של החלות והרקיקים לכלל עשרה לחמים).","\u0003אביי אמר\u0004 בדחיית דברי ר' ירמיה: \u0003אפילו\u0004 אם \u0003תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו היא כשיטת \u0003ר' שמעון,\u0004 אין זו קושיה, שכן \u0003שמעינן ליה\u0004 \u0005[שמענו אותו]\u0006 את \u0003ר' שמעון\u0004 ש\u0003אומר\u0004 כי במקרים של ספק אם חייב אדם בקרבן, \u0003מייתי\u0004 \u0005[מביא]\u0006 קרבן, \u0003ומתני\u0004 \u0005[ומתנה]\u0006 עליו שאם הוא חייב בו — יהא זה קרבן חובתו, ואם לא — יהא זה קרבן נדבה. ואף במקרה זה שבמשנתנו יביא חמש מנחות, ובכללן עשר חלות ועשרה רקיקים (לשני מיני מנחת מאפה תנור), ויתנה עליהם.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדינו של מי שנטהר מספק צרעת (החייב בהבאת אשם ולוג שמן לטהרתו), \u0003ר'\u0004 \u0003שמעון אומר: למחרת\u0004 שבעת ימי טהרתו, ביום השמיני, הריהו \u0003מביא\u0004 את \u0003אשמו ו\u0004את \u0003לוגו\u0004 (לוג היין)"],["\u0003עמו, ואומר\u0004 בדרך תנאי: \u0003אם\u0004 קרבן זה של \u0003מצורע הוא\u0004 — \u0003הרי\u0004 \u0003זהו אשמו וזה\u0004 הוא \u0003לוגו,\u0004 כדינו. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאין הוא מצורע — איל \u0003אשם זה יהא\u0004 של \u0003שלמי נדבה,\u0004 שכן דרך הקרבתם שווה.","\u0003ו\u0004כיצד נוהגים ב\u0003אותו אשם\u0004 של ספק? הריהו \u0003טעון\u0004 (צריך) \u0003שחיטה בצפון\u0004 העזרה, כדין האשם, \u0003ומתן\u0004 (ונתינה) מדמו על \u0003בהונות\u0004 המיטהר ועל אוזנו (יעוין ויקרא יד, יד), \u0003וסמיכה, ונסכים, ותנופת\u0004 (הנפת) \u0003חזה ושוק\u0004 כדין שלמים, \u0003ונאכל לזכרי כהונה ל\u0004משך \u0003יום ולילה,\u0004 כדין אשם (ולא לשני ימים, כדין השלמים).","ומעירים: \u0003ואף על גב דקא מפריק מר\u0004 \u0005[ואף על פי שהיה החכם מתרץ]\u0006 שאלה זו \u0003ב\u0004מסכת \u0003שחיטת קדשים\u0004 (מסכת זבחים עו,ב), בסוגיה בה נידונה השאלה האם מותר לדעת ר' שמעון להביא קדשים לבית הפסול, במקרה של ספק.","והביאו ראיה מדברי ר' שמעון אלה שהרי הוא ממעט בזמן אכילתם של קדשים, שאם לא ייאכלו הקרבנות בתוך יום ולילה (כזמן אכילת אשם), שוב לא יוכל לאוכלם (שמא קרבן אשם הוא, ונותר בשר הקרבן לאחר זמן אכילתו ונפסל בכך, ודינו לשריפה): \u0003אימר\u0004 \u0005[אמור]\u0006 מכאן שמה ש\u0003אמר ר' שמעון\u0004 שבספק \u0003מייתי ומתני\u0004 \u0005[מביא ומתנה]\u0006 על \u0003קרבנו,\u0004 \u0003אף\u0004 \u0003לכתחילה\u0004 — הרי זה רק בענין הנועד \u0003לתקוני גברא\u0004 \u0005[לתיקונו\u0006 של \u0005האיש],\u0006 וכגון בספק מצורע, שאין לו דרך אחרת להיטהר מצרעתו, אלא אם כן יביא קרבנו. \u0003אבל בעלמא\u0004 \u0005[בכלל],\u0006 בסתם ספק קרבנות, הרי \u0003דיעבד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מותר להביא ולהתנות על הקרבן. ואולם לעשות כן אף \u0003לכתחילה\u0004 — \u0003לא\u0004 אמר ר' שמעון.","ואולם \u0003הני מילי\u0004 \u0005[דברים אלה,\u0006 שלכתחילה אין פותרים ספיקות בדרך התנאה\u0005]\u0006 אמורים דווקא \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שלמים,\u0004 וטעם הדבר — משום \u0003דקא\u0004 \u0005[ש\u0006בכך \u0005הוא]\u0006 \u0003ממעט ב\u0004זמן \u0003אכילתן,\u0004 שצריכים הם עתה להיאכל בתוך יום ולילה בלבד (כדין אכילת אשם), ונמצא בכך \u0003דהוו להו\u0004 \u0005[שנעשו להם]\u0006 השלמים שלא נאכלו בתוך זמן זה \u0003קדשים\u0004 המובאים \u0003לבית הפסול,\u0004 לשריפה. \u0003אבל\u0004 לענין ספק \u0003מנחות,\u0004 שאין הוא יודע איזו מנחה פירש בנדרו — \u0003אפילו לכתחילה\u0004 מותר להביא ולהתנות. ונמצא איפוא שדברי משנתנו הריהם אף כשיטת ר' שמעון זו, וכדברי אביי.","למעלה שנינו שאביי מעמיד את דברי משנתנו אף כשיטת ר' שמעון. ובענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 כיצד ניתן להעמיד את משנתנו כשיטת ר' שמעון, והרי לדעת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 שיכול להביא למנחת מאפה תנור \u0003מחצה חלות ומחצה רקיקין\u0004 — \u0003יביא,\u0004 אם כן במקרה זה שבמשנתנו צריך הוא להביא עשר חלות ועשרה רקיקים ולהתנות עליהם, שחלק מהם יעלה לחובתו, והשאר יהיה לנדבה. וכן הריהו מביא שני לוגים שמן, לוג אחד לכל מנחה. ואולם כל עשרון סולת ולוג השמן שאתו התקדשו למנחה בכלי בפני עצמו (שזה התקדש לחלות, וזה התקדש לרקיקים). ונמצא כי \u0003הא קא מייתי\u0004 \u0005[הרי הוא מביא]\u0006 במקום מנחה אחת הבאה מ\u0003עשרון אחד,\u0004 מנחה אחת הבאה \u0003משני עשרון. ו\u0004בדומה לכך, נמצא שבמקום להביא מנחה אחת הבאה מ\u0003לוג אחד\u0004 שמן, הריהו מביא מנחה אחת הבאה \u0003משני לוגין!\u0004","ענה לו אביי לרב פפא: זו אינה שאלה, שכן כבר \u0003שמעינן ליה\u0004 \u0005[שמענו אותו]\u0006 את \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 ש\u0003אם הביא\u0004 במנחה כשיעור \u0003עשרון אחד\u0004 סולת, אף שבא \u0003משני עשרונות, ו\u0004כמו כן אם נתן במנחה כשיעור \u0003לוג אחד\u0004 של שמן, אף שבא השמן \u0003משני לוגין\u0004 — \u0003יצא\u0004 בכך ידי חובתו.","ושבים ושואלים: \u0003ו\u0004לדעת אביי \u0003מיקמץ היכי קמץ\u0004 \u0005[לקמוץ איך\u0006 הוא \u0005קומץ]\u0006 מנחה זו שמצורפות בה שתי מנחות לאחת, מהו לשון תנאו (לשיטת ר' שמעון)? ומשיבים: \u0003דמתני ואמר\u0004 \u0005[שמתנה ואומר]\u0006 כך: \u0003אי\u0004 \u0005[אם]\u0006 מאפה תנור של \u0003חלות לחודייהו\u0004 \u0005[בלבד]\u0006 פירשתי בנדרי, \u0003ו\u0004כן אם מאפה תנור של \u0003רקיקין לחודייהו\u0004 \u0005[בלבד]\u0006 הוא זה ש\u0003אמרי\u0004 \u0005[אמרתי]\u0006 בנדרי, הרי זה \u0003דקא קמיצנא\u0004 \u0005[שאני קומץ]\u0006 \u0003מחלות\u0004 — \u0003ליהוי\u0004 \u0005[שיהיה]\u0006 קומצם \u0005של\u0006 ה\u0003חלות,\u0004 וזה \u0003דקא קמיצנא\u0004 \u0005[שאני קומץ]\u0006 \u0003מרקיקין\u0004 — \u0003ליהוי\u0004 \u0005[שיהיה]\u0006 קומצם של ה\u0003רקיקין.\u0004 ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003מחצה רקיקין ומחצה חלות אמרי\u0004 \u0005[אמרתי]\u0006 בנדרי, הרי זה \u0003דקא קמיצנא\u0004 \u0005[שאני קומץ]\u0006 \u0003מ\u0004ה\u0003חלות\u0004 — \u0003ליהוי\u0004 \u0005[שיהיה]\u0006 על \u0003מחצה חלות ומחצה רקיקין, ודקא קמיצנא\u0004 \u0005[ו\u0006זה \u0005שאני קומץ]\u0006 \u0003מרקיקין\u0004 — \u0003ליהוו\u0004 \u0005[שיהיה]\u0006 גם הוא על \u0003מחצה רקיקין ומחצה חלות.\u0004","ושואלים על הצעה זו: \u0003והא\u0004 \u0005[והרי]\u0006 על המנחה שיש בה מן החלות ומן הרקיקים, אינו יכול לקמוץ מחלות בלבד \u0003אלא\u0004 \u0003בעי מיקמץ\u0004 \u0005[צריך לקמוץ]\u0006 \u0003חד קומץ\u0004 \u0005[קומץ אחד]\u0006 \u0003מחלות\u0004"],["\u0003ומרקיקין\u0004 כאחד, \u0003ו\u0004אילו באופן זה \u0003קא קמיץ\u0004 \u0005[הוא קומץ]\u0006 \u0003מחלות\u0004 לעצמן על מנחה שיש בה גם \u0003רקיקין, ומרקיקין\u0004 לעצמם על מנחה שיש בה \u0003חלות!\u0004","ומשיבים: אף זו אינה שאלה, שכן כבר \u0003שמעינן ליה\u0004 \u0005[שמענו אותו]\u0006 את \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 שהמביא מנחת מאפה תנור שחלק מלחמיה הם חלות וחלק רקיקים, ש\u0003אם קמץ ועלה בידו\u0004 בקומצו רק \u0003מאחד\u0004 מאלה, מחלות בלבד או מרקיקים בלבד \u0003על שניהם\u0004 — \u0003יצא\u0004 בכך ידי קמיצה.","ומקשים עוד על שיטת אביי: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003מותר שמן\u0004 הנשאר לאחר משיחתם של הרקיקים. ושנינו למעלה (עה,א) שמנחה הבאה מחציתה חלות ומחציתה רקיקים, שמביא לוג שמן, וחוצהו לשנים, את המחצית האחת נותן לבלילתן של החלות, ובמחצית השניה הוא מושח את הרקיקים. ושאר השמן הנשאר ממשיחת הרקיקים ניתן אף הוא לבלילת החלות. ואולם מנחה שכולה רקיקים, השמן הנותר לאחר המשיחה, ניתן לכהנים. ומעתה יש לשאול לשיטת ר' שמעון, \u0003דאי\u0004 \u0005[שאם]\u0006 מנחה של \u0003מחצה חלות ומחצה רקיקין\u0004 הוא זה \u0003ש\u0004\u0003אמר\u0004 בנדרו — דינו של \u0003מותר השמן\u0004 שהוא \u0003מחזירו לחלות.\u0004 ואולם, \u0003אי\u0004 \u0005[אם]\u0006 מנחה שכל לחמיה \u0003כולהו\u0004 \u0005[כולם]\u0006 של \u0003רקיקין\u0004 הוא ש\u0003אמר\u0004 בנדרו — דינו של \u0003מותר השמן\u0004 שהוא \u0003נאכל לכהנים!\u0004","ומשיבים: הוא סבור \u0003כ\u0004דעת \u0003ר' שמעון בן יהודה,\u0004 שאמר בשם ר' שמעון, שאף מותר השמן במנחה שהיא מחצה חלות ומחצה רקיקים ניתן לכהנים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יהודה אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון:\u0004 גם את החלות \u0003מושחן כמין\u0004 האות היוונית \u0003כי, ומותר השמן נאכל לכהנים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא לרב אשי\u0004 בשאלה: מדוע האומר שפירש בנדרו איזו מנחה עליו להביא, ושכח עתה מהי אותה מנחה, מביא רק את חמשת מיני המנחות, \u0003והא איכא לספוקה\u0004 \u0005[והרי יש\u0006 מקום \u0005להסתפק]\u0006 בסוג נוסף של מנחה, \u0003במנחת נסכים\u0004 (הבאה עם קרבנות עולה שונים), שאף היא באה בנדבה, שכן \u0003אמר רבא: מתנדב אדם מנחת נסכים בכל יום!\u0004","ומשיבים: אין מנחת נסכים בכלל הספק, שכן \u0003כי קא מסתפקא ליה\u0004 \u0005[כאשר הוא מסופק לו]\u0006 איזו מנחה נדב, הרי זה במנחות מסויימות. ומפרטים (ונותנים \u0003סימן\u0004 לזכרון מהם אותם דברים שיוזכרו להלן: מנחה הבאה כקרבן \u0003יחיד;\u0004 מנחה הבאה \u0003בגלל\u0004 עצמה; מנחה החייבת ב\u0003לבונה;\u0004 מנחה הבאה \u0003בלוג\u0004 אחד של שמן; מנחה שהוא \u0003מקמצה,\u0004 ולא הפטורה מקמיצה: בכלל הספק מנחה ה","\u0003באה\u0004 רק \u0003בגלל\u0004 (בעקבות נדבתו של) \u0003יחיד\u0004 כחמשת מיני המנחות הללו, אבל במנחת נסכים, שהיא \u0003באה\u0004 אף \u0003בגלל ציבור,\u0004 בקרבנות ציבור — \u0003לא מסתפקא ליה\u0004 \u0005[לא מסופק לו].\u0006","ועוד: \u0003כי קא מסתפקא ליה\u0004 \u0005[כאשר מסופק לו]\u0006 — הרי זה דווקא במנחה ה\u0003באה בגלל עצמה,\u0004 כחמשת מיני המנחות הללו, אבל במנחת נסכים, שכאשר היא באה בחובה הריהי \u0003באה בגלל זבח,\u0004 משום הקרבן, ולא מכח עצמה — \u0003לא מסתפקא ליה\u0004 \u0005[לא מסופק לו].\u0006","ועוד: \u0003כי קא מסתפקא ליה\u0004 \u0005[כאשר מסופק לו]\u0006 — הרי זה דווקא במנחה ה\u0003טעונה\u0004 הבאת \u0003לבונה\u0004 עמה, כאותם חמשת מיני המנחות, אבל במנחת נסכים, \u0003שאינה טעונה לבונה\u0004 — \u0003לא מסתפקא ליה\u0004 \u0005[לא מסופק לו].\u0006","ועוד: \u0003כי קא מסתפקא ליה\u0004 \u0005[כאשר מסופק לו]\u0006 — הרי זה דווקא במנחה ה\u0003באה בלוג\u0004 אחד של שמן (לעשרון סולת), כחמשת מיני המנחות הללו, אבל במנחת נסכים, ה\u0003באה\u0004 \u0003בשלשה לוגין\u0004 (הם כמידת \"רביעית ההין\". במדבר טו, ה. האמורה בנסכים הבאים עם קרבן הכבש), ובארבעה לוגים (\"שלישית ההין\". שם ו, האמורה בנסכים הבאים עם האיל) ובששה לוגים (\"חצי ההין\". שם ט, האמור בנסכים הבאים עם הפר) — \u0003לא מסתפקא ליה\u0004 \u0005[לא מסופק לו].\u0006","ועוד: \u0003כי קא מסתפקא ליה\u0004 \u0005[כאשר מסופק לו]\u0006 — הרי זה דווקא במנחה ה\u0003טעונה קמיצה,\u0004 כחמשת מיני המנחות הללו, מה שאין כן מנחת נסכים, \u0003שאינה טעונה קמיצה\u0004 — \u0003לא קא מסתפקא ליה\u0004 \u0005[לא מסופק לו].\u0006","שנינו במשנתנו שהאומר \u0003\"פירשתי\u0004 בשעה שנדרתי שעלי להביא \u0003מנחה של עשרונים,\u0004 ושכחתי, ואיני יודע עתה כמה עשרונים פירשתי בנדרי\" — שלדעת חכמים יביא מנחה של ששים עשרונים, ולדעת רבי יביא ששים מנחות, ממנחה שיש בה עשרון אחד ועד למנחה שיש בה ששים עשרונים.","ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא, האומר \u0003\"פירשתי\u0004 בנדרי כמה עשרונים עלי להביא ב\u0003מנחה\u0004 מסויימת, \u0003וקבעתי\u0004 שמנחה זו שאביא תהיה \u0003בכלי אחד של עשרונים,\u0004 ושכחתי מה נדרתי, \u0003ו\u0004עתה \u0003איני יודע מה פירשתי\"\u0004 — \u0003יביא מנחה\u0004 אחת \u0003של ששים עשרונים,\u0004 אלו \u0003דברי חכמים. רבי אומר: יביא\u0004 ששים \u0003מנחות\u0004 בששים כלים \u0003של עשרונים\u0004 \u0003מ\u0004עשרון \u0003אחד ועד ששים\u0004 עשרונים, \u0003שהן\u0004 בסך הכל \u0003אלף ושמונה מאות ושלשים\u0004 מנחות.","ואם אומר הנודר כי \"בשעה שנדרתי \u0003פירשתי\u0004 בנדרי להביא מנחה מסויימת בכלי אחד שיש בה מספר מסויים של עשרונים, ושכחתי, \u0003ו\u0004עתה \u0003איני\u0004 \u0003יודע מה פירשתי, ואי זו מהן\u0004 מכלל חמש המנחות \u0003פירשתי\u0004 שאביא בנדרי, \u0003ואיני יודע כמה\u0004 עשרונים שיהיו במנחה \u0003פירשתי\"\u0004 — \u0003יביא\u0004 מספק את \u0003חמש\u0004 סוגי ה\u0003מנחות, של ששים ששים עשרונים\u0004 בכל אחת מהן, \u0003שהן\u0004 \u0003שלש מאות\u0004 עשרונים, אלו \u0003דברי חכמים. רבי אומר: יביא חמש מנחות,\u0004 שכל אחת מאלה \u0003של ששים\u0004 מנחות שיש בהן מספר \u0003עשרונים מאחד ועד ששים, שהן תשעה אלפים ומאה וחמשים\u0004 עשרונים.","ומבררים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזו שאלה, \u0005הם,\u0006 חכמים ורבי, \u0005חלוקים]?\u0006 \u0003אמר רב חסדא: ב\u0004שאלה האם \u0003מותר להכניס חולין לעזרה קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 ש\u0003רבי סבר\u0004 \u0005[סבור]\u0006 כי \u0003אסור להכניס חולין לעזרה,\u0004 ולכן אין להביא בכלי אחד מנחה של ששים עשרונים — שהרי ספק הוא מה נדר, ואפשר שנדר מנחה בת פחות מששים עשרונים, ועתה כשמביא ששים עשרונים הריהו מכניס חולין לעזרה. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003מותר להכניס חולין לעזרה,\u0004 ולכך אף שיתכן שהוא מכניס חולין לעזרה — אין בכך כלום.","\u0003רבא אמר\u0004 הסבר אחר ביסוד מחלוקת חכמים ורבי: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 ואף לחכמים \u0003אסור להכניס חולין לעזרה,\u0004 \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה האם \u0003מותר לערב חובה בנדבה\u0004 \u0003קא מיפלגי\u0004 \u0005[חלוקים הם].\u0006","\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003מותר לערב חובה בנדבה,\u0004 ולכך יכול הוא להביא בכלי אחד ששים עשרונים, ולהתנות שכמספר העשרונים שנדר בשעתו — יעלו לו לקרבן חובתו, ושאר העשרונים שבמנחה — יהיו בנדבתו, ולהביאם יחד, אף שמעורבים הם. \u0003ו\u0004אילו \u0003רבי סבר\u0004 \u0005[סבור]\u0006 כי \u0003אסור לערב חובה בנדבה,\u0004 ולכך אינו יכול להביא ששים עשרונים בכלי אחד, ולהתנות, אלא צריך להביא ששים כלים נפרדים, שבכל אחד מספר עשרונים מאחד ועד ששים, ולהתנות שאותה מנחה שיש בה כמספר העשרונים שנדר — תעלה לו לחובתו, ושאר המנחות שבשאר הכלים — יבואו בנדבתו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא\u0004 בשאלה: \u0003ל\u0004שיטת \u0003רבנן דאמרי\u0004 \u0005[חכמים שאומרים]\u0006 ש\u0003מותר לערב חובה בנדבה,\u0004 ולפיכך מותר להביא בכלי אחד ששים עשרונים, חלקם חובה וחלקם נדבה — \u0003הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 מעתה קמיצתם \u0003של\u0004 \u0003שני קמצים\u0004 ממנחה זו, אחד ממנחת החובה ואחד ממנחת הנדבה! השיב רבא: לשיטת חכמים, אכן הריהו קומץ פעמיים, \u0003דקמיץ והדר קמיץ\u0004 \u0005[שקומץ וחוזר\u0006 ו\u0005קומץ].\u0006","הקשה על כך אביי: \u0003והא\u0004 \u0005[והרי]\u0006 כיון שמעורבות הן מנחת החובה ומנחת הנדבה בכלי אחד, ואינן ניכרות לעצמן, יתכן ש\u0003קא קמיץ\u0004 \u0005[הוא\u0006 הכהן \u0005קומץ]\u0006 \u0003מ\u0004ה\u0003חובה\u0004 על ה\u0003נדבה ו\u0004כן להיפך, \u0003מ\u0004ה\u0003נדבה\u0004 על \u0003ה\u0004\u0003חובה!\u0004","השיב רבא: אין זו שאלה, שכן מדובר באופן \u0003דתלי ליה\u0004 \u0005[שתולה אותו]\u0006 מביא המנחה \u0003בדעת\u0004 ה\u0003כהן\u0004 הקומץ. שכך \u0003אמר\u0004 מביא המנחה מראש: \u0003כל היכא דמטיא ידא\u0004 \u0005[כל היכן שתגיע ידו]\u0006 של ה\u0003כהן השתא\u0004 \u0005[עכשיו]\u0006 בקמיצה הראשונה — יהיה זה מקומה של מנחת \u0003חובה, ו\u0004כל מקום בו תגיע ידו בקמיצה \u0003לבסוף\u0004 בפעם השניה — יהיה זה מקומה של מנחת ה\u0003נדבה.\u0004","והוסיף אביי ושאל את רבא: \u0003ואקטורי היכי מקטר\u0004 \u0005[ולהקטיר\u0006 את שני הקמצים הללו, \u0005איך\u0006 הוא \u0003מקטיר]?\u0004 שכן אם תאמר ש\u0003ליקטר\u0004 \u0005[\u0006ש\u0005יקטיר]\u0006 את הקומץ של מנחת ה\u0003נדבה ברישא\u0004 \u0005[בתחילה]\u0006 — אם כן, את הקומץ של מנחת ה\u0003חובה\u0004 \u0003היכי מקטר לה\u0004 \u0005[איך\u0006 הוא \u0005מקטיר אותו]?\u0006 שהרי יש מקום לחשש \u0003דלמא\u0004 \u0005[שמא]\u0006 נדר להביא מנחה של ששים עשרונים, ו\u0003כולה\u0004 איפוא \u0003חובה היא,\u0004 וחייבת היא בקמיצת קומץ אחד, ושאר המנחה הריהי בכלל \"שירים\". \u0003ו\u0004נמצא איפוא שכשקמץ למנחת נדבה קודם שקמץ למנחת החובה \u0003חסרו להו\u0004 \u0005[להם]\u0006 ה\u0003שירים,\u0004 שהרי הוקטר כבר אותו קומץ לנדבה (שלמעשה הריהו חלק מהשיריים של מנחת החובה),","\u0003ו\u0004הרי \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא ש\u0003שירים שחסרו בין\u0004 ה\u0003קמיצה\u0004 של המנחה \u0003להקטרה\u0004 של הקומץ — \u0003אין מקטיר קומץ עליהן!\u0004","ואם תאמר \u0003ליקטר\u0004 \u0005[\u0006ש\u0005יקטיר]\u0006 את קומץ מנחת ה\u0003חובה ברישא\u0004 \u0005[בתחילה],\u0006 אם כן, את הקומץ של מנחת ה\u0003נדבה היכי מקטר לה\u0004 \u0005[איך\u0006 הוא \u0005מקטיר אותו]?\u0006"],["\u0003ו\u0004הרי יש מקום לחשש \u0003דלמא\u0004 \u0005[שמא]\u0006 נדר להביא מנחה של ששים עשרונים, ואז המנחה \u0003כולה חובה היא\u0004 (החייבת היא בקמיצת קומץ אחד ושאר כל המנחה היא \"שיריים\", \u0003ו\u0004כלל הוא ש\u0003כל\u0004 דבר קודש \u0003שהוא\u0004 חלק \u0003ממנו\u0004 ניתן \u0003לאישים\u0004 (מוקרב על המזבח) \u0003הרי הוא\u0004 (שאר הקרבן) \u0003ב\u0004כלל האיסור \u0003\"בל תקטירו\"\u0004 (\"...כי כל שאור וכל דבש לא תקטירו ממנו אשה לה' \".","ויקרא ב, יא \u0003—\u0004 שאין להקריב על המזבח דברים שאינם ראוים לקרבן). ואם כן כיצד מקטירים את הקומץ השני (של מנחת הנדבה), לאחר שכבר הוקטר הקומץ הראשון (של מנחת החובה)! \u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי:\u0004 בתחילה אכן מקטירים את הקומץ של מנחת החובה, ובאשר להקטרת הקומץ השני — יש לומר \u0003דמסיק להו\u0004 \u0005[שמעלה אותם\u0006 על המזבח\u0005],\u0006 לא לשם הקטרת קומץ, אלא \u0003לשום\u0004 \u0005[לשם]\u0006 \u0003עצים\u0004 הנשרפים במערכה. \u0003וכ\u0004שיטת \u0003ר' אליעזר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 יש דברים ש\u0003לריח ניחוח\u0004 (כקרבן העולה על המזבח) \u0003אי\u0004 (אין) \u0003אתה מעלה, אבל אתה מעלה\u0004 אותם על המזבח \u0003לשום\u0004 \u0005[לשם]\u0006 \u0003עצים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 \u0003ודלמא\u0004 \u0005[ושמא]\u0006 נאמר כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל,\u0006 ואף לדעת חכמים\u0005]\u0006 אסור להכניס חולין לעזרה, וכמו כן לדעת הכל, ואף לדעת רבי, \u0003מותר לערב חובה בנדבה, ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004דברי \u0003ר' אליעזר קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 ובאופן זה: \u0003דרבנן\u0004 \u0005[שחכמים]\u0006 הסבורים שמביא ששים עשרונים בכלי אחד \u0003—\u0004 \u0003אית להו\u0004 \u0005[יש להם,\u0006 מקבלים\u0005]\u0006 את שיטת \u0003ר' אליעזר\u0004 שמותר להעלות למזבח, לשם עצים, את האסור בהקטרה, ולכן יש תקנה למנחה המסופקת, שיכול הוא לקמוץ שני קמצים, האחד לשם חלק מנחת החובה שבששים העשרונים, והאחר לשם מנחת נדבה שבתוך ששים העשרונים, ויקטיר את קומץ מנחת החובה לשם חובתו, ואת קומץ מנחת הנדבה לשם עצים. \u0003ו\u0004אילו \u0003רבי\u0004 הסבור שיש להביא ששים מנחות מעשרון אחד ועד ששים עשרונים \u0003—\u0004 \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את שיטת \u0003ר' אליעזר?!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: אין לומר כן, שהרי \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003ל\u0004דעת \u0003רבי מותר לערב חובה בנדבה,\u0004 ולכך היה מקום אף לשיטת רבי להביא ששים עשרונים בלבד (ולהתנות עליהם שהחלק שנדר יהיה לחובה והשאר יהיה לנדבה, וכחכמים), \u0003ו\u0004הטעם שלדעת רבי אין לעשות כן הוא מפני שרבי את שיטת \u0003ר' אליעזר לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005],\u0006 \u0005משום כך לא היה צריך רבי להצריך את הנודר להביא ששים מנחות שונות, שכן\u0006 \u0003אפשר\u0004 לו \u0003דמייתי שיתין\u0004 \u0005[שיביא ששים]\u0006 עשרונים \u0003בחד מנא\u0004 \u0005[בכלי אחד]\u0006 וכחכמים, \u0003ו\u0004יביא עוד עשרון \u0003חד\u0004 \u0005[אחד]\u0006 של מנחה לנדבה \u0003בחד מנא\u0004 \u0005[בכלי אחד],\u0006 \u0003ומגע להו\u0004 \u0005[ומגיע אותם,\u0006 גורם להם שיגעו זה בזה\u0005],\u0006 והריהם נחשבים כדבר אחד, \u0003ו\u0004מעתה \u0003קמיץ\u0004 \u0005[קומץ]\u0006 מאותו עשרון על חלק מששים העשרונים שהם לנדבה, ומתוך ששים העשרונים הריהו קומץ על אותו חלק שהוא לחובתו! אלא על כרחך אין להסביר את מחלוקת חכמים ורבי כר' אליעזר\u0005.\u0006","ועוד הסבר במחלוקתם של חכמים ורבי, \u0003רבא אמר: דכולי עלמא\u0004 \u0005[לדעת הכל],\u0006 ואף לדעת רבי \u0003מותר לערב חובה בנדבה,\u0004 \u0003ו\u0004כמו כן \u0003דכולי עלמא אית להו\u0004 \u0005[לדעת הכל,\u0006 ואף לדעת רבי \u0005יש להם,\u0006 מקבלים\u0005]\u0006 את שיטת \u0003ר' אליעזר\u0004 האומרת שמותר להעלות למזבח, לשם עצים, את האסור בהקטרה. \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן],\u0006 בדין המנחה המסופקת, \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' אליעזר בן יעקב ורבנן קא מיפלגי\u0004 \u0005[וחכמים הם חלוקים],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 (לעיל מנחות פח,א):","\u0003אפילו מנחה של ששים עשרון\u0004 סולת \u0003—\u0004 \u0003נותן לה ששים לוג\u0004 שמן. \u0003ר' אליעזר בן יעקב אומר: אפילו מנחה של ששים עשרון\u0004 סולת \u0003—\u0004 \u0003אין לה אלא לוגה,\u0004 הלוג שלה, לוג אחד בלבד. \u0003ש\u0004כן \u0003נ\u0004 \u0003אמר\u0004 בפרשת המצורע \u0003\"למנחה ולג שמן\"\u0004 (ויקרא יד, כא)","\u0003—\u0004 להורות, שכל מנחה, בכל גודל, אינה טעונה אלא לוג אחד של שמן. וכך תוסבר מחלוקת חכמים ורבי: \u0003רבנן\u0004 \u0005[חכמים]\u0006 של משנתנו \u0003—\u0004 \u0003סברי כרבנן\u0004 \u0005[סבורים כחכמים\u0006 החולקים על ר' אליעזר בן יעקב\u0005]\u0006, \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 שיש להביא למנחה של ששים עשרונות \u0003ששים לוג\u0004 שמן. ולכך אף במנחה המסופקת, אפשר להביא ששים עשרונים בכלי אחד, \u0003וכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 \u0003עשרון\u0004 שבששים העשרונות הללו, \u0003לוגה קא שקיל\u0004 \u0005[הוא מקבל לוג\u0006 אחד\u0005],\u0006 כדין.","\u0003ו\u0004אילו \u0003רבי\u0004 \u0003—\u0004 \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003כר' אליעזר בן יעקב,\u0004 ש\u0003אמר\u0004 כי \u0003אין לה\u0004 (למנחה, בכל גודל) \u0003אלא לוגה\u0004 בלבד. \u0003ו\u0004לכן במקרה זה של מנחה מסופקת אין אפשרות להביא ששים עשרונים במנחה אחת, שהרי \u0003לא ידעינן\u0004 \u0005[אין אנו יודעים]\u0006 \u0003אי חדא\u0004 \u0005[אם אחת]\u0006 \u0003מנחה היא\u0004 זו (וכגון שנדב ששים עשרונים, וכולה מנחה של חובה) \u0003—\u0004 \u0003דסגי\u0004 \u0005[שדי]\u0006 \u0003לה\u0004 איפוא \u0003בחד\u0004 \u0005[באחד]\u0006 \u0003לוג\u0004 שמן, \u0003אי\u0004 \u0005[או]\u0006 ש\u0003שתי מנחות נינהו\u0004 \u0005[הן],\u0006 שחלק מהעשרונים של מנחת חובה, וחלק של מנחת נדבה \u0003—\u0004 \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 לתת בהן \u0003שני לוגין\u0004 של שמן, לוג אחד לכל מנחה.","ולכך אין דרך לפתרון הספק אלא להביא ששים מנחות שונות, בששים כלים, ובכל אחת מהן ינתן לוג שמן (כשיטת ר' אליעזר בן יעקב) \u0003.\u0004 \u0003רב אשי אמר\u0004 הסבר אחר למחלוקת חכמים ורבי: ש\u0003ב\u0004דינו של זה שהתחייב להביא קרבן \u0003קטן ו\u0004במקום זה \u0003הביא\u0004 קרבן \u0003גדול\u0004 \u0003קמיפלגי\u0004 \u0005[הם חלוקים].\u0006 \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 שאם נדר להביא קרבן \u0003קטן והביא\u0004 קרבן \u0003גדול\u0004 — \u0003יצא\u0004 בכך ידי חובתו. ולכך אף במקרה שבמשנתנו, יכול הוא להביא מנחה של ששים עשרונות, אף אם בשעתו נדר מנחה בת פחות עשרונים. \u0003ו\u0004אילו \u0003רבי סבר\u0004 \u0005[סבור]\u0006 כי הנודר מנחה קטנה והביא מנחה גדולה \u0003לא יצא\u0004 בכך ידי חובתו, שהרי לא הביא כפי שנדר. ולכך במקרה שבמשנתנו, אינו יכול להביא מנחה בת ששים עשרונים, שמא נדר מנחה הקטנה מכך. ואינו יוצא ידי ספקו, אלא כשמביא ששים מנחות בגדלים שונים, שאחת מהן היא כשיעור המנחה שנדר, והשאר תהיינה לנדבה.","ושואלים על הסברו זה של רב אשי: \u0003והא איפלגו\u0004 \u0005[והרי\u0006 כבר \u0005נחלקו]\u0006 חכמים ורבי \u0003בה\u0004 בשאלה זו \u0003חדא זמנא\u0004 \u0005[פעם אחת],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה בפרקנו\u0005]:\u0006 הנודר לקרבן שור \u0003קטן והביא\u0004 שור \u0003גדול\u0004 — \u0003יצא\u0004 ידי חובתו. \u0003רבי אומר: לא יצא\u0004 ידי חובתו. ומה טעם יחלקו אף במשנתנו בעקרון זה?","ומשיבים: אף על פי כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו הדברים בשני המקרים. שכן, \u0003דאי איתמר בהא\u0004 \u0005[שאם\u0006 היתה מחלוקתם \u0005נאמרת\u0006 רק \u0005בזו,\u0006 במשנתנו\u0005]\u0006 — הייתי אומר כי דווקא \u0003בהא\u0004 \u0005[ב\u0006הלכה \u0005זו]\u0006 בנודר להביא קרבן קטן והביא גדול \u0003קא אמרי רבנן\u0004 \u0005[הוא\u0006 ש\u0005אמרו חכמים]\u0006 שיצא ידי חובתו, ו\u0003משום דאידי ואידי\u0004 \u0005[ש\u0006גם ב\u0005זו,\u0006 המנחה הקטנה, \u0005ו\u0006גם ב\u0005זו,\u0006 המנחה הגדולה\u0005]\u0006 \u0003קומץ\u0004 אחד \u0003הוא\u0004 שנקמץ, ודרך עבודתם איפוא שווה. \u0003אבל התם\u0004 \u0005[שם].\u0006 בנודר שור קטן והביא שור גדול, \u0003דקא נפישי\u0004 \u0005[שהם רבים,\u0006 גדולים יותר\u0005]\u0006 ה\u0003אימורין\u0004 (חלק הקרבן הקרב על המזבח) של \u0003השור הגדול מאלה של השור הקטן,\u0004 \u0003אימא מודו ליה\u0004 \u0005[אמור\u0006 ש\u0005מודים\u0006 חכמים \u0005לו]\u0006 \u0003לרבי\u0004 שהמביא שור גדול במקום שור קטן שנדר, לא יצא בכך ידי חובתו. ולכך נצרך לשנות גם את ההלכה ההיא.","\u0003ו\u0004מן הצד האחר, \u0003אי איתמר\u0004 \u0005[ואם היתה\u0006 מחלוקתם של חכמים ורבי \u0005נאמרת]\u0006 רק \u0003בההיא\u0004 \u0005[באותה]\u0006 משנה בענין שור קטן ושור גדול — \u0005הייתי אומר כי דווקא\u0006 \u0003ב\u0004הלכה \u0003ההיא,\u0004 בענין הקרבנות \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003רבי\u0004 שלא יצא ידי חובתו, ומשום הטעם שמרובים הם אימוריו של השור הגדול מזה של השור הקטן. \u0003אבל בהא\u0004 \u0005[ב\u0006מקרה \u0005זה\u0006 שבמשנתנו\u0005]\u0006 במנחה המסופקת, ששוים הם הקומץ המורם ממנחה גדולה לזה המורם ממנחה קטנה, \u0003אימא מודי להו לרבנן\u0004 \u0005[אמור\u0006 שרבי \u0005מודה להם לחכמים],\u0006 ואף לדעתו יצא בכך ידי חובתו. על כן \u0003צריכא\u0004 \u0005[צריכה]\u0006 מחלוקת זו להיאמר בשני המקומות הללו\u0005.\u0006","\u0005ונותנים\u0006 \u0003סימן\u0004 \u0005להלכות שבמשניות שתבואנה להלן:\u0006 \u0003עצים. זהב. יין. עולה. תודה. שור.\u0004","הנודר \u0003\"הרי עלי\u0004 להביא למקדש \u0003עצים\",\u0004 ולא פירש כמה עצים — \u0003לא יפחות משני גזירין\u0004 (חתיכות עץ), כגזירי העץ שאותם עורכים על המזבח. האומר \"הרי עלי להביא \u0003לבונה\"\u0004 — \u0003לא יפחות מקומץ.\u0004","ואומרים בעניינו של הקומץ, כי \u0003חמשה קמצים הם: האומר\u0004 \"הרי \u0003עלי לבונה\"\u0004 — \u0003לא יפחות מקומץ,\u0004 כאמור; \u0003המנדב\u0004 להביא \u0003מנחה\u0004 — \u0003יביא עמה\u0004 אף \u0003קומץ לבונה; המעלה\u0004 (המקטיר) \u0003את הקומץ בחוץ\u0004 לעזרה — \u0003חייב\u0004 כרת, אם עשה כן במזיד; \u0003שני בזיכין\u0004 של לבונה הבאים עם לחם הפנים הריהם \u0003טעונין שני קמצים\u0004 של לבונה, בכל אחד קומץ.","ועוד בדיני לשונות נדבה שאינם מפורשים, הנודר ואומר \u0003\"הרי עלי\u0004 להביא \u0003זהב\u0004 לבדק הבית\" ולא פירש כמה זהב — \u0003לא יפחות מדינר זהב.\u0004 האומר \"הרי עלי להביא לבדק הבית \u0003כסף\"\u0004 — \u0003לא יפחות\u0004 \u0003מדינר כסף.\u0004 אמר \"הרי עלי להביא לבדק הבית \u0003נחשת\"\u0004 — יביא נחושת ששוויה \u0003לא יפחות ממעה כסף.\u0004 ואם אמר \u0003\"פירשתי\u0004 בשעה שנדרתי כמה זהב (וכיוצא בזה, כסף או נחושת) עלי להביא, ושכחתי מה אמרתי, \u0003ו\u0004עתה \u0003איני יודע מה\u0004 \u0003פירשתי\u0004 בנדרי\" — \u0003יהא מביא\u0004 זהב עוד ועוד, \u0003עד שיאמר\u0004 \"הסכום הזה גדול מדי, ש\u0003לא לכך\u0004 \u0003נתכוונתי,\u0004 אלא לפחות מזה\".","שנינו במשנתנו את דינו של הנודר עצים, ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר בפרשת המנחות \"ונפש כי תקריב קרבן מנחה לה'...\" (ויקרא ב, א), והמלה \u0003\"קרבן\"\u0004 לכאורה מיותרת. אלא הריהו \u0003מלמד שמתנדבין\u0004 גם \u0003עצים\u0004 להקריב על המזבח, כדרך שמתנדבים מנחה. \u0003וכמה\u0004 (מה שיעורה של נדבת עצים)? \u0003שני גזירין. ו\u0004ראיה לדבר שאף העצים באים כקרבן, ש\u0003כן הוא אומר\u0004 בסדרי המקדש שהתקינו בימי נחמיה \u0003\"והגורלות הפלנו על קרבן העצים\u0004 הכהנים והלוים והעם להביא לבית אלהינו לבית אבותינו לעתים מזומנים שנה בשנה לבער על מזבח ה' אלהינו ככתוב בתורה\" (נחמיה י, לה). \u0003רבי אומר: עצים\u0004 אלה \u0003קרבן הם,\u0004 כקרבן מנחה, ולכן הריהם \u0003טעונין מלח וטעונין הגשה\u0004 אל קרן המזבח, כקרבן המנחה.","\u0003אמר רבא: ולדברי רבי\u0004 הללו, יש להוסיף עוד שה\u0003עצים טעונין קמיצה,\u0004 כדינה של המנחה. שצריך ליטול חלק מהם, ולפוררם לחלקים קטנים, כדי קמיצה בכף היד. הוסיף ו\u0003אמר רב פפא: לדברי רבי\u0004 הללו, \u0003עצים\u0004 שהוקדשו לקרבן, כיון שמעתה הם קרבן הקרב על המזבח, \u0003צריכין\u0004 הם \u0003עצים\u0004 אחרים של הקדש, שיבערום, כדרך כל קרבן הנשרף על גבי המזבח.","שנינו במשנתנו שהנודר \u0003לבונה\u0004 \u0003לא יפחות מן הקומץ.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדין המנחה \u0003\"והרים ממנו בקמצו מסלת המנחה ומשמנה ואת כל הלבנה\u0004 אשר על המנחה והקטיר המזבח ריח ניחוח אזכרתה לה' \" (ויקרא ו, ח) — \u0003מקיש\u0004 (משווה) הכתוב את ה\u0003לבונה\u0004 (\"ואת כל הלבונה אשר על המנחה\") \u0003ל\u0004חלק המנחה בו מתקיימת מצות \u0003הרמה\u0004 של ה\u0003מנחה\u0004 (\"והרים ממנו בקומצו מסולת המנחה ומשמנה\"), לומר: \u0003מה\u0004 שיעור \u0003הרמה\u0004 של \u0003מנחה\u0004 — הריהו \u0003קומץ,\u0004 כמפורש בכתוב, \u0003אף\u0004 שיעור ה\u0003לבונה נמי\u0004 \u0005[גם כן]\u0006 הריהו \u0003קומץ.\u0004","ועוד בדיני נדבת לבונה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: אמר \u0003\"הרי עלי למזבח\"\u0004 ולא פירש מה נודר — \u0003יביא לבונה, שאין לך דבר שקרב לגבי מזבח\u0004 בשלימות \u0003אלא לבונה.\u0004 אמר \"בשעה שנדרתי \u0003פירשתי\u0004 מה אני רוצה להביא למזבח, ושכחתי לאחר מכן, \u0003ו\u0004עתה \u0003איני יודע מה פירשתי\"\u0004 — \u0003יביא מכל דבר שקרב למזבח.\u0004","ושואלים: \u0003ותו ליכא\u0004 \u0005[ועוד\u0006 דברים \u0005הקרבים כולם על המזבח\u0006 \u0005אין]?\u0006 \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 קרבן \u0003עולה\u0004 שקרב הוא כולו על המזבח! ומשיבים: אין כל קרבן העולה \u0003קרב על המזבח, שהרי\u0004 \u0003איכא\u0004 \u0005[יש]\u0006 את \u0003עורה\u0004 של הבהמה, שאינו קרב על המזבח, אלא ניתן \u0003לכהנים.\u0004","ושואלים שוב: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 את \u0003עולת העוף\u0004 הנשרפת כולה על המזבח, ואף עורה בכלל! ומשיבים: אף עולת העוף אינה קריבה כולה על המזבח, שהרי \u0003איכא\u0004 \u0005[יש]\u0006"],["בה \u0003מוראה ונוצה\u0004 שאינם קרבים, אלא נזרקים אצל המזבח.","ושואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 יין \u0003ה\u0004\u0003נסכים\u0004 שניתנים כולם על המזבח! ומשיבים: אין הם קרבים ממש על המזבח, אלא ניתנים לספלים שעל המזבח, ומשם \u0003לשיתין\u0004 (החללים שמתחת למזבח) הם \u0003אזלי\u0004 \u0005[הולכים].\u0006","ועוד שואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003מנחת נסכים,\u0004 שכולה נשרפת על עצי המערכה שבמזבח! ומשיבים: כשאומר בלשון סתומה \"הרי עלי למזבח\", ניכר מתוך דבריו שהתכוון לדבר שעניינו ברור שהוא למזבח בלבד. ואולם מנחת נסכים, מאחר והיא מכלל המנחות, אם כן \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003מנחה\u0004 אחרת שאינה עולה כולה על המזבח, היא מנחת נדבה, \u0003דאכלי\u0004 \u0005[שאוכלים]\u0006 \u0003כהנים מינה\u0004 \u0005[ממנה]\u0006 (לאחר שהוקטר קומץ ממנה) — שוב \u0003לא פסיקא ליה\u0004 \u0005[אין\u0006 זה \u0005פסוק לו,\u0006 ברור\u0005]\u0006 שעולה כולה למזבח, ובודאי לא התכוין אלא ללבונה.","שנינו במשנתנו שהאומר \u0003\"הרי עלי זהב\" לא\u0004 \u0003יפחות מדינר זהב. ו\u0004שואלים: מנין לנו שכוונתו היתה למטבע זהב, \u0003דלמא\u0004 \u0005[שמא]\u0006 היתה כוונתו ל\u0003נסכא\u0004 \u0005[נתך]\u0006 זהב, פיסת מתכת, ויביא מתכת זהב השווה פחות \u0005מדינר זהב!\u0006 \u0003אמר ר' אלעזר:\u0004 משנתנו מדברת כש\u0003אמר\u0004 הנודר במפורש \"הרי עלי \u0003מטבע\u0004 זהב\". ושואלים: אף באופן זה, מדוע עליו להביא דינר זהב, \u0003ודלמא\u0004 \u0005[ושמא]\u0006 לא היתה כוונתו אלא להביא \u0003פריטי\u0004 \u0005[פרוטות]\u0006 זהב! \u0003אמר רב פפא: פריטי דדהבא\u0004 \u0005[פרוטות של זהב]\u0006 \u0003לא עבדי אינשי\u0004 \u0005[לא עושים אנשים],\u0006 ולכן ודאי לא זו היתה כוונת הנודר.","עוד שנינו במשנתנו שהאומר \"הרי עלי \u0003כסף\"\u0004 — \u0003לא יפחות\u0004 \u0003מדינר\u0004 כסף. \u0003ו\u0004שואלים: מנין לנו שכוונתו היתה למטבע כסף, \u0003דלמא\u0004 \u0005[שמא]\u0006 היתה כוונתו ל\u0003נסכא\u0004 \u0005[נתך]\u0006 כסף, ויביא כסף השווה אף פחות \u0005מדינר כסף!\u0006 \u0003אמר ר' אלעזר:\u0004 משנתנו מדברת כש\u0003אמר\u0004 הנודר במפורש \"הרי עלי \u0003מטבע\u0004 כסף\". ושואלים: אף באופן זה, מדוע עליו להביא דינר כסף, \u0003ודלמא\u0004 \u0005[ושמא]\u0006 לא היתה כוונתו אלא להביא \u0003פריטי\u0004 \u0005[פרוטות]\u0006 כסף! \u0003אמר רב ששת:\u0004 משנתנו מדברת \u0003באתרא\u0004 \u0005[במקום]\u0006 שבו \u0003לא סגו פריטי דכספא\u0004 \u0005[לא מהלכות,\u0006 מתקבלות בשוק, \u0005פרוטות של כסף].\u0006","עוד שנינו במשנתנו שהאומר \"הרי עלי \u0003נחושת\"\u0004 — \u0003לא יפחות\u0004 \u0003מ\u0004נחושת בערך \u0003מ\u0004\u0003עה כסף.\u0004 ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: לא יפחות\u0004 בכמות הנחושת שיביא \u0003מ\u0004זו שניתן לעשות ממנה \u0003צינורא\u0004 (כעין מזלג) \u0003קטנה של נחשת.\u0004 ושואלים: \u0003למאי חזיא\u0004 \u0005[למה,\u0006 לאיזו עבודה במקדש, \u0003ראויה]\u0004 הצינורא? \u0003אמר אביי: שמחטטין\u0004 (מוציאים) \u0003בה\u0004 (באמצעותה) את ה\u0003פתילות\u0004 הישנות שבמנורה, המוחלפות בחדשות, \u0003ומקנחין בה\u0004 את האפר הנתון ב\u0003נרות\u0004 (מיכלי השמן והפתילה) שבמנורה.","במשנתנו נידונו דיניהם של הנודבים ממיני המתכת: זהב, כסף ונחושת. ולא נידון בה דינו של האומר \"הרי עלי להביא \u0003ברזל\".\u0004 ובענין זה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אחרים אומרים: לא יפחות\u0004 בהבאת נדרו \u0003מ\u0004כמות כזו של ברזל, שניתן לעשות ממנה \u0003כליה עורב,\u0004 שבגג ההיכל. \u0003ו\u0004שואלים: \u0003כמה\u0004 הוא שיעורו של כליה עורב? \u0003אמר רב יוסף: אמה על אמה.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את מהלך הדברים שהובאו עתה, באופן שונה: שבברייתא שנו כי אחרים אומרים שהנודר ברזל \u0003לא יפחות מאמה על אמה\u0004 של ברזל. ועל כך נשאלה השאלה: \u0003למאי חזיא\u0004 \u0005[למה,\u0006 לאיזה שימוש במקדש, \u0003ראויה]\u0004 היא כמות זו של ברזל? ועל כך \u0003אמר רב יוסף: ל\u0004עשות ממנה \u0003כליה עורב.\u0004","נדר ואמר \u0003\"הרי עלי\u0004 להביא \u0003יין\u0004 לנסכים\", ולא פירש כמה יין — \u0003לא יפחות משלשה לוגין\u0004 של יין, שהוא השיעור הפחות שבנסכי יין, שיעור נסכי הכבש. אמר \"הרי עלי להביא \u0003שמן\"\u0004 — \u0003לא יפחות\u0004 \u0003מלוג\u0004 אחד של שמן, שהרי המנחה המועטה ביותר, מנחה של עשרון סולת, חייבת בלוג שמן. \u0003רבי אומר:\u0004 יביא \u0003שלשה לוגין\u0004 של שמן, כשיעור השמן הבא במנחת נסכים של כבש, שהוא השיעור הקטן ביותר שבמנחות הנסכים.","האומר \"נדרתי (יין או שמן), ו\u0003פירשתי\u0004 כמה לוגים אני נודר, ושכחתי כמה לוגים אמרתי, \u0003ו\u0004עתה \u0003איני יודע מה פירשתי\"\u0004 — \u0003יביא\u0004 \u0003כ\u0004מספר הלוגים המובאים ב\u0003יום\u0004 ה\u0003מרובה\u0004 ביותר במספר הלוגים המובאים בו למקדש.","שנינו במשנתנו כי הנודר להביא יין מביא לפחות שלושה לוגים יין. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא מה שנאמר בפרשת הנסכים \"כל ה\u0003אזרח\u0004 יעשה ככה להקריב אשה ריח ניחוח לה' \" (במדבר טו, יג) — \u0003מלמד שמתנדבין יין\u0004 לנסכים לעצמם, ולא רק כבאים עם קרבן. \u0003וכמה\u0004 הוא שיעור היין לנסכים אותו מתנדבים? \u0003שלשה לוגין,\u0004 כשיעור הנמוך ביותר של נסכי הקרבנות (של נסכי הכבשים).","\u0003ומנין\u0004 לנו \u0003שאם רצה להוסיף\u0004 בנדבתו על שיעור זה, ש\u0003יוסיף? תלמוד לומר\u0004 עוד בדין הנסכים \"ונסכיהם חצי ההין יהיה לפר ושלישית ההין לאיל ורביעית ההין לכבש יין...\" (שם כח, יד), ובאה לשון הריבוי \u0003\"יהיה\"\u0004 להורות שיהיו נסכים נוספים הבאים לעצמם יותר על השיעור הרגיל. ודנים עוד בברייתא: \u0003יכול\u0004 יהא הדין \u0003ש\u0004\u0003יפחות\u0004 בנדבת הנסכים אף משלושה לוגים יין? \u0003תלמוד לומר\u0004 \"כל האזרח יעשה \u0003ככה\",\u0004 להדגשה: דווקא כך, שלושה לוגים יין, ולא פחות.","עוד שנינו במשנתנו כי הנודב להביא \u0003שמן\u0004 סתם — לדעת חכמים הרי זה \u0003לא יפחות מן הלוג,\u0004 שהוא כשיעור שמן במנחת הנדבה המועטה ביותר, ואילו \u0003רבי\u0004 \u0003אומר\u0004 כי יביא \u0003שלשה לוגין,\u0004 שהוא השיעור הפחות שבנסכים. ומבררים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה יסוד \u0005הם חלוקים]?\u0006","\u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רב פפא:\u0004 חכמים ורבי חולקים בדרכי הלימוד בגזירה שווה. האם למדים \u0003ב\u0004אופן שיש ל\u0003דון מינה ומינה\u0004 \u0005[ללמוד ממנה וממנה],\u0006 כלומר, מכל פרטי הדבר המלמד לעניינו של הדבר הלמד. או \u0003ב\u0004אופן שיש ל\u0003דון מינה\u0004 \u0003ואוקים באתרה\u0004 \u0005[ללמוד ממנה\u0006 לענין הפרט בו נגזרה הגזירה, \u0005והעמד\u0006 את הדבר הלמד בשאר פרטיו \u0005במקומה]\u0006 \u0003קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 ומפרטים לענייננו:","\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כגישה העקרונית האומרת \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה],\u0006 ולכך בענייננו גם כן נאמר כי נלמדים דין נסכי השמן הבאים לעצמם מדין השמן הבא עם מנחת נדבה: \u0003מה מנחה\u0004 ובה שמן — \u0003מתנדבין, אף שמן\u0004 לעצמו — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מתנדבין. ומינה\u0004 \u0005[וממנה]\u0006 תוסיף ותלמד, \u0003מה מנחה\u0004 — שיעורה \u0003בלוג, אף שמן\u0004 לעצמו — שיעורו \u0003בלוג. ו\u0004אילו","\u0003רבי סבר\u0004 \u0005[סבור]\u0006 כגישה העקרונית האומרת \u0003דון מינה ואוקי באתרה\u0004 \u0005[למד ממנה ו\u0006אולם \u0005העמד במקומה],\u0006 ולכך בענייננו נאמר: \u0003מה מנחה\u0004 ובה שמן — \u0003מתנדבין, אף שמן\u0004 לעצמו — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מתנדבין. ו\u0004אולם באשר לשיעור נדבת השמן, \u0003אוקי באתרה\u0004 \u0005[העמד\u0006 אותה \u0005במקומה]\u0006 שיהא דינה \u0003כנסכים, מה\u0004 שיעורם של \u0003נסכים\u0004 — אינו פחות מ\u0003שלשת לוגין, אף\u0004 שיעור נדבת \u0003שמן נמי\u0004 \u0005[גם כן]\u0006 — הריהו \u0003שלשת לוגין.\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא\u0004 לחכמים שהציעו לפניו להסביר כך את מחלוקת חכמים ורבי: \u0003אי\u0004 \u0005[אם]\u0006 \u0003ממנחה גמר לה\u0004 \u0005[\u0006היה \u0005לומד אותה]\u0006 \u0003רבי,\u0004 את דין נדבת שמן לעצמו — \u0003דכולי עלמא\u0004 \u0005[כולם,\u0006 הן חכמים ואף רבי\u0005]\u0006 \u0003לא פליגי\u0004 \u0005[לא\u0006 היו \u0005חלוקים]\u0006 בדין, ולדעת הכל שיטת הלימוד היא \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה].\u0006 \u0003אלא\u0004 הסבר המחלוקת הוא שונה: \u0003רבי\u0004 את דין נדבת שמן לעצמו אינו למד ממנחה, אלא \u0003מ\u0004הכתוב \u0003\"אזרח\"\u0004 האמור בפרשת נסכים (\"כל האזרח יעשה ככה\") \u0003גמיר לה\u0004 \u0005[לומד אותה].\u0006 ומעתה, כשם שאין הנסכים באים בפחות משלושה לוגים, אף נדבת שמן הריהי בת שלושה לוגים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן לרב פפא: ומי מצית אמרת הכי\u0004 \u0005[והאם יכול אתה לומר כך]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 הכתוב \"וכי תקריב \u0003קרבן\u0004 מנחה\" — \u0003מלמד שמתנדבין שמן, וכמה\u0004 שיעורו? \u0003שלשת לוגין. מאן\u0004 \u0005[מי]\u0006 התנא ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר\u0004 ששיעורו \u0003שלשת לוגין?\u0004 — \u0003רבי, וקא מייתי לה\u0004 \u0005[והוא מביא אותה,\u0006 את מקור הלכה זו לנדבת שמן לעצמו\u0005]\u0006 \u0003מ\u0004מה שנאמר \u0003\"קרבן\u0004 מנחה\", ולא מ\"האזרח\"! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא לרב הונא בנו של רב נתן: \u0003אי תניא תניא\u0004 \u0005[אם שנויה\u0006 כך ברייתא, הריהי \u0005שנויה],\u0006 ואני חוזר בי מהסברי.","שנינו במשנתנו שהאומר \u0003\"פירשתי ואיני יודע מה\u0004 \u0003פירשתי\"\u0004 — \u0003יביא כיום\u0004 ה\u0003מרובה,\u0004 שמרובים קרבנות ציבור המובאים בו יותר מבשאר כל ימות השנה. ומביאים מה ש\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: מהו \"כיום מרובה\"? \u0003כיום טוב הראשון של חג\u0004 הסוכות \u0003שחל להיות\u0004 ביום ה\u0003ש\u0004\u0003בת,\u0004 שיש בו מלבד קרבנות המוספים של החג, אף מוספי יום השבת, וסך כל לוגי השמן המובאים באותו יום הוא מאה וארבעים.","האומר \u0003\"הרי עלי\u0004 להביא קרבן \u0003עולה\",\u0004 ולא פירש מאיזו בהמה יביא — \u0003יביא כבש\u0004 לקרבן עולה, שהוא קרבן בהמה הפחות ביותר. \u0003ר' אלעזר בן עזריה אומר:\u0004 יביא \u0003או תור או בן יונה,\u0004 לעולת העוף.","האומר \u0003\"נדרתי להביא קרבן עולה, ובשעה שנדרתי\u0004 \u0003פירשתי\u0004 שעולה זו תהיה \u0003מן הבקר,\u0004 ואף פירשתי איזה ממיני הבקר, ולאחר מכן שכחתי, \u0003ו\u0004עתה \u0003איני יודע מה\u0004 (איזה מין ממיני הבקר) \u0003פירשתי\u0004 בנדרי\" — \u0003יביא\u0004 את שני מיני זכרי הבקר, \u0003פר ועגל,\u0004 שכן אין העולה באה אלא מן הזכרים. האומר \"נדרתי להביא קרבן עולה, ובשעה שנדרתי פירשתי ש\u0003מן הבהמה\u0004 אביא בנדרי ואף פירשתי איזו בהמה תהא זו, ולאחר מכן שכחתי, \u0003ו\u0004עתה \u0003איני יודע מה\u0004 (איזו בהמה) \u0003פירשתי\u0004 בנדרי\" — \u0003יביא פר\u0004 (בן שלוש שנים) \u0003ועגל\u0004 (בן שנה), \u0003איל\u0004 (כבש זכר בן שנתיים), \u0003שעיר\u0004 (תיש בן שנתיים), \u0003גדי\u0004 (בן עיזים בתוך שנתו הראשונה), \u0003וטלה\u0004 (כבש זכר בשנתו הראשונה). האומר \"נדרתי להביא קרבן עולה, ובשעה שנדרתי \u0003פירשתי\u0004 מה אביא, ולאחר מכן שכחתי, \u0003ו\u0004עתה \u0003איני יודע מה\u0004 (איזה מין הוא, אם בהמה אם עוף) \u0003פירשתי\"\u0004 —"],["\u0003מוסיף עליהן\u0004 גם \u0003תור ובן יונה\u0004 הבאים לעולת העוף.","האומר \u0003\"הרי עלי\u0004 להביא קרבן \u0003תודה\"\u0004 או שאומר \"הרי עלי להביא קרבן \u0003שלמים\"\u0004 — \u0003יביא כבש,\u0004 שמבין הבהמות הראויות לקרבנות אלה, הוא הפחות שבהן. האומר \"נדרתי להביא לקרבן תודה (או שלמים), ובשעה שנדרתי \u0003פירשתי\u0004 איזה מין \u0003מן\u0004 ה\u0003בקר\u0004 אביא בנדרי, ולאחר מכן שכחתי, \u0003ו\u0004עתה \u0003איני יודע מה פירשתי\"\u0004 — \u0003יביא פר ופרה, עגל ועגלה,\u0004 שהרי קרבנות התודה והשלמים באים הן מהזכר והן מהנקבה. האומר \"נדרתי להביא לקרבן תודה (או לשלמים), ובשעה שנדרתי פירשתי איזו \u0003מן הבהמה\u0004 אביא בנדרי, \u0003ו\u0004עתה \u0003איני יודע מה פירשתי\"\u0004 — \u0003יביא פר ופרה,\u0004 \u0003עגל ועגלה, איל ורחלה, שעיר ושעירה, גדי וגדייה, טלה וטלייה.\u0004 שכל אלה באים בקרבן התודה או השלמים.","האומר בנדר \u0003\"הרי עלי שור\"\u0004 לקרבן עולה (או שלמים) — אף שלא אמר בנדרו אלא \"שור\", \u0003יביא הוא\u0004 (את השור לקרבן) \u0003ו\u0004מנחת \u0003נסכיו\u0004 (הסולת, השמן, היין) \u0003ב\u0004שווי \u0003מנה\u0004 (מאה דינרים). הנודר \"הרי עלי \u0003עגל\u0004 לעולה או שלמים\" — \u0003יביא הוא ונסכיו בחמש\u0004 סלעים (עשרים דינרים). \"הרי עלי \u0003איל\u0004 לקרבן\" — \u0003יביא הוא ונסכיו בשתים\u0004 סלעים (שמונה דינרים). \"הרי עלי \u0003כבש\u0004 לקרבן\" — \u0003יביא הוא ונסכיו בסלע\u0004 אחד (ארבעה דינרים).","האומר \"הרי עלי להביא \u0003שור במנה\"\u0004 (מאה דינרים) — \u0003יביא\u0004 שור \u0003ב\u0004שווי \u0003מנה, חוץ\u0004 (מלבד) \u0003מנסכיו.\u0004 \"הרי עלי להביא \u0003עגל בחמש\u0004 סלעים\" — \u0003יביא\u0004 עגל \u0003ב\u0004שווי \u0003חמש\u0004 סלעים, \u0003חוץ מנסכיו.\u0004 \"הרי עלי להביא \u0003איל בשתים\u0004 סלעים\" — \u0003יביא\u0004 איל \u0003ב\u0004שווי \u0003שתים\u0004 סלעים, \u0003חוץ מנסכיו.\u0004 \"הרי עלי להביא \u0003כבש בסלע\u0004 אחד\" — \u0003יביא\u0004 כבש \u0003ב\u0004שווי \u0003סלע\u0004 אחד, \u0003חוץ מנסכיו.\u0004","\"הרי עלי להביא \u0003שור במנה\", והביא שנים\u0004 שוורים ששניהם יחד \u0003ב\u0004שווי \u0003מנה\u0004 — \u0003לא יצא\u0004 ידי נדרו בכך, שנדר. \u0003ואפילו\u0004 היו אלה שני שוורים גדולים, ובאופן ש\u0003זה\u0004 השור האחד הריהו \u0003ב\u0004שווי \u0003מנה חסר דינר\u0004 (תשעים ותשעה דינרים), \u0003ו\u0004כן \u0003זה\u0004 השור השני הריהו \u0003ב\u0004שווי \u0003מנה חסר דינר.\u0004","אמר \"הרי עלי להביא שור \u0003שחור\" והביא\u0004 שור \u0003לבן,\u0004 או שאמר \"הרי עלי להביא שור \u0003לבן\" והביא\u0004 שור \u0003שחור,\u0004 או שאמר \"הרי עלי להביא שור \u0003גדול\" והביא\u0004 שור \u0003קטן\u0004 — בכל האופנים הללו \u0003לא יצא\u0004 ידי נדרו, שהרי לא הביא כפי שנדר. האומר \"הרי עלי להביא שור \u0003קטן\" והביא\u0004 שור \u0003גדול\u0004 — \u0003יצא\u0004 ידי נדרו, שכן בכלל שוויו של שור גדול יש שוויו של שור קטן. \u0003רבי אומר: לא יצא\u0004 ידי נדרו, שהרי לא הביא כפי שנדר.","שנינו במשנתנו שהנודר להביא קרבן עולה ולא פירש ממה יביא, לדעת חכמים הריהו מביא כבש, שהוא הפחות שבעולות בהמה, ואילו לדעת ר' אלעזר בן עזריה הריהו מביא תור או בן יונה, לעולת העוף. ומסבירים: \u0003ולא פליגי\u0004 \u0005[ולא נחלקו]\u0006 בעיקרה של הלכה, אלא \u0003מר כי אתריה ומר כי אתריה\u0004 \u0005[חכם זה\u0006 אמר את דינו \u0005על פי\u0006 המקובל ב\u0005מקומו, וחכם זה\u0006 אמר את דינו \u0005על פי\u0006 המקובל ב\u0005מקומו].\u0006 שבמקומם של חכמים לא היו קוראים \"עולה\" בסתם אלא לעולת בהמה. ואילו במקומו של ר' אלעזר בן עזריה, היו קוראים \"עולה\" בסתם אף לעולת העוף.","שנינו במשנתנו שלדעת חכמים, הנודר קרבן עולה מביא כבש. ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: האומר \u0003\"הרי עלי\u0004 להביא \u0003עולה ב\u0004שווי \u0003סלע למזבח\"\u0004 — \u0003יביא כבש.\u0004 וטעם הדבר: \u0003שאין לך דבר שקרב ב\u0004שווי \u0003סלע לגבי מזבח אלא כבש.\u0004 האומר \"בשעת נדרי, דבר \u0003שקרב בסלע פירשתי,\u0004 ולאחר מכן שכחתי, \u0003ו\u0004עתה \u0003איני יודע מה פירשתי\"\u0004 — \u0003יביא מכל דבר שקרב בסלע לגבי מזבח.\u0004 ובלבד שיהא זה דבר שלם, הקרב כפי שהוא.","שנינו במשנתנו שהאומר \u0003\"פירשתי\u0004 בנדרי שאביא \u0003מן הבקר\u0004 וציינתי איזו בהמה מן הבקר ואחר כך שכחתי \u0003ואיני יודע מה פירשתי\"\u0004 — \u0003יביא פר ועגל.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הריהו חייב גם בהבאת עגל, \u0003וליתי\u0004 \u0005[ושיביא]\u0006 רק \u0003פר,\u0004 ו\u0003ממה נפשך\u0004 (לכל אופן שתרצה) יועיל הדבר. שהרי אם פר נדר — הרי הביא פר, כנדרו. ואם עגל נדר — הרי עגל בכלל פר, שהקטן הריהו כלול בגדול!","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003רבי היא,\u0004 ש\u0003אמר\u0004 שהנודר להביא שור \u0003קטן והביא\u0004 שור \u0003גדול\u0004 — \u0003לא יצא\u0004 בכך ידי נדרו, אלא אם יביא פר ועגל.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 משנתנו כשיטת \u0003רבי\u0004 היא, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את מה ששנינו ב\u0005סוף\u0006 המשנה\u0005]\u0006 שהנודר להביא \u0003שור ב\u0004שווי \u0003מנה,\u0004 \u0003והביא שנים\u0004 שוורים \u0003ב\u0004שווי \u0003מנה\u0004 גם יחד — \u0003לא יצא\u0004 ידי נדרו. \u0003ואפילו\u0004 הביא שני שוורים ושור \u0003זה,\u0004 אחד מהם \u0003ב\u0004שווי \u0003מנה חסר דינר ו\u0004שור \u0003זה\u0004 האחר \u0003ב\u0004שווי \u0003מנה חסר דינר,\u0004 או שנדר להביא שור","\u0003שחור והביא\u0004 שור \u0003לבן,\u0004 או שנדר להביא שור \u0003לבן והביא\u0004 שור \u0003שחור,\u0004 או שנדר להביא שור \u0003גדול והביא\u0004 שור \u0003קטן\u0004 — בכל אלה \u0003לא יצא\u0004 ידי חובת נדרו. הנודר להביא שור \u0003קטן והביא\u0004 שור \u0003גדול\u0004 — לדעת חכמים \u0003יצא\u0004 בכך ידי נדרו, \u0003רבי\u0004 \u0003אומר: לא יצא\u0004 ידי נדרו.","אם כן נמצא לפי שיטתך ש\u0003רישא\u0004 \u0005[תחילת\u0006 המשנה\u0005]\u0006 בדין \"פירשתי מן הבקר ואיני יודע מה פירשתי\", שמביא פר ועגל הריהי כשיטת רבי, \u0003ו\u0004כן \u0003סיפא\u0004 \u0005[סוף]\u0006 המשנה בנודר שור קטן והביא שור גדול, שלא יצא בכך ידי נדרו היא שיטת \u0003רבי\u0004 (כנאמר במפורש לפנינו), \u0003ו\u0004אילו \u0003מציעתא\u0004 \u0005[אמצע]\u0006 המשנה, בכל הדינים, הריהי כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על רבי?","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 של המשנה הם כשיטת \u0003רבי,\u0004 ואילו \u0003מציעתא\u0004 \u0005[אמצע]\u0006 המשנה היא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך הוא\u0006 התנא מתכוון \u0005לומר]:\u0006 \u0003דבר זה\u0004 שנוי ב\u0003מחלוקת רבי ורבנן\u0004 \u0005[וחכמים].\u0006","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה במסכת שקלים\u0005]:\u0006 \u0003ששה\u0004 שופרות (קופות שצורתן כעין שופר) היו במקדש \u0003ל\u0004צורך נתינת כספי ה\u0003נדבה,\u0004 שבהם היו קונים קרבנות להקרבה בזמנים שהמזבח בטל מהקרבה. ומבררים: \u0003כנגד מי\u0004 התקינו להעמיד ששה שופרות אלה? \u0003(סימן\u0004 לזכירת שמות החכמים שיוזכרו להלן במהלך הסוגיה: \u0003קמ\"ף ש\"ע).\u0004","\u0003אמר חזקיה: כנגד ששה בתי אבות הכהנים\u0004 שבכל משמר כהנים. שכל משמר כהנים היה עובד שבוע, ובכל יום מימות השבוע היה עובד אחד מבתי האב שלו, וביום השבת היו עובדים כולם כאחד. \u0003שתקנו להם חכמים\u0004 ששה שופרות כדי \u0003שיהא שלום זה עם זה.\u0004 שכן עורו של הקרבן הקרב מהכסף הנתון בשופר ניתן לכהני בית האב שהקריבוהו, ואם היה רק שופר אחד, נמצא כי כאשר נטלו ממנו ביום אחד בשבוע (וכגון באופן שהיה המזבח בטל רק באותו יום), היו נהנים מהעורות רק בית האב שהקריב באותו היום, והיו שאר בתי האב באים להתקוטט איתם. ולכך תיקנו שיהיו ששה שופרות, וכל הנדרים והנדבות היו מתחלקים בין השופרות בשווה, וכך כל בית אב היה נוטל להקרבה רק משופרו.","\u0003ר' יוחנן אמר\u0004 הסבר אחר לתקנתם של ששה שופרות אלה: \u0003מתוך שהנדבה מרובה\u0004 היא, שנדרו הרבה מעות, לכך \u0003תיקנו להם שופרות מרובין, כדי שלא\u0004 יהיו כל המעות הללו מונחים בצפיפות באותו שופר וכך \u0003יתעפשו המעות.\u0004","\u0003וזעירי אמר\u0004 הסבר אחר: התקינו ששה שופרות \u0003כנגד\u0004 ששת מיני הבהמה הקרבים לעולה, שהם: \u0003פר ועגל, איל וכבש, גדי ושעיר,\u0004 ולדמי כל אחד מן הבהמות הללו היה שופר נפרד. \u0003ו\u0004מה שלא הסתפקו בשופרות לקרבנות גדולים ולקרבנות קטנים — כשיטת \u0003רבי היא,\u0004 ש\u0003אמר:\u0004 הנודר להביא שור \u0003קטן והביא גדול\u0004 — \u0003לא יצא,\u0004 שהרי לא הביא כפי שנדר, ולכן צריך לעשות לכל אחד שופר בפני עצמו, שיתן בו דמים לצורך הקרבן שנדר.","\u0003ובר פדא אמר\u0004 הסבר אחר: הותקנו ששה שופרות \u0003כנגד\u0004 קרבנות ציבור שאבדו, והופרשו אחרים תחתיהם, ולאחר מכן נמצאו הראשונים שאבדו, שדמי \u0003הפרים\u0004 (של חטאות ציבור) הללו — ינתנו לשופר ראשון. \u0003ו\u0004דמי \u0003האילים\u0004 (של אשם גזילות ואשם מעילות) — ינתנו לשופר שני."],["\u0003ו\u0004דמי \u0003הכבשים\u0004 (אשם נזיר ואשם מצורע הניתנים לנדבה) — ינתנו לשופר שלישי. \u0003ו\u0004דמי \u0003השעירים\u0004 של חטאות ציבור של רגלים (המכפרים על טומאת מקדש וקדשיו) — ינתנו לשופר רביעי. \u0003ו\u0004דמי \u0003המותרות\u0004 (שהפריש אדם מעות לצורך הקרבת אחד הקרבנות הללו, ולאחר שנקנה הקרבן נותרו בידו מעות) — הריהם ניתנים לשופר חמישי. \u0003והמעה\u0004 (שמביאים שנים שהשתתפו במחצית השקל, והביאו שניהם שקל אחד) — תינתן לשופר הששי.","ולאחר שהובאו ארבעה הסברים שונים בטעם תקנת ששת השופרות במקדש, מסבירים: \u0003כולהו\u0004 \u0005[כולם,\u0006 שאר החכמים\u0005]\u0006 \u0003כ\u0004הסברו של \u0003חזקיה\u0004 (שששת השופרות נועדו למניעת קטטה בין בתי האב השונים של משמר הכהנים) \u0003לא אמרי\u0004 \u0005[אינם אומרים]\u0006 — שכן \u0003ל\u0004חשש זה של \u0003אנצויי\u0004 \u0005[מריבה]\u0006 בין כהנים \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שמוסכם הוא על כל הכהנים ש\u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מבתי האב של הכהנים את עבודת \u0003יומיה קא עביד\u0004 \u0005[יומו הוא עושה]\u0006 ומקבל לפי זה את עורות העולה שקרבו באותו יום\u0005. וכמו כן, שאר החכמים\u0006","\u0003כ\u0004הסברו של \u0003ר' יוחנן\u0004 (שששת השופרות נועדו למניעת עיפוש המעות) \u0003לא אמרי\u0004 \u0005[אינם אומרים]\u0006 — שכן \u0003ל\u0004חשש זה של \u0003איעפושי\u0004 \u0005[עיפוש]\u0006 \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","וכמו כן, כל שאר החכמים \u0003כ\u0004הסברו של \u0003זעירי\u0004 (שששת השופרות הותקנו כנגד ששת מיני בהמה שנודב אדם לעולה ומוסרה לקיץ המזבח, ולא הסתפקו בשלושה שופרות, שלושה לקרבנות הגדולים ושלושה לקרבנות הקטנים, משום שזעירי סבור כשיטת רבי \u0003לא אמרי\u0004 \u0005[אינם אומרים]\u0006 — שכן \u0003כיחידאה לא מוקמי\u0004 \u0005[כ\u0006שיטת \u0005יחיד,\u0006 רבי, \u0005אינם מעמידים]\u0006 את טעמה של תקנת חכמים זו.","וכמו כן, כל שאר החכמים \u0003כ\u0004הסברו של \u0003בר פדא\u0004 (שששת השופרות נועדו לדמי פרים, אילים, כבשים ושעירים שאבדו ונמצאו לאחר שהוקרב תחתיהם, ולדמי מותרות ועבור המעה) \u0003נמי לא אמרי\u0004 \u0005[גם כן אינם אומרים]\u0006 — \u0005משום שאין להפריד בין ארבעת הבהמות הללו ולהניח את מעותיהן בשופרות נפרדים ובין\u0006 \u0003מותרות\u0004 (שניתן להם שופר אחד), שהרי \u0003כולהו נמי\u0004 \u0005[כולם,\u0006 כל אלה, \u0005גם כן]\u0006 הריהם בכלל \u0003מותרות,\u0004 שהרי נותרו, לאחר שהוקרב תחתם קרבן אחר, ונמצאו אלה.","וגם למה שאמר שהשופר הששי נועד למעה (ההולכת, כשאר הדמים שבששת השופרות, לעולות הנדבה), אין שאר החכמים מודים לו, שכן לדעתם \u0003מעה נמי\u0004 \u0005[גם כן]\u0006 \u0003לשקלים אזלא\u0004 \u0005[הולכת].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003להיכן קלבון\u0004 (כינויה של מעה זו) \u0003זה הולך?\u0004 — \u0003לשקלים,\u0004 אלו \u0003דברי ר' מאיר. ר' אליעזר אומר: לנדבה.\u0004","\u0003ו\u0004לאחר שהובאו ונידונו הסבריהם של ארבעה חכמים בטעם התקנת ששת השופרות במקדש, למעות הניתנות לעולות נדבה, מביאים הסברים נוספים. \u0003שמואל אמר:\u0004 ששת השופרות הללו הם \u0003כנגד\u0004 ששה מותרות (הכסף הנותר בידו של המפריש מעות לקניות קרבנות, לאחר שנקנו) אלה: בזבחים — \u0003מותר\u0004 קרבן \u0003חטאת, ומותר\u0004 קרבן \u0003אשם\u0004 (אשם גזילות ואשם מעילות), \u0003ומותר\u0004 קרבן \u0003אשם נזיר\u0004 (שמביא הנזיר שנטמא במת בתוך ימי נזירותו), \u0003ומותר\u0004 קרבן \u0003אשם\u0004 שמביא \u0003ה\u0004\u0003מצורע\u0004 לאחר שנרפא מצרעתו ונטהר. \u0003ו\u0004במנחות — \u0003מותר מנחת חוטא\u0004 (שמביא החוטא בשבועת העדות או בשבועת ביטוי או בטומאת מקדש וקדשיו, אם דל הוא), \u0003ומותר\u0004 מנחת \u0003עשירית האיפה של כהן גדול\u0004 (הנקראת \"מנחת כהן משיח\" או \"מנחת חביתין\", הקרבה כל יום, ויש בה עשירית האיפה סולת, מחציתה קרבה בבוקר ומחציתה קרבה בערב).","\u0003ור' אושעיא אמר:\u0004 טעם התקנת ששת השופרות הללו, ארבעה \u0003כנגד\u0004 ארבעת מותרות זבחים, \u0003מותר חטאת, ומותר אשם, ומותר אשם נזיר, ומותר אשם מצורע.\u0004 \u0003ו\u0004אחד נוסף כנגד \u0003מותר קינין\u0004 (שתי תורים או שני בני יונה הבאים לקרבנות העוף של יולדת, הזב הנטהר מזובו, ועוד), ושלא כדברי שמואל. \u0003ו\u0004אחד כנגד \u0003מותר מנחת חוטא,\u0004 וכשיטת שמואל.","ושואלים: \u0003שמואל מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' אושעיא\u0004 המונה שופר כנגד קינים? ומשיבים: ששת השופרות הללו נועדו לעולות נדבה, ואילו מותר ה\u0003קינין\u0004 כבר \u0003תנא ליה רישא\u0004 \u0005[שנה אותו\u0006 התנא \u0005במסכת שקלים\u0006 \u0005בראש]\u0006 המשנה, בין שבעת השופרות המנויים שם (שכן בסך הכל היו שלושה עשר שופרות במקדש), ולא היו לנדבה.","\u0003ו\u0004שואלים עתה לשיטת \u0003ר' אושעיא:\u0004 והאם הוא מונה בין ששת השופרות לנדבה את הקינים, משום שהוא אכן \u0003תני\u0004 \u0005[שונה]\u0006 את המשנה בשקלים, \u0003ולא תני\u0004 \u0005[ו\u0006אולם \u0005אינו שונה]\u0006 את הנאמר בה בתחילת \u0003קינין?! והתני\u0004 \u0005[והרי שונה]\u0006 \u0003ר' אושעיא\u0004 את המשנה הזו במפורש, \u0003ותני\u0004 \u0005[ושונה]\u0006 הוא בה בתחילתה \u0003קינין!\u0004 ומשיבים: אף שנמנו הקינים בתחילת המשנה בין שבעת השופרות שהיו במקדש, חזרו ונמנו אף בין ששת השופרות לנדבה, \u0003חד\u0004 \u0005[אחד]\u0006 — נזכר \u0003לקינין\u0004 עצמם, \u0003וחד\u0004 \u0005[ואחד]\u0006 — נזכר \u0003למותר קינין.\u0004","ושואלים לצד האחר: \u0003ור' אושעיא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כשמואל\u0004 המונה שופר למותר עשירית האיפה של כהן גדול? ומשיבים: \u0003סבר לה כמאן דאמר\u0004 \u0005[סבור הוא\u0006 ר' אושעיא \u0005כמי שאומר]\u0006 ש\u0003מותר של עשירית האיפה של כהן גדול\u0004 אינו בא כעולת נדבה אלא \u0003ירקב. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מותר מנחת\u0004 — \u0003נדבה, מותר מנחה\u0004 — \u0003ירקב.\u0004","ועל התמיהה בנוסח לשון הברייתא \u0003מאי קאמר\u0004 \u0005[מה הוא אומר],\u0006 \u0003אמר רב חסדא: הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונתו\u0005]:\u0006 \u0003מותר מנחת חוטא\u0004 — הריהי ל\u0003נדבה, מותר עשירית האיפה של כהן גדול\u0004 — \u0003ירקב.\u0004","\u0003רבה אמר:\u0004 יש לפרש את דברי הברייתא באופן שונה: \u0003אפילו מותר עשירית האיפה של כהן גדול\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 הריהו ל\u0003נדבה, אלא מותר לחמי תודה\u0004 — \u0003ירקב.\u0004","ומעירים: רב חסדא ורבה \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של אמוראים ראשונים נחלקו. שכך למדנו: \u0003מותר עשירית האיפה של כהן גדול,\u0004 מה דינו? \u0003ר' יוחנן אמר: נדבה, ר' אלעזר אמר: ירקב.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת הסוברים שמותר עשירית האיפה של כהן גדול ירקב, ממה ששנינו: \u0003מותר\u0004 ה\u0003שקלים\u0004 — הריהו \u0003חולין, ו\u0004אילו \u0003מותר עשירית האיפה ומותר קיני זבין וקיני זבות וקיני יולדות וחטאות ואשמות\u0004 — כל אלה \u0003מותריהן נדבה.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 כוונת האמור \"מותר עשירית האיפה\" — \u0003מותר עשירית האיפה של כהן גדול,\u0004 שהוא הולך לנדבה!","ודוחים: \u0003לא,\u0004 הכוונה ל\u0003מותר מנחת חוטא,\u0004 שאף היא באה עשירית האיפה סולת (\u0003ויקרא ה, יא).\u0004","\u0003אמר רב נחמן בר רב יצחק, מסתברא\u0004 \u0005[מסתבר]\u0006 לומר \u0003כמאן דאמר\u0004 \u0005[כ\u0006שיטת \u0005מי שאומר]\u0006 שדין \u0003מותר עשירית האיפה של כהן גדול\u0004 ש\u0003ירקב.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 על האמור במנחת חוטא \u0003\"לא ישים עליה שמן ולא יתן עליה לבנה כי חטאת היא\"\u0004 (שם), \u0003אמר ר' יהודה:\u0004 לשון מיעוט זו (\"חטאת היא\"), באה ללמד כי דווקא \u0003היא קרויה \"\u0004\u0003חטאת\"\u0004 (ומשום כך, אין היא טעונה הבאת לבונה, כדין קרבן החטאת שאינו טעון לבונה), \u0003ואין\u0004 מנחה \u0003אחרת\u0004 ה\u0003קרויה \"\u0004\u0003חטאת\".\u0004 ומכאן \u0003לימד\u0004 הכתוב \u0003על\u0004 מנחת \u0003עשירית האיפה של כהן גדול\u0004 — \u0003שאינה קרויה \"\u0004\u0003חטאת\", ו\u0004לכך הריהי \u0003טעונה לבונה. ו\u0004מכאן אף נסיק, כי מאחר שמנחת עשירית האיפה של כהן גדול","\u0003אינה קרויה \"\u0004\u0003חטאת\"\u0004 — אין דין \u0003מותרה\u0004 כדין \u0003מותר החטאת ההולך לנדבה, אלא הריהו\u0004 \u0003ירקב.\u0004","נדב להקדש ואמר \u0003\"שור זה עולה\", ו\u0004לאחר מכן \u0003נסתאב\u0004 (נפל בו מום), ונפסל להקרבה — הריהו פודה את השור, ומביא בדמיו שור אחר לקרבן. ו\u0003אם רצה\u0004 — \u0003יביא בדמיו שנים\u0004 שוורים. וכן אם אמר בהקדשו \u0003\"שני שוורים אלו עולה\", ו\u0004לאחר מכן \u0003נסתאבו\u0004 השוורים, ופדה אותם — אם \u0003רצה יביא בדמיהן\u0004 שור \u0003אחד.\u0004 אלו דברי חכמים, \u0003ו\u0004אילו \u0003רבי אוסר\u0004 להביא שור אחד, אלא יביא שני שוורים.","\u0003אמר בהקדשו\u0004 \u0003\"איל זה עולה\", ונסתאב\u0004 האיל, ונפדה בדמים — \u0003אם רצה יביא בדמיו כבש.\u0004 וכן אם אמר בהקדשו \u0003\"כבש זה עולה\", ונסתאב,\u0004 ונפדה בדמים — \u0003אם רצה יביא בדמיו איל.\u0004 אלו דברי חכמים, \u0003ו\u0004אילו \u0003רבי אוסר\u0004 להביא בדמי הקרבן שנפדה קרבן ממין אחר."],["שנינו במשנתנו כי אם אמר \"שור זה לעולה\", ולאחר מכן נפל מום בשור, ונפדה — אם רצה יביא בדמיו שני שוורים. ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת רישא\u0004 \u0005[בתחילה,\u0006 במשנה הקודמת\u0005]\u0006 שה\u0003אומר \"הרי עלי להביא\u0004 \u0003שור ב\u0004שווי \u0003מנה\", והביא\u0004 במקום שור אחד השווה מנה, \u0003שנים\u0004 שוורים \u0003ב\u0004שווי \u0003מנה\u0004 — \u0003לא יצא\u0004 בכך ידי חובתו. ומדוע בענייננו יכול להביא שני שוורים במקום שור אחד, שנדב?","ומשיבים: אין הדברים שווים. שכן המשנה הקודמת עוסקת באופן שאמר \"הרי עלי שור\", שהוא לשון נדר, ולכן חייב להביא כפי שנדר. ואולם משנתנו עוסקת באופן שאמר \u0003\"שור זה\u0004 עולה\", והרי זו לשון נדבה, \u0003ו\u0004לכך אחר ש\u0003נסתאב\u0004 השור, ונפסל להקרבה \u0003שאני\u0004 \u0005[שונה]\u0006 הוא הדין, שהרי לא נתחייב להביא אלא שור זה לעולה, ומכיון שאינו יכול להביאו אלא את דמיו הריהו יכול להביא בדמים אלו שני שוורים.","עוד שנינו במשנתנו שהאומר \u0003\"שני שוורין אלו עולה\" ונסתאבו,\u0004 ונפדו בדמים, שלדעת חכמים אם \u0003רצה,\u0004 יכול הוא ש\u0003יביא בדמיהן\u0004 שור \u0003אחד, ו\u0004אילו \u0003רבי אוסר\u0004 להביא בדמיהם שור אחד, אלא יביא שני שוורים. ושואלים על שיטת רבי: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אינו מביא אלא שור אחד?","\u0003משום דהוה ליה\u0004 \u0005[שהרי זה]\u0006 כמו הנודר להביא שור \u0003גדול והביא\u0004 שור \u0003קטן,\u0004 וכן להיפך, שנדר להביא שור קטן והביא שור גדול, שלדעת רבי לא יצא, כיון שהביא שלא כפי שנדר. ואף כאן שני שוורים נחשבים כ\"גדול\" בהשוואה לשור אחד הנחשב \"קטן\". \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 שמשנתנו מדברת לא בנודר אלא בנודב את השוורים המסויימים הללו וקרבנו \u0003נסתאב,\u0004 ומעתה שוב אין המקדיש חייב אלא בהבאת דמי פדיונם — בכל זאת \u0003לכתחילה לא שרי\u0004 \u0005[לא התיר]\u0006 \u0003רבי\u0004 להביא שור אחד בדמיהם.","\u0003ו\u0004יש לשאול, אם כן \u0003לפלוג\u0004 \u0005[שיחלוק]\u0006 רבי על חכמים \u0003נמי ברישא\u0004 \u0005[גם כן בתחילת\u0006 המשנה\u0005],\u0006 בדינו של האומר \"שור זה עולה\" שאמרו חכמים שאם נסתאב יכול להביא בדמיו שני שוורים, שכן לדעתם אין דינו שונה מזה שנדר להביא \"שור קטן\" והביא \"שור גדול\", שהם סבורים שיצא ידי חובתו. ואולם רבי (כמובא לעיל מנחות קז,ב) חלוק על שיטתם ולדעתו אין מביאים שור גדול בנדרו של האומר שור קטן, ויחלוק אם כן בענין \"שור זה עולה\"!","ומשיב \u0005ים: אכן\u0006 \u0003רבי אכולה מילתא פליג\u0004 \u0005[על כל הדבר חלק],\u0006 ואף במקרה שבתחילת המשנה, באומר \"שור זה עולה\" הריהו סבור שלא יביא שני שוורים בדמי השור שנדב. \u0003ו\u0004מה שלא אמר רבי את דעתו זו כבר בתחילת המשנה — שכן הוא \u0003נטר להו לרבנן\u0004 \u0005[המתין להם לחכמים]\u0006 \u0003עד דמסקי מילתייהו\u0004 \u0005[שיגמרו\u0006 את \u0005דבריהם],\u0006 \u0003והדר מיפליג עלייהו\u0004 \u0005[וחזר\u0006 ו\u0005חלק עליהם]\u0006 בשני המקרים.","\u0003תדע\u0004 שכן הוא הדין לדעת רבי, \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 בסוף משנתנו\u0005]\u0006 שלדעת חכמים האומר \u0003\"איל זה עולה\" ונסתאב\u0004 — אם \u0003רצה יביא בדמיו כבש,\u0004 ואף שהאיל נחשב \"גדול\" בהשוואה לכבש. וכן שהאומר \u0003\"כבש זה לעולה\" ונסתאב\u0004 — אם \u0003רצה יביא בדמיו איל.\u0004 שכך הוא הדין לדעת חכמים, שבין כשנדר \"גדול\" (איל) רשאי להביא \"קטן\" (כבש), ובין כשנדר \"קטן\" (כבש) רשאי להביא \"גדול\" (איל). \u0003ו\u0004אילו \u0003רבי אוסר\u0004 להביא כבש בדמיו של הנודר איל — הרי איפוא שרבי סבור שאף במקרה של המקדיש בלשון \"הרי זה\", ונפסל הקרבן, אין מביאים בדמי פדיונו אלא כפי שנדר, ואף לא קרבן \"גדול\" במקום קרבן \"קטן\" שנדב. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי כך היא שיטתו של רבי.","שנינו במשנתנו שהנודב בלשון \"שור זה עולה\" ונסתאב השור לאחר מכן, שלדעת חכמים הריהו יכול להביא בדמיו גם שני שוורים. ובענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003ממינא למינא\u0004 \u0005[ממין\u0006 אחד \u0005למין\u0006 אחר\u0005]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 דינו? האם כשהתירו חכמים להביא בדמיו אף שלא כפי שנדר, התירו אף לשנות את מין הבהמה, וכגון שיביא שני אילים במקום שור אחד, אם שווים דמיהם לדמי השור?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו בברייתא: האומר \u0003\"שור זה עולה\", ונסתאב\u0004 — \u0003לא יביא בדמיו איל,\u0004 שהרי אין שוויו של האיל כשווי דמי השור, \u0003אבל\u0004 אם רוצה, הריהו \u0003מביא בדמיו\u0004 של השור \u0003שני אילים\u0004 אם שווים כדמי השור. \u0003ו\u0004אילו \u0003רבי אוסר\u0004 להביא שני אילים בדמי שור זה, וטעמו: שהרי מביא שני האילים חייב להביא אתם שני מנחות נסכים, ואלה באות בשני כלים, ולא בכלי אחד \u0003לפי שאין בילה\u0004 (בלילה). ומעתה, אין הקרבנות המובאים דומים לקרבן אותו הוא נדב, שהרי הוא נדב קרבן שמנחתו מובאת בכלי אחד, ואילו עתה מובאים בדמי קרבן זה שני קרבנות שעמהם שתי מנחות. נמצא איפוא, שלדעת חכמים הריהו רשאי לשנות ממין למין, ולהביא שני אילים במקומו של שור זה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא הדין לדעת חכמים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, שרשאי להביא בדמי שור זה אף ממין אחר, \u0003מאי איריא תרי\u0004 \u0005[מה שייך שנים],\u0006 מדוע אמרה הברייתא שרק שני אילים הוא יכול להביא בדמי השור, ואילו איל אחד אינו יכול להביא, והרי \u0003אפילו\u0004 איל \u0003חד נמי\u0004 \u0005[אחד גם כן]\u0006 צריך להיות מותר להביא, הגם שהוא \"קטן\" בהשוואה לשור שהוא \"גדול\", \u0003דהא\u0004 \u0005[שהרי]\u0006 שנינו במשנתנו \u0003ב\u0004דינו של הנודב שור זה ו\u0003נסתאב\u0004 כי \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא שני להו\u0004 \u0005[לא שונה להם]\u0006 הדין \u0003בין\u0004 המביא \u0003גדול ל\u0004מביא \u0003קטן\u0004 (שהרי הנודב איל, רשאי להביא בדמיו כבש)!","ומשיבים: \u0003תרי\u0004 \u0005[שתי]\u0006 דעות שונות של \u0003תנאי\u0004 \u0005[שוני המשניות]\u0006 בענין זה, \u0003ו\u0004חלוקות הן \u0003אליבא דרבנן\u0004 \u0005[לשיטת חכמים].\u0006 שיש אומרים כי דעת חכמים היא שבמקרה זה מותר להביא אף קטן במקום גדול (כבמשנתנו), ויש האומרים בדעת חכמים כי אף במקרה זה אין להביא קטן במקום גדול (כבברייתא).","שנינו באותה ברייתא כי \u0003רבי אוסר\u0004 להביא שני אילים בדמי השור שנפדה, וטעמו: \u0003לפי שאין בילה.\u0004 ומדייקים בדבריו: כל עיקר \u0003טעמא\u0004 \u0005[הטעם]\u0006 הוא מפני ש\u0003אין בילה,\u0004 ומכאן יש לדייק: \u0003הא\u0004 \u0005[הרי]\u0006 שאם \u0003יש בילה\u0004 — \u0003שרי\u0004 \u0005[מותר]\u0006 היה לשיטת רבי להביא שני אילים במקום שור זה שנפסל\u0005,\u0006","\u0003ו\u0004אולם \u0003התנן\u0004 \u0005[הרי שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0005האומר\u0006 \u0003\"איל זה עולה\" ונסתאב\u0004 האיל — לדעת חכמים אם \u0003רצה יביא בדמיו כבש.\u0004 וכן שהאומר \u0003\"כבש זה עולה\" ונסתאב\u0004 — אם רצה \u0003יביא בדמיו איל, ו\u0004אילו \u0003רבי אוסר\u0004 להביא כן. הרי משמע שאוסר רבי להביא בשינוי ממה שנדר, אף בקרבן אחד, ואף מקטן לגדול, הגם שאין הוא מביא אלא מנחה אחת!","ומשיבים: אף בשיטת רבי ישנם \u0003תרי תנאי\u0004 \u0005[שני שוני משניות]\u0006 \u0003ו\u0004חלוקים הם \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003רבי.\u0004 שיש האומרים כי רבי אוסר רק שינוי קרבן שיש אתו שינוי במנחות (כבברייתא), ויש האומרים שרבי אוסר בכל שינוי, וגם זה שאין עמו שינוי במנחות (כבמשנתנו).","ומביאים את הנאמר בסופה של אותה ברייתא: הדברים שהובאו בתחילתה עוסקים בנדבת קרבן שנפל בו מום, והריהו נפדה, ובדמיו מביאים קרבן אחר. \u0003ו\u0004אולם \u0003בטהורים\u0004 (קרבנות שאין בהם מום, שאינם נפדים), אם נדר להביא \u0003עגל, והביא\u0004 במקומו \u0003פר,\u0004 או שנדר להביא \u0003כבש, והביא\u0004 במקומו \u0003איל\u0004 — \u0003יצא.\u0004 ומסבירים: \u0003סתמא\u0004 \u0005[סתם,\u0006 שלא נאמר \u0003שם אומר הדברים\u0004\u0005],\u0006 דברי הברייתא הללו, שיכול להביא קרבן גדול במקום קרבן קטן שאמר, הריהם \u0003כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 החלוקים בכך על רבי.","במשנתנו שנינו שהאומר \"שור זה עולה\", ונסתאב ונפדה בדמים, שאם \u0003רצה\u0004 יכול ש\u0003יביא בדמיו\u0004 \u0003שנים\u0004 שוורים. ובהסבר דין זה \u0003אמר רב מנשיא בר זביד, אמר רב: לא שנו\u0004 הלכה זו \u0003אלא\u0004 בזמן ש\u0003אמר \"שור זה עולה\",\u0004 שלא הוקדש אלא שור זה, ומשנפסל שור זה — אין המקדיש חייב אלא בדמיו, ולכך יכול להביא בהם שני שוורים. \u0003אבל\u0004 אם \u0003אמר \"שור זה עלי עולה\"\u0004 — \u0003הוקבע\u0004 אחריותו עליו, לענין זה שחובה עליו להביא עולה אחת (כשור גדול), ולא שתי עולות (בשני שוורים).","ושואלים על דבריו: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 במה שאמר \"עלי\", \u0003\"עלי להביאו\"\u0004 לשור זה למקדש \u0003קאמר\u0004 \u0005[הוא אומר,\u0006 מתכוון לומר\u0005],\u0006 ואין בכלל דבריו קבלת אחריות!","\u0003אלא אי איתמר\u0004 \u0005[אם נאמרה]\u0006 הלכה זו, \u0003הכי איתמר\u0004 \u0005[כך\u0006 היא \u0005נאמרה],\u0006 וזה נוסחה: \u0003אמר רב מנשיא בר זביד, אמר רב: לא שנו\u0004 במשנתנו שיכול להביא שני שוורים בדמיו של שור זה, \u0003אלא\u0004 בזמן ש\u0003אמר\u0004 המקדיש \u0003\"שור זה עולה\",\u0004 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפילו אם \u0003אמר \"שור זה עלי עולה\", אבל\u0004 אם \u0003אמר\u0004 \u0003\"שור זה ודמיו עלי עולה\"\u0004 — \u0003הוקבע\u0004 אחריותו עליו דווקא בשור אחד, ולא בשני שוורים.","\u0003ה\u0004מקדיש לקרבן, ו\u0003אומר \"אחד מכבשי\u0004 יהיה ל\u0003הקדש\"\u0004 או \u0003\"אחד\u0004 \u0003משורי\u0004 יהיה \u0003ל\u0004\u0003הקדש\", והיו לו שנים\u0004 (כבשים או שוורים) — \u0003הגדול שבהן\u0004 ינתן ל\u0003הקדש.\u0004 ואם היו לו \u0003שלשה\u0004 — ה\u0003בינוני שבהם\u0004 ינתן \u0003ל\u0004\u0003הקדש.\u0004 האומר \"נדרתי להביא כבש (או שור) לקרבן, ו\u0003פירשתי\u0004 איזה כבש (או שור) הוא זה, ולאחר מכן שכחתי, \u0003ו\u0004עתה \u0003איני יודע מה ש\u0004\u0003פירשתי\u0004 בנדרי\", \u0003או ש\u0004אומר \u0003\"אמר לי אבא\u0004 לפני שמת כי הקדיש אחד מהכבשים (או השוורים), \u0003ו\u0004אולם \u0003איני יודע מה\u0004 הוא אותו כבש (או שור) שהקדיש\" — \u0003הגדול שבהן\u0004 ינתן ל\u0003הקדש.\u0004","שנינו במשנתנו כי המקדיש אחד מכבשיו (או משווריו), והיו לו שנים, הריהו מביא לקרבן את הגדול שבהם. ושואלים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 שאנו סבורים שכל ה\u0003מקדיש\u0004 — \u0003בעין יפה\u0004 (בנדיבות לב) הוא \u0003מקדיש,\u0004 ולכן אומרים כי הקדיש את הטובה שבבהמותיו. ואולם מעתה \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשנה\u0005]\u0006 כי אם היו לו שלושה, הריהו מביא את ה\u0003בינוני שבהן\u0004 ל\u0003הקדש, אלמא\u0004 \u0005[מכאן]\u0006 שאנו סבורים שכל ה\u0003מקדיש\u0004 — \u0003בעין רעה\u0004 (בצמצום) הוא \u0003מקדיש,\u0004 ולא הקדיש את הטובה שבבהמותיו!","\u0003אמר שמואל:\u0004 אנו סבורים שכל המקדיש בעין יפה הוא מקדיש, ובאשר לאמור בסוף משנתנו שהריהו נותן מהבינונית שבשלוש הבהמות — אין הכוונה שנותן רק את הבינונית, אלא הריהו נותן את היפה שבשלוש, וכן את הבינונית, משום ש\u0003חוששין\u0004 אנו \u0003אף לבינוני, דלגבי\u0004 \u0005[שבהשוואה]\u0006 ל\u0003קטן\u0004 — \u0003עין יפה הוא.\u0004 ומן הספק יתן את שתיהן.","ושואלים: עתה שספק הוא האם היתה דעתו ליפה שבהן או לבינונית, \u0003היכי עביד\u0004 \u0005[איך\u0006 הוא \u0005עושה,\u0006 כיצד נוהגים בפועל\u0005]?\u0006 \u0003אמר ר' חייא בר רב:\u0004 הריהו \u0003ממתין לו\u0004 לבינוני \u0003עד שיומם\u0004 (יפול בו מום), ואזי הריהו פודה אותו, \u0003ו\u0004בכך הריהו \u0003מחיל ליה לקדושתיה\u0004 \u0005[מחלל את קדושתו],\u0006 ונעשה חולין, והבהמה שהתחלל עליה מקודשת. ופדיון זה נעשה \u0003בגדול\u0004 מבין השלושה, והוא הקרב על המזבח. ומעתה, אם הבינוני הוא שהוקדש בתחילתו — הרי הועברה קדושתו זו לגדול. ואם לא היה זה הבינוני, אלא הגדול שהוקדש — הרי הגדול אכן קרב על המזבח, והקטן יוצא לחולין.","ועוד בדין זה ששנינו במשנה, שאם היו לו שלושה מביא את הבינוני, \u0003אמר רב נחמן, אמר רבה בר אבוה: לא שנו אלא\u0004 כש\u0003אמר\u0004 \u0003\"אחד משוורי הקדש\", אבל\u0004 אם \u0003אמר \"שור בשוורי הקדש\"\u0004 — \u0003הגדול שבהן הקדש.\u0004 שכן \u0003תורא בתוראי קאמר\u0004 \u0005[השור\u0006 ש\u0005בשוורי הוא אומר],\u0006 שכוונתו לשור המובחר בין השוורים.","ומקשים: \u0003איני\u0004 \u0005[כך הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא, אמר ר' חייא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: האומר לחבירו \"בית בביתי אני מוכר לך\"\u0004 — \u0003מראהו עלייה,\u0004 שהרי לא פירש איזה בית הוא מוכר. ומעתה יש לדון: \u0003לאו\u0004 \u0005[האם לא]\u0006 נותן לו את העליה \u0003משום\u0004 שהיא דבר \u0003ג\u0004 \u0003ריע\u0004 \u0005[גרוע]\u0006 ביותר. ומכאן, שאף האומר \"שור בשוורי\" (בדומה לאומר \"בית בביתי\") התכוין לגרוע שבשווריו! \u0005ומשיבים:\u0006 \u0003לא,\u0004 אין הכוונה ב\"עליה\" לעליית הבית, אלא הכוונה ב\"עליה\" ככינוי ל\u0003מעולה שבבתים.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על דברי רבה בר אבוה ממה ששנינו בברייתא: ה\u0005אומר\u0006 \u0003\"שור בשוורי\u0004 יהיה ל\u0003הקדש\", וכן שור של הקדש שנתערב באחרים,\u0004 וספק איזה הוא אותו שור, \u0003הגדול שבהן\u0004 יהיה \u0003הקדש\u0004 (שיוקדש לקרבן, שמא אין הוא הקרבן המקורי, ויוקרב), \u0003וכולם,\u0004 כל שאר הבהמות, \u0003ימכרו\u0004 לנודרי קרבן עולה \u0003לצרכי\u0004 הקרבת אותן \u0003עולות,\u0004 שהרי ספק הוא בכל אחת מהבהמות אם בהמת הקרבן היא, \u0003ו\u0004אילו \u0003ד\u0004\u0003מיהן\u0004 (הכסף שהתקבל עבורם) הריהו \u0003חולין.\u0004 הרי איפוא שגם באומר \"שור בשוורי\" ספק הוא בכולם!","ומשיבים: \u0003תרגומא\u0004 \u0005[תרגם,\u0006 הסבר\u0005]\u0006 שקביעה זו שהרי זה ספק בכל הבהמות, אמורה רק ב\u0003שור של הקדש שנתערב באחרים,\u0004 ולא באומר \"שור בשוורי\", שבכגון זה ודאי התכוון לגדולה שבבהמות. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 לשון \u0003\"וכן\" קאמר\u0004 \u0005[הוא אומר]\u0006 בברייתא, והרי זה מלמד שקביעה זו מתייחסת לשני המקרים\u0005! ומשיבים:\u0006 \u0003תרגומא\u0004 \u0005[תרגם,\u0006 הסבר\u0005]\u0006 לשון זו כמתייחסת רק ל\u0003גדול\u0004 שבשוורים, שנעשה הקדש בשני המקרים. ואולם הדין האחר האמור בברייתא (מכירת כל הבהמות לצרכי עולות בלבד, משום הספק), אינו מתייחס אלא למקרה של שור הקדש שהתערב באחרים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על דברי רבה בר אבוה ממה ששנינו בברייתא: המוכר לחבירו בית ואמר לו \u0003\"בית בביתי אני מוכר לך\", ונפל\u0004 אחד הבתים — \u0003מראהו\u0004 לקונה את הבית \u0003ה\u0004\u0003נפול\u0004 ואומר לו: \"בית זה קנית\". וכן המוכר עבד לחבירו, ואמר לו \u0003\"עבד בעבדיי אני מוכר לך\", ומת\u0004 אחד מעבדיו — \u0003מראהו\u0004 את העבד ה\u0003מת,\u0004 ואומר לו: \"עבד זה קנית\"."],["\u0003ו\u0004מעתה יש להקשות לשיטת רבה בר אבוה: \u0003אמאי ליחזי היידן\u0004 \u0005[מדוע מראה\u0006 המוכר ללוקח \u0005איזה]\u0006 בית ש\u0003נפל,\u0004 ואומר לו \"בית זה קנית\", וכן מדוע מראה \u0003היידן\u0004 \u0005[איזה]\u0006 עבד ש\u0003מת,\u0004 ואומר לו \"עבד זה קנית\", הרי לדעתו כאשר אמר \"בית בבתיי\" או \"עבד בעבדיי\" ודאי התכוון למשובח שבאותו מין ולא לאלה!","ותוהים על עצם שאלה זו: וכי מדין \u0003לוקח\u0004 (קונה) ומוכר \u0003קא אמרת\u0004 \u0005[אתה אומר]\u0006 להקשות על דברי רבה בר אבוה שאמר את דינו בענין הקדש?! \u0003שאני\u0004 \u0005[שונה]\u0006 הוא דין ה\u0003לוקח,\u0004 שהרי כלל הוא בדיני קניה ומכירה כי במקרה של ויכוח בין הקונה לבין המוכר באשר למה נכלל במכירה, \u0003יד בעל השטר\u0004 (הקונה, המחזיק בשטר המכירה) \u0003על התחתונה,\u0004 והוא מקבל את מה שאפשר לומר פחות בשטר.","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן],\u0006 לסברה זו, אם כן בדעת עולא שהאומר \"בית בביתי אני מוכר לך\", נותן לקונה עליה (שהובאה לעיל כקושיה על דברי רבה בר אבוה), ניתן לומר כי \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שכוונת דבריו ל\u0003עלייה\u0004 ממש (ולא כדרך שתירצנו שהוא כינוי למעולה שבבתיו), זו \u0003דגריעה\u0004 \u0005[שגרועה]\u0006 מכל בתיו — אין זו קושיה על רבה בר אבוה, שהרי גם שם טעם הדבר, הוא משום שבענייני מכירה \u0003יד בעל השטר על התחתונה.\u0004","האומר \u0003\"הרי עלי\u0004 להביא קרבן \u0003עולה\"\u0004 — \u0003יקריבנה ב\u0004בית ה\u0003מ\u0004\u0003קדש\u0004 אשר בירושלים. \u0003ואם הקריבה בבית חוניו\u0004 שבארץ מצרים — \u0003לא יצא\u0004 ידי חובתו. האומר \u0003\"הרי עלי עולה, שאקריבנה בבית חוניו\"\u0004 — \u0003יקריבנה במקדש, ו\u0004אולם \u0003אם\u0004 עמד ו\u0003הקריבה בבית חוניו\u0004 — \u0003יצא. ר' שמעון אומר:\u0004 זה האומר \"הרי עלי עולה שאקריבנה בבית חוניו\", אינו מחיל כלל קדושה, ולכך \u0003אין זו\u0004 הבהמה שהופרשה לכך בכלל קדושת \u0003עולה,\u0004 ונוהגים בה כבשאר בהמות חולין.","האומר \u0003\"הריני נזיר\"\u0004 — לאחר מלאות ימי נזירותו כראוי, \u0003יגלח\u0004 את שער ראשו \u0003ב\u0004בית ה\u0003מ\u0004\u0003קדש\u0004 אשר בירושלים, ומביא בו את קרבנותיו, כמפורש בדינו בתורה (במדבר ו, יג—יח). \u0003ואם\u0004 במלאות ימי נזירותו \u0003גלח\u0004 את שער ראשו \u0003בבית חוניו,\u0004 והביא בו את קרבנותיו — \u0003לא יצא\u0004 ידי חובתו, והריהו צריך לשוב ולגלח ולהביא קרבנותיו בבית המקדש בירושלים. האומר \u0003\"הריני נזיר\u0004 על מנת \u0003שאגלח בבית חוניו\"\u0004 — \u0003יגלח במקדש,\u0004 שאין תנאו שאמר שיגלח בבית חוניו נחשב. \u0003ו\u0004אולם \u0003אם\u0004 עמד ו\u0003גלח בבית חוניו,\u0004 וכפי שאמר בתנאו — \u0003יצא. ר' שמעון אומר:\u0004 כל האומר \"הריני נזיר שאגלח בבית חוניו\" אין זו לשון קבלת נזירות כלל, ולכך \u0003אין זה נזיר\u0004 כלל, ומותר הוא איפוא בשתיית יין ולהיטמא למתים.","שנינו במשנתנו שלדעת חכמים האומר \"הרי עלי עולה שאקריבנה בבית חוניו\", עליו להקריבה בבית המקדש שבירושלים, ואולם אם עבר והקריבה בבית חוניו — \u0003יצא\u0004 ידי חובת נדרו. ותוהים על כך: הרי כשאמר \"הרי עלי עולה\" — התחייב להקריבה כדינה בשחיטה ובשאר עבודות הקרבן שאחריה כראוי. ואילו זה, \u0003הא\u0004 \u0005[הרי]\u0006 כששחטה בבית חוניו לא שחטה כשחיטת הקרבן הראויה, שהרי שחטה מחוץ למקדש, ובכך בעצם \u0003מקטל קטלה\u0004 \u0005[הריגה הרג אותה]!\u0006","\u0003אמר רב המנונא:\u0004 הקדשה ראויה הקדיש האדם הזה, ואין כוונת הלשון \"יצא\" שיצא ידי נדרו (לפי שאכן הביא עולה כפי שנדר), אלא שיצא ידי חובתו מלהביא עולה אחרת. ואף שאמר בלשון \"הרי עלי\" וחייב להביאה כתיקנה, מכל מקום כיון שהוסיף ואמר \"שאקריבנה בבית חוניו\" — \u0003נעשה\u0004 בכך \u0003כאומר \"הרי עלי עולה, על מנת שלא אתחייב באחריותה\",\u0004 וכאילו אמר \"הרי עלי על מנת שאהרגנה\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב המנונא: \u0003אלא מעתה,\u0004 לפי דבריך, אף \u0003סיפא דקתני\u0004 \u0005[סוף\u0006 משנתנו, \u0005ששנה\u0006 בה\u0005]\u0006 שהאומר \u0003\"הריני נזיר\u0004 על מנת \u0003שאגלח\u0004 את השיער, ואביא את הקרבנות, ביום מלאת ימי נזירותי \u0003בבית חוניו\"\u0004 — \u0003יגלח\u0004 ויביא קרבנותיו \u0003במקדש, ואם גילח בבית חוניו\u0004 — \u0003יצא,\u0004 האם \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שפירוש הלשון \"יצא\" \u0003ש\u0004\u0003נעשה כאומר \"הריני נזיר, על מנת שלא אתחייב באחריות קרבנותיו\",\u0004 ומעתה אינו צריך להביא שוב את קרבנותיו ביום מלאת ימי נזירותו? והלא ה\u0003נזיר\u0004 כל \u0003כמה\u0004 (עוד) \u0003דלא מייתי\u0004 \u0005[שלא מביא]\u0006 את \u0003קרבנותיו\u0004 — \u0003לא מתכשר\u0004 (אינו יוצא מידי נזירותו, להיות מותר מאיסורי הנזיר)!","\u0003אלא אמר רבא\u0004 הסבר אחר: אין זו הקדשה ראויה, ולכך הבהמה שהביא בקרבנו אין בה כל קדושה, שכן \u0003אדם זה\u0004 האומר \"הרי עלי עולה שאקריבנה בבית חוניו\" כל עיקרו \u0003ל\u0004הבאת \u0003דורון\u0004 (מתנה) \u0003נתכוין,\u0004 ולא לקרבן ממש. שכך ודאי \u0003אמר\u0004 אדם זה (שמקומו קרוב יותר לבית חוניו מאשר לירושלים): \u0003אי סגיא\u0004 \u0005[אם די]\u0006 לי להביא את הבהמה הזו \u0003בבית חוניו\u0004 — \u0003טרחנא\u0004 \u0005[טורח אני]\u0006 ומביאה לשם. ואולם \u0003טפי\u0004 \u0005[יותר]\u0006 מכך, ללכת לירושלים לבית המקדש, ולהביאה לשם להקרבה — \u0003לא מצינא לאיצטעורי\u0004 \u0005[איני יכול להצטער]\u0006 כל כך. ונמצא איפוא כי לא היתה זו הקדשה לעולה של ממש. וכוונת משנתנו שראוי מלכתחילה שיעלנה לירושלים, ויקדישנה כראוי, ותוקרב בבית המקדש. ואולם אם לא עשה כן, אלא הקריבה בבית חוניו — יצא בכך ידי נדרו, ואין הוא צריך להביא קרבן אחר תחתיו.","וכן בזה האומר \u0003\"הריני\u0004 \u0003נזיר\u0004 שאגלח בבית חוניו\" \u0003נמי\u0004 \u0005[גם כן],\u0006 כל עיקרו של \u0003האי גברא\u0004 \u0005[זה האיש]\u0006 אינה לנזירות של ממש, אלא \u0003לצעורי נפשיה קא מיכוין\u0004 \u0005[לצער את עצמו,\u0006 בהימנעות משתיית יין ושאר איסורי הנזיר, \u0005הוא מתכוין].\u0006 ולכך \u0003אמר: אי סגיא\u0004 \u0005[אם דיה]\u0006 לקבלה זו שלי, שבסוף ימי הנזירות אגלח את שערי ואביא את קרבנותי \u0003בבית חוניו\u0004 — \u0003טרחנא\u0004 \u0005[טורח אני],\u0006 ומביא את קרבנותי לשם. ואולם \u0003טפי\u0004 \u0005[יותר]\u0006 מכך, ללכת לירושלים לבית המקדש, ולהביא שם את קרבנותי — \u0003לא מצינא לאיצטעורי\u0004 \u0005[איני יכול להצטער]\u0006 כל כך. וכוונת משנתנו שמלכתחילה יעלה לירושלים לבית המקדש, ויקדיש את קרבנותיו, ויגלח ויקריבם כראוי ביום מלאת ימי נזירותו. ואולם אם לא עשה כן, אלא גילח והקריב אותם בבית חוניו — יצא בכך ידי חובה, ואינו צריך לשוב ולהביאם.","ומעירים: \u0003ורב המנונא אמר לך\u0004 \u0005[\u0006יכול \u0005לומר\u0006 לך] כמענה לדברי רבא: בענין דברי משנתנו ב\u0003נזיר\u0004 שנדר לגלח בבית חוניו — אכן אפשר לומר \u0003כדקאמרת\u0004 \u0005[כמו שאמרת,\u0006 הסברת\u0005],\u0006 ואולם בענין דברי משנתנו בנודר \u0003עולה\u0004 להקריבה בבית חוניו — נשאר אני בהסברי, שטעם הדבר הוא משום ש\u0003על מנת שלא אתחייב\u0004 \u0003באחריותה קאמר\u0004 \u0005[הוא אמר].\u0006","\u0003ו\u0004מעירים: \u0003אף ר' יוחנן סבר לה להא\u0004 \u0005[סבור הוא כ\u0006הסברו \u0005זה]\u0006 של \u0003רב המנונא,\u0004 שכן \u0003אמר\u0004 \u0003רבה בר בר חנה, אמר ר' יוחנן:\u0004 האומר \u0003\"הרי עלי עולה שאקריבנה בבית חוניו\",\u0004 \u0003והקריבה בארץ ישראל\u0004 אך לא בבית המקדש — \u0003יצא. ו\u0004הריהו \u0003ענוש כרת\u0004 על הקרבה זו, שכן הוא שחט קדשים בחוץ. וכשיטת רב המנונא.","ומוסיפים: \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן\u0006 הסבורה \u0005כך,\u0006 כשיטתו של רב המנונא\u0005]:\u0006 האומר \u0003\"הרי עלי עולה שאקריבנה\u0004 \u0003במדבר\u0004 סיני\" (שכן סבור הוא שנותרה במדבר סיני עדיין קדושה בשל המשכן שהיה בו), \u0003והקריבה בעבר הירדן\u0004 — \u0003יצא, וענוש כרת\u0004 כמקריב קדשים בחוץ.","\u0003הכהנים ששמשו\u0004 (שעבדו) \u0003בבית חוניו\u0004 — \u0003לא ישמשו ב\u0004בית ה\u0003מקדש שבירושלים,\u0004 שנפסלו לעבודת הקודש בכך. \u0003ואין צריך לומר\u0004 כי כהנים ששימשו \u0003לדבר אחר\u0004 (עבודה זרה), שפסולים לעבוד בבית המקדש. וראיה לדבר, \u0003ש\u0004כן \u0003נ\u0004 \u0003אמר:\u0004 \u0003\"אך לא יעלו כהני הבמות אל מזבח ה' בירושלים כי אם אכלו מצות בקרב אחיהם\"\u0004 (מלכים ב כג, ט) — שנקבע בדינם של הכהנים שהקטירו בבמות אפילו לשם ה', שנפסלו מלעבוד במקדש, אולם הריהם מותרים באכילת מנחות וכן שאר קדשים, שלענין זה הריהם כשאר הכהנים (\"בתוך אחיהם\"). ו\u0003הרי אלו\u0004 נחשבים \u0003כ\u0004כהנים \u0003ב\u0004\u0003עלי מומין,\u0004 ש\u0003חולקין\u0004 (זכאים לקחת חלק בקרבנות) \u0003ואוכלין\u0004 מהם, אבל \u0003לא מקריבין.\u0004","שנינו במשנתנו כי אין כהני בית חוניו רשאים לעבוד בבית המקדש, ובודאי שכך דינו של כהן שעבד עבודה זרה (\"דבר אחר\"). ובעניינו של כהן זה \u0003אמר רב יהודה: כהן ששחט לעבודה זרה,\u0004 ולא הקריב לה, ולאחר מכן שב בתשובה — \u0003קרבנו\u0004 הקרב בבית המקדש לאחר מכן הריהו בכלל האמור בקרבנות \u0003ריח ניחוח,\u0004 שכשר הוא.","\u0003אמר רב יצחק בר אבדימי: מאי קראה\u0004 \u0005[מה\u0006 הוא \u0005המקרא]\u0006 המלמד על כך? — שכן נאמר: \"...כל בן נכר ערל לב וערל בשר לא יבוא אל מקדשי לכל בן נכר אשר בתוך בני ישראל. כי אם הלויים אשר רחקו מעלי בתעות ישראל אשר תעו מעלי אחרי גלוליהם ונשאו עוונם. והיו במקדשי משרתים פקודות אל שערי הבית ומשרתים את הבית המה ישחטו את העולה ואת הזבח לעם והמה יעמדו לפניהם לשרתם. \u0003יען אשר ישרתו אותם לפני גלוליהם והיו לבית ישראל למכשול עו‍ן על כן נשאתי ידי עליהם נאם ה' אלהים ונשאו עו‍נם\"\u0004 (יחזקאל מד, ט—יב), \u0003וכתיב בתריה\u0004 \u0005[ונאמר\u0006 בפסוק \u0005אחריו]:\u0006 \u0003\"ולא יגשו אלי לכהן לי\u0004 ולגשת על כל קדשי אל קדשי הקדשים...\". הרי למדנו מן הכתוב \"אשר ישרתו\" שרק \u0003אי עבד\u0004 \u0005[אם עשה]\u0006 הכהן עבודה שהיא בגדר \u0003שירות\u0004 לעבודה זרה — \u0003אין\u0004 \u0005[כן],\u0006 הריהו פסול לעבודה במקדש, אבל \u0003שחיטה לאו\u0004 \u0005[לא]\u0006 בכלל \u0003שירות הוא,\u0004 שהרי שחיטה נעשית גם בכל אדם, ובשל השחיטה בלבד אינו נפסל לעבודה במקדש.","ועוד בדיני כהן שעבד עבודה זרה, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו \u0005אמוראים בדינו של כהן ש\u0006\u0003שגג בזריקה\u0004 של דם הקרבן לעבודה זרה, האם קרבנו הקרב בבית המקדש כשר הוא. ש\u0003רב נחמן אמר: קרבנו\u0004 הריהו כשאר קרבנות כשרים, שנאמר בהם \u0003ריח ניחוח,\u0004 וכשר. ואילו \u0003רב ששת אמר\u0004 כי \u0003אין קרבנו\u0004 של כהן זה בכלל \u0003ריח ניחוח,\u0004 שפסול הוא להקריב.","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין,\u0006 מה המקור בתורה להלכה זו ש\u0005אני אומר אותה]\u0006 שאין קרבנו של השוגג בזריקה לעבודה זרה כשר — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדברי הנביא יחזקאל (המובאים למעלה) בדינם של \u0005אלה שעבדו עבודה זרה ובאים לעבוד במקדש:\u0006 \u0003\"והיו לבית ישראל למכשול עו‍ן\", מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא: \u0003או\u0004 זה שעבד עבודה זרה ב\u0003מכשול או\u0004 זה שעבד עבודה זרה ב\u0003עו‍ן\u0004 — אין עבודתם כשרה במקדש, \u0003ו\u0004הרי \u0003\"מכשול\"\u0004 — משמעו: עבירה ב\u0003שוגג, ו\"עו‍ן\"\u0004 — משמעו: עבירה ב\u0003מזיד.\u0004 נמצא שאף השוגג בעבודה זרה פסול לעבודה במקדש.","ושואלים: \u0003ורב נחמן\u0004 הסבור שקרבנו במקדש כשר, מה יענה על ראיה זו? ומשיבים: לדעתו לא כך הוא פירוש הדברים, אלא הכוונה היא לעבירה ב\u0003מכשול\u0004 של \u0003עו‍ן,\u0004 שרק העובד עבודה זרה במזיד הוא הפסול לעבודה במקדש, ולא זה העובד בשוגג.","\u0003אמר רב נחמן: מנא אמינא לה\u0004 \u0005[מנין,\u0006 מה המקור בתורה להלכה זו ש\u0005אני אומר אותה]\u0006 שקרבנו של השוגג בזריקה לעבודה זרה כשר? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור בשוגג בעבודה זרה: \"ואם נפש אחת תחטא בשגגה והקריבה עז בת שנתה לחטאת. \u0003וכפר הכהן על הנפש השגגת בחטאה\u0004 \u0003בשגגה\u0004 לפני ה' לכפר עליו ונסלח לו\" (במדבר טו, כז—כח), ומן הכתוב \"על הנפש השוגגת\" מובן כי אף נפשו שלו השוגגת ומביאה חטאת מתכפרת בקרבן, והרי כתוב זה \u0003מלמד\u0004 איפוא \u0003שכהן מתכפר\u0004 בקרבנותיו, אף \u0003על ידי\u0004 עבודתו בהם ב\u0003עצמו.\u0004","ומעתה נברר: \u0003במאי\u0004 \u0005[במה,\u0006 באיזה חטא עבודה זרה\u0005]\u0006 חטא בשגגה כהן זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ששגג \u0003בשחיטה\u0004 לעבודה זרה — \u0003מאי איריא\u0004 \u0005[מה שייך דווקא]\u0006 ב\u0003שוגג? אפילו מזיד נמי\u0004 \u0005[גם כן]\u0006 קרבנו כשר (וכדברי רב יהודה למעלה)! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ששגג \u0003בזריקה\u0004 לעבודה זרה, והרי נאמר בו שקרבנו כשר.","\u0003ורב ששת\u0004 הסבור שקרבנו פסול \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]\u0006 בדחיית ראיה זו: \u0003לעולם\u0004 מדובר בכהן ששגג \u0003בשחיטה\u0004 לעבודה זרה ולא בזריקה, ואף רב יהודה לא הכשיר את הכהן השוחט לעבודה זרה, אלא כשהיה שוגג בדבר, אבל אם היה מזיד הריהו פסול להקרבה. שטעמו של רב יהודה הוא משום שאין השחיטה נחשבת שירות, \u0003ו\u0004כי השוחט \u0003ב\u0004\u0003מזיד לא נעשה משרת לעבודה זרה?! ו\u0004מעירים כי רב נחמן ורב ששת","\u0003אזדו\u0004 \u0005[הולכים]\u0006 במחלוקתם זו \u0003לטעמייהו\u0004 \u0005[לטעמם,\u0006 לשיטתם\u0005]\u0006 בענין אחר, \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בדינו של הכהן ש\u0003הזיד בשחיטה\u0004 לעבודה זרה, ש\u0003רב נחמן אמר\u0004 כי \u0003קרבנו\u0004 שהקריב בבית המקדש הריהו בכלל \u0003ריח ניחוח,\u0004 ו\u0003כשר.\u0004 \u0003ו\u0004אילו \u0003רב ששת אמר\u0004 כי \u0003אין קרבנו ריח ניחוח,\u0004 שאינו כשר.","ומנמקים את שיטותיהם: \u0003רב נחמן אמר\u0004 כי \u0003קרבנו ריח ניחוח\u0004 — שהרי \u0003לא עבד\u0004 \u0005[לא עשה]\u0006 במעשהו זה עבודה שהיא בגדר \u0003\"שירות\",\u0004 שהשחיטה אינה בגדר \"שירות\". ואילו \u0003רב ששת אמר\u0004 כי \u0003אין קרבנו ריח ניחוח,\u0004"],["שאין השחיטה נחשבת כשירות אלא כאשר נעשתה בשוגג, ואולם כשנעשתה במזיד — הריהו \u0003נעשה\u0004 בכך \u0003משרת לעבודה זרה.\u0004 ומנמקים את שיטותיהם.","\u0003אמר רב נחמן: מנא אמינא לה\u0004 \u0005[מנין,\u0006 מה המקור בתורה להלכה זו ש\u0005אני אומר אותה]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כהן שעבד עבודה זרה, ושב\u0004 בתשובה, \u0003קרבנו\u0004 הקרב בבית המקדש הריהו \u0003ריח ניחוח,\u0004 מקובל ומרצה.","ויש לברר: \u0003במאי\u0004 \u0005[במה\u0006 עבד\u0005]\u0006 עבודה זרה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שעבד \u0003בשוגג\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 הענין\u0005]\u0006 שנאמר בברייתא \"שעבד עבודה זרה \u0003ושב\u0004 בתשובה\", והלא כהן זה \u0003שב ועומד הוא\u0004 (אדם כשר הוא מיסודו), שהרי לא התכוון לחטוא! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הוא שמדובר בברייתא זו שעשה הכהן כן \u0003במזיד. ו\u0004מעתה \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן שחטא הכהן במזיד \u0003בזריקה\u0004 של דם הקרבן לעבודה זרה — גם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003שב\u0004בתשובה על כך, \u0003מאי הוי\u0004 \u0005[מה נהיה,\u0006 מה בכך\u0005]?\u0006 עדיין פסול הוא \u0003להקרבה במקדש, שכן\u0004 \u0003הא עבד\u0004 \u0005[הרי עשה]\u0006 \u0003לה\u0004 לעבודה זרה \u0003שירות,\u0004 ונפסל על ידי כך! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן שעשה זאת \u0003בשחיטה.\u0004 ומכאן איפוא ראיה לשיטתי, שהשוחט במזיד אינו נפסל להקרבה במקדש.","\u0003ורב ששת אמר לך\u0004 \u0005[\u0006יכול \u0005לומר\u0006 \u0003לך]\u0004 בדחיית ראיה זו: \u0003לעולם\u0004 מדובר בשוחט לעבודה זרה \u0003בשוגג, ו\u0004אשר לשאלה כיצד תוסבר הלשון \"ושב\" באדם זה — \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זאת כוונת הדברים\u0005]:\u0006 \u0003אם\u0004 כהן זה \u0003שב מעיקרו\u0004 (שאדם כשר הוא מיסודו), בודאי \u0003דכי עבד\u0004 \u0005[ש\u0006אף \u0005שכאשר עשה]\u0006 דבר עבירה, ששחט לעבודה זרה — \u0003בשוגג עבד\u0004 \u0005[עשה]\u0006 כן, ולכך \u0003קרבנו ריח ניחוח, ו\u0004אולם \u0003אם לאו\u0004 \u0005[לא]\u0006 כן הוא אלא אינו כשר מעיקרו, ודאי אם שחט במזיד — \u0003אין קרבנו ריח ניחוח.\u0004","ועוד נחלקו רב נחמן ורב ששת בעניינים דומים. האחד, בדין קרבנו של כהן ש\u0003השתחוה לעבודה זרה\u0004 ואחר כך הקריב קרבן בבית המקדש, ש\u0003רב נחמן אמר\u0004 כי \u0003קרבנו ריח ניחוח,\u0004 מקובל ומרצה. \u0003ו\u0004אילו \u0003רב ששת אמר\u0004 כי \u0003אין קרבנו\u0004 של כהן זה \u0003ריח ניחוח.\u0004 והשני, בדין קרבנו של הכהן ש\u0003הודה\u0004 (שהצהיר בפיו) \u0003לעבודה זרה\u0004 כאלוהיו, שאף בזה \u0003רב נחמן אמר\u0004 ש\u0003קרבנו ריח ניחוח, ו\u0004אילו \u0003רב ששת אמר\u0004 בזה ש\u0003אין קרבנו ריח ניחוח.\u0004","ולאחר שהובאה מחלוקתם של רב נחמן ורב ששת במקרים שונים של עבודה לעבודה זרה (זריקה בשוגג, שחיטה במזיד, השתחויה, הודאה בפה), מסבירים כי \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמרנה כל המחלוקות הללו, \u0003דאי אשמעינן הך קמייתא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק את \u0005זו הראשונה,\u0006 זריקה בשוגג\u0005],\u0006 הייתי אומר כי דווקא \u0003בההיא קאמר\u0004 \u0005[באותה\u0006 עבודה \u0005אמר]\u0006 \u0003רב ששת\u0004 שאין קרבנו מתקבל, ו\u0003משום דעבד ליה\u0004 \u0005[שעשה לו]\u0006 \u0003שירות\u0004 לעבודה זרה, \u0003אבל\u0004 במקרה שרק עשה \u0003שחיטה\u0004 לעבודה זרה, \u0003דלא עבד ליה\u0004 \u0005[שלא עשה בה]\u0006 \u0003שירות\u0004 לעבודה זרה, אף שעשה כן במזיד — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 רב ששת \u0003לרב נחמן\u0004 שקרבנו מתקבל.","\u0003ו\u0004כן \u0003אי אשמעינן\u0004 \u0005[אם היה משמיע לנו]\u0006 את מחלוקתם רק בענין \u0003שחיטה\u0004 במזיד — הייתי אומר שרב ששת סבור שאין קרבנו מתקבל, \u0003משום דעבד ליה\u0004 \u0005[שעשה לו]\u0006 על כל פנים \u0003עבודה. אבל\u0004 במקרה ש\u0003השתחוה\u0004 לעבודה זרה, \u0003דלא עבד ליה\u0004 \u0005[שלא עשה לו]\u0006 \u0003עבודה\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 שאף לרב ששת קרבנו של כהן זה \u0003לא\u0004 נפסל. על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר אף מחלוקתם בענין השתחואה לעבודה זרה.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 את מחלוקתם רק בענין \u0003השתחואה\u0004 — הייתי אומר שרב ששת סבור שאין קרבנו מתקבל, \u0003משום דעביד ליה\u0004 \u0005[שעשה לו]\u0006 \u0003מעשה\u0004 (של השתחואה), \u0003אבל\u0004 אם רק \u0003הודה\u0004 בפיו לעבודה זרה, \u0003דדיבורא בעלמא\u0004 \u0005[שדיבור בלבד]\u0006 הוא זה, ולא מעשה — \u0003אימא\u0004 \u0005[אמור]\u0006 שאף לדעת רב ששת \u0003לא\u0004 ייפסל קרבנו. על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 להיאמר אף אופן זה של מחלוקתם.","שנינו במשנתנו כי הכהנים ששימשו בבית חוניו פסולים לעבודה בבית המקדש שבירושלים, \u0003ו\u0004הוסיפה המשנה כי \u0003אין צריך לומר\u0004 שכך הוא דינם של הכהנים ששימשו ל\u0003דבר אחר\u0004 (עבודה זרה). ודנים בדברים הללו: \u0003מדקאמר\u0004 \u0005[מ\u0006מה \u0005שהוא אומר]\u0006 כי \u0003אין צריך לומר\u0004 שכך הוא הדין בכהן ששימש ל\u0003דבר אחר, מכלל\u0004 כך ניתן ללמוד \u0003ש\u0004\u0003בית חוניו\u0004 עצמו — \u0003לאו\u0004 \u0005[לא]\u0006 בית \u0003עבודה זרה הוא.\u0004","ומעירים: וכמו כן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 הסבורה \u0003כ\u0004שיטת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003בית חוניו לאו\u0004 \u0005[לא]\u0006 בית \u0003עבודה זרה הוא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 המוסרת כיצד נוסד בית חוניו זה: \u0003אותה שנה שמת\u0004 בה \u0003שמעון הצדיק,\u0004 ששימש ככהן גדול, \u0003אמר להן\u0004 לחכמים: ב\u0003שנה זו הוא\u0004 (כלומר, אני) \u0003מת, אמרו לו: מנין אתה יודע\u0004 זאת?","\u0003אמר להן:\u0004 ב\u0003כל\u0004 שנה ושנה ב\u0003יום הכפורים,\u0004 כשנכנסתי לקודש הקדשים בסדר עבודת היום, \u0003נזדמן לי\u0004 מראה דמותו של \u0003זקן אחד\u0004 ה\u0003לבוש\u0004 בבגדים \u0003לבנים ונתעטף\u0004 ראשו ב\u0003לבנים, ו\u0004כשנכנסתי לקודש הקדשים היה \u0003נכנס עמי,\u0004 ושוהה עמי בעת עבודתי שם, \u0003ו\u0004לאחר מכן \u0003יצא עמי\u0004 אל מחוץ לקודש הקדשים. ואילו ב\u0003שנה זו נזדמן לי זקן אחד\u0004 ה\u0003לבוש\u0004 בבגדים \u0003שחורים ונתעטף\u0004 ב\u0003שחורים, ו\u0004בשעה שנכנסתי לקודש הקדשים אמנם \u0003נכנס עמי ו\u0004אולם בשעה שיצאתי מקודש הקדשים \u0003לא יצא עמי.\u0004","ואכן, מיד לאחר יום הכיפורים, \u0003לאחר הרגל\u0004 (חג הסוכות) \u0003חלה\u0004 שמעון הצדיק \u0003שבעת ימים, ומת. ו\u0004מעירים אגב כך, כי מאז פטירתו של שמעון הצדיק, חשו הכל שיש שינוי וירידה בדורות, \u0003נמנעו אחיו הכהנים מלברך\u0004 את ישראל ברכת כהנים \u0003בשם\u0004 המפורש (שהיו אומרים, כדרך הנאמרת עד עתה, בכינוי).","ושבים לענין יסודו של בית חוניו: \u0003בשעת פטירתו\u0004 של שמעון הצדיק, \u0003אמר להם\u0004 לחכמים בצוואה: \u0003חוניו בני ישמש\u0004 כהן גדול \u0003תחתי\u0004 (במקומי). \u0003נתקנא בו\u0004 בחוניו \u0003שמעי אחיו, ש\u0004כן \u0003היה גדול ממנו\u0004 מחוניו \u0003שתי שנים ומחצה.\u0004 הסתיר את קנאתו, ו\u0003אמר לו\u0004 בתחבולה על מנת להכשילו: \u0003בא ואלמדך סדר עבודה\u0004 של הכהן הגדול (שכן היה שמעי חכם ממנו). \u0003הלבישו\u0004 שמעי את חוניו \u0003באונקלי\u0004 (גלימה), \u0003וחגרו בצילצול\u0004 (חגורה מקושטת), \u0003העמידו אצל המזבח.\u0004 ואחר כך \u0003אמר להם\u0004 שמעי \u0003לאחיו הכהנים: ראו מה נדר זה ו\u0004אף \u0003קיים\u0004 את מה שנדר \u0003לאהובתו,\u0004 שכך אמר לה: \"ב \u0003אותו היום שאשתמש בכהונה גדולה\u0004 — \u0003אלבוש באונקלי שליכי\u0004 \u0005[שלך]\u0006 \u0003ואחגור בצילצול\u0004 \u0003שליכי\u0004 \u0005[שלך]\".\u0006","\u0003בקשו אחיו הכהנים להרגו\u0004 לחוניו, על בזיון הקודש, \u0003רץ\u0004 (ברח) \u0003מפניהם, ורצו אחריו,\u0004 עד ש\u0003הלך לאלכסנדריא של מצרים, ובנה שם מזבח, והעלה עליו\u0004 קרבנות \u0003לשום\u0004 (לשם) \u0003עבודה זרה. וכששמעו חכמים בדבר, אמרו: מה זה\u0004 (חוניו) \u0003ש\u0004עדיין \u0003לא ירד לה\u0004 (לא הגיע לכהונה גדולה), כיון שנלקחה ממנו — \u0003כך\u0004 קלקל, שהקים בית עבודה זרה. זה \u0003היורד לה\u0004 (שכבר הגיע לגדולה) — \u0003על אחת כמה וכמה\u0004 שהריהו מקלקל אם היא נלקחת ממנו. אלו \u0003דברי ר' מאיר.\u0004 ונמצא שלדעת ר' מאיר שימש בית חוניו מיסודו לעבודה זרה.","וממשיכה הברייתא כי \u0003אמר לו ר' יהודה\u0004 לר' מאיר: \u0003לא כך היה מעשה, אלא\u0004 שאף שציווה שמעון הצדיק כי חוניו הוא שיכהן תחתיו ככהן גדול, מכל מקום \u0003לא קיבל עליו חוניו\u0004 את התפקיד, משום \u0003שהיה שמעי אחיו גדול ממנו שתי שנים ומחצה,\u0004 ולכך נעשה שמעי לכהן גדול. \u0003ואף על פי כן\u0004 שחוניו עצמו לא רצה לשמש ככהן גדול, מכל מקום \u0003נתקנא בו חוניו בשמעי אחיו\u0004 על שהוא משמש ככהן גדול (שכן חוניו היה חכם ממנו), וביקש להכשילו. מה עשה? \u0003אמר לו\u0004 חוניו לשמעי: \u0003בא ואלמדך סדר עבודה\u0004 של כהן גדול. \u0003והלבישו באונקלי, וחגרו בצילצול, והעמידו אצל המזבח. אמר להם לאחיו הכהנים: ראו מה נדר זה וקיים לאהובתו, \"אותו היום שישתמש בכהונה גדולה\u0004 — \u0003אלבוש באונקלי שליכי\u0004 \u0005[שלך]\u0006 \u0003ואחגור בצילצול\u0004 \u0003שליכי\u0004 \u0005[שלך]\":\u0006","\u0003בקשו אחיו הכהנים להרגו\u0004 את שמעי על כך. עמד שמעי ו\u0003סח להם\u0004 לכהנים את \u0003כל המאורע\u0004 (שהוטעה לעשות כן על ידי חוניו). \u0003בקשו\u0004 הכהנים לפיכך \u0003להרוג את חוניו\u0004 שגרם לזה. \u0003רץ\u0004 חוניו \u0003מפניהם, ורצו אחריו. רץ לבית המלך, ורצו אחריו, כל הרואה אותו אומר: זה הוא, זה הוא,\u0004 שידעו מי הוא, ולא יכול היה להימלט שם. לפיכך \u0003הלך לאלכסנדריא של מצרים, ובנה שם מזבח, והעלה עליו לשם שמים.\u0004 לקיים מה שנאמר \u0003\"(והיה) ביום ההוא יהיה מזבח לה' בתוך ארץ מצרים ומצבה אצל גבולה לה' \"\u0004(שם יט). הרי שלדעת ר' יהודה שימש בית חוניו כבית לעבודת ה'.","\u0003וכששמעו חכמים בדבר, אמרו: ומה זה\u0004 חוניו \u0003שברח ממנה\u0004 (מן הכהונה הגדולה, שהרי בתחילה לא רצה בה), כל כך גברה קנאתו כשראה את אחיו משמש בה, עד שעשה \u0003כך\u0004 להכשיל את אחיו באופן כה חמור. זה \u0003המבקש לירד לה\u0004 (ועדיין לא הגיע לגדולה) — \u0003על אחת כמה וכמה\u0004 גדולה היא קנאתו במי שמשמש בגדולה זו.","ובעקבות דברי חכמים הללו באשר לתוצאותיה האפשריות של העלייה לגדולה, מביאים עוד מה ש\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהושע בן פרחיה: בתחלה כל האומר\u0004 לי \u0003\"עלה לה\u0004 לגדולה של נשיאות\" (שכן היה ר' יהושע בן פרחיה נשיא) — הרי \u0003אני כופתו ונותנו לפני הארי\u0004 מפני כעסי עליו, על הצעתו זו. ואולם, \u0003עתה\u0004 שהריני משמש בנשיאות, \u0003כל האומר לי לירד ממנה\u0004 — \u0003אני מטיל עליו קומקום של חמין,\u0004 מפני כעסי עליו, שכך היא טבעה של העליה לגדולה.","\u0003וראיה לדבר,\u0004 \u0003שהרי\u0004 מוצאים אנו כי \u0003שאול ברח ממנה\u0004 מן הגדולה, שלא רצה לשמש כמלך על ישראל (\"ויאמר ה' הנה הוא נחבא אל הכלים\". שמואל א י, כב), \u0003ו\u0004אולם \u0003כ\u0004\u0003שעלה\u0004 למלכות, וסבור היה כי עומד דוד ליטלה ממנה — \u0003בקש להרוג את דוד\u0004 (שם פרקים יח—כז).","למעלה הובא שלדעת ר' מאיר שימש בית חוניו לעבודה זרה ולדעת ר' יהודה שימש לעבודת ה', והביא ר' יהודה ראיה לדבריו מן הנאמר בנבואת ישעיהו על מצרים, שעתיד לקום בית לעבודת ה' במצרים. ובענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לאביי: ר' מאיר, האי קרא\u0004 \u0005[זה הפסוק]\u0006 שהביא \u0003ר' יהודה מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו,\u0006 כיצד הוא מפרש אותו\u0005]?\u0006","השיב לו אביי: מקרא זה מתפרש \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003לאחר מפלתו של\u0004 צבא \u0003סנחריב\u0004 מלך אשור שצר על ירושלים (מלכים ב פרקים יח—יט), \u0003יצא חזקיה\u0004 המלך אל מחוץ לירושלים \u0003ומצא\u0004 גויים \u0003בני מלכים\u0004 שהביא אתו סנחריב ממסעות כיבושיו, \u0003שהיו יושבין בקרונות של זהב,\u0004 ו\u0003הדירן\u0004 (הביא אותם לנדור) \u0003שלא לעבוד עבודה זרה,\u0004 והם קיימו את הנדר והתפזרו למקומותיהם, \u0003ש\u0004כן \u0003נאמר\u0004 באותה נבואת ישעיהו על מצרים: \u0003\"ביום ההוא יהיו חמש ערים בארץ מצרים מדברות שפת כנען\u0004"]]};
